(window.GIM_TS=window.GIM_TS||{})["Yevamot.6"]={"from":144,"a":[["\u0003ו\u0004הביכורים \u0003נוהגין בשאר שני שבוע,\u0004 כלומר, בכל השנים של מחזור השמיטה, ואילו מעשר שני אינו נוהג בשנה השלישית והשישית של השמיטה. \u0003ואין להם פדיון, מה שאין כן במעשר.\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ששנה ושייר.","וחוזרים לעצם הדיון בענין איסור ערל במעשר: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לשאלה זו ממה ששנינו: \u0003נשתיירו בו\u0004 בזה שנימול \u0003ציצין המעכבין את המילה — הרי זה אינו אוכל לא בתרומה, ולא בפסח, ולא בקדשים, ולא במעשר. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ל\u0003מעשר דגן,\u0004 והרי זה פתרון לשאלתנו, ודוחים: \u0003לא,\u0004 מעשר זה שאמרנו — \u0003מעשר בהמה\u0004 הוא.","ותוהים: \u0003מעשר בהמה היינו\u0004 \u0005[\u0006הרי \u0005זה]\u0006 \u0003קדשים,\u0004 ומדוע ידון בו לעצמו? ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003מי לא תנן\u0004 \u0005[האם לא שנינו]\u0006 \u0003פסח וקתני\u0004 \u0005[ושנינו]\u0006 גם \u0003קדשים!\u0004","ודוחים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003פסח וקדשים צריכי\u0004 \u0005[צריכים]\u0006 להיאמר לעצמם, ומדוע, \u0003דאי תנא\u0004 \u0005[שאילו\u0006 היה \u0005שונה]\u0006 רק \u0003פסח\u0004 הייתי אומר: \u0003משום\u0004 שפסול \u0003ערלות בפסח כתיבא\u0004 \u0005[נאמרה]\u0006 במפורש, \u0003אבל קדשים\u0004 שלא נאמר בהם הדבר — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא. ו\u0004להיפך: \u0003אי תנא\u0004 \u0005[אילו\u0006 היה \u0005שונה]\u0006 רק \u0003קדשים, הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003קדשים — פסח.\u0004 שנאסר במפורש לערל, אבל בשאר הקדשים אין פסול ערילות. \u0003אלא מעשר בהמה למה לי?\u0004 הלא הוא בכלל שאר הקדשים. ולכאורה ראיה היא שמעשר זה הוא מעשר שני!","ודוחים באופן אחר: \u0003אלא\u0004 הכוונה \"במעשר\" היא \u0003מעשר ראשון\u0004 הניתן ללויים, \u0003ו\u0004שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: מעשר ראשון אסור לזרים,\u0004 ואינו נאכל אלא ללויים בלבד. ושמא, כיון שאסור לזרים — אסור גם לערלים, ואין מכאן ראיה למעשר שני המותר לזרים.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה אחרת \u0003מדתני\u0004 \u0005[מ\u0006מה \u0005ששנה]\u0006 \u0003ר' חייא בר רב מדפתי\u0004 ברייתא זו: \u0003ערל אסור בשתי מעשרות.\u0004 ונברר, \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 שני מעשרות אלה הם \u0003אחד מעשר דגן ואחד מעשר בהמה!\u0004 ודוחים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הכוונה היא ל\u0003מעשר ראשון ו\u0004כדעת \u0003ר' מאיר,\u0004 כלומר, \"מעשר דגן\" הוא מעשר ראשון.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו: \u0003אונן אסור במעשר ומותר בתרומה ובפרה\u0004 אדומה. \u0003טבול יום,\u0004 מי שטבל לטהרתו ועדיין לא העריב שמשו — \u0003אסור בתרומה ומותר בפרה ובמעשר. מחוסר כפורים,\u0004 מי שחייב להביא קרבן לגמר טהרתו, כגון זב ומצורע, או יולדת ועדיין לא הביא קרבנו — \u0003אסור בפרה ומותר בתרומה ובמעשר. ואם איתא\u0004 \u0005[יש]\u0006 מקום להלכה זו — \u0003ניתני\u0004 \u0005[שישנה]\u0006 גם כן הבדל נוסף: \u0003ערל אסור בתרומה, ומותר בפרה ובמעשר!\u0004","ודוחים: \u0003האי תנא\u0004 \u0005[\u0006ה\u0005תנא\u0006 ה\u0005זה]\u0006 של ברייתא זו — שיטת תנא \u0003דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' עקיבא היא, דמרבי ליה\u0004 \u0005[ש\u0006היה \u0005מרבה אותו]\u0006 את ה\u0003ערל\u0004 שיהיה \u0003כטמא,\u0004 וכיון שהוא כעין טמא הריהו פסול אף לפרה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' עקיבא אומר: \"איש איש\u0004 מזרע אהרן והוא צרוע או זב בקדשים לא יאכל\u0003\"\u0004 (ויקרא כב, ד) — \u0003לרבות את הערל\u0004 לאיסור אכילת קדשים.","לגופו של דבר שואלים: \u0003ומאן תנא דפליג עליה\u0004 \u0005[ומי\u0006 הוא \u0005התנא שחולק עליו],\u0006 על \u0003ר' עקיבא —\u0004 ה\u0003תנא\u0004 של \u0003ר' יוסף הבבלי היא\u0004 (הוא). \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שרפת אונן ומחוסר כפורים\u0004 בפרה אדומה — \u0003כשרה,\u0004 והוא התנא החולק על ר' עקיבא שהרי ייחסנו את הברייתא הקודמת לר' עקיבא, ובה נאמר שגם מחוסר כיפורים פסול בפרה, ותנא זה מכשיר בו. \u0003ר' יוסף הבבלי אומר:\u0004 ב\u0003אונן — כשרה,\u0004 ב\u0003מחוסר כפורים — פסולה.\u0004","ומעירים לגופה של ההלכה: \u0003ואף ר' יצחק סבר\u0004 כי \u0003ערל אסור במעשר,\u0004 ש\u0003אמר ר' יצחק: מנין לערל שאסור במעשר — נאמר \"ממנו\" במעשר\u0004 (\"ולא בערתי ממנו בטמא\". דברים כו, יד), \u0003ונאמר \"ממנו\" בפסח\u0004 (כגון: \"אל תאכלו ממנו נא\". שמות יב, ט), \u0003מה \"ממנו\" האמור בפסח ערל אסור בו — אף \"ממנו\" האמור במעשר ערל אסור בו.\u0004","ומעירים: המלה \"ממנו\" בשני המקומות ודאי \u0003מופני\u0004 \u0005[מופנה,\u0006 מיותרת\u0005]\u0006 כדי ללמוד גזירה שווה, \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא מופני\u0004 \u0005[מופנה]\u0006 היא, \u0003איכא למיפרך\u0004 \u0005[יש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה באופן זה: \u0003מה לפסח שכן חייבין עליו משום פיגול ונותר וטמא\u0004 וחמור הוא הרבה ממעשר, ואין איפוא ללמוד מפסח לענין מעשר. \u0003לאיי אפנויי מופני\u0004 \u0005[על כן\u0006 בהכרח ש\u0005מופנה\u0006 הוא\u0005]\u0006 ולכן למדים בגזירה שווה זו של \"ממנו\".","ושואלים: \u0003מאי מופני\u0004 \u0005[מה\u0006 הוא ה\u0005מופנה\u0006 בזה\u0005]?\u0006 \u0003אמר רבא אמר ר' יצחק: תלתא\u0004 \u0005[שלוש\u0006 פעמים\u0005]\u0006 \u0003\"ממנו\" כתיבי\u0004 \u0005[נאמרו]\u0006 \u0003בפסח\u0004 (\"אל תאכלו ממנו נא\", \"ולא תותירו ממנו עד בוקר\", \"והנותר ממנו\". שמות יב, ט-י), והם נלמדים כך: \u0003חד לגופיה\u0004 \u0005[אחד לגופו,\u0006 לעצמו\u0005]\u0006 שלא יאכל ממנו, \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לגזירה שוה, וחד\u0004 \u0005[ואחד]\u0006 מהם בא לצורך אחר —","\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003בא הכתוב ליתן לך\u0004 מצות \u0003עשה\u0004 של חיוב שריפה (\"והנותר ממנו... באש תשרופו\") \u0003אחר לא תעשה\u0004 של \"לא תותירו\", אם כן \u0003איידי דכתיב\u0004 \u0005[כיון שנאמר]\u0006 שם \u0003\"נותר\" — כתיב נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003\"ממנו\", ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003ליתן לו בקר שני לשריפתו,\u0004 שאין שורפים את הנותר מן הפסח בבוקר הראשון לאחר זמנו שהוא יום טוב, אלא ממתינים לבוקר השני, חול המועד — אם כן \u0003איידי דכתיב\u0004 \u0005[מכיון שנאמר]\u0006 \u0003\"עד בקר\" כתיב נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003\"ממנו\".\u0004","וכן \u0003תלתא\u0004 \u0005[שלוש\u0006 פעמים\u0005]\u0006 \u0003\"ממנו\" כתיבי\u0004 \u0005[נאמרו]\u0006 \u0003במעשר\u0004 (\"לא אכלתי באוני ממנו ולא בערתי ממנו בטמא ולא נתתי ממנו למת\". דברים כו, יד): \u0003חד לגופיה\u0004 \u0005[אחד לגופו,\u0006 לעצמו\u0005],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 מלמד \u0003ל\u0004מה שאמר \u0003ר' אבהו אמר ר' יוחנן,\u0004 שבא הכתוב להתיר ביעור בשמן של תרומה טמאה, \u0003וחד\u0004 \u0005[ואחד]\u0006 מהם בא ללמד \u0003ל\u0004מה שאמר \u0003ריש לקיש.\u0004","ש\u0003אמר ריש לקיש אמר ר' סמיא: מנין למעשר שני שנטמא שמותר לסוכו\u0004 (לסוך בו) — \u0003שנאמר: \"ולא נתתי ממנו למת\"\u0004 (שם כו, יד) ונדייק: \u0003\"למת\" הוא\u0004 ש\u0003לא נתתי, הא\u0004 \u0005[הרי]\u0006 נתינה \u0003לחי דומיא\u0004 \u0005[בדומה]\u0006 לזו שנותנים ל\u0003מת — נתתי,\u0004 ו\u0003איזה דבר\u0004 ושימוש במעשר \u0003ששוה בחיים ובמתים — הוי אומר זו סיכה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר זוטרא: ואימא\u0004 \u0005[ואמור]\u0006 שהכוונה היא \u0003ליקח\u0004 (לקנות) \u0003לו\u0004 תמורתו \u0003ארון ותכריכים\u0004 שכיוצא בו בחי שהוא קונה לעצמו בגדים וכלים? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: \"ממנו\"\u0004 משמע \u0003מגופו\u0004 של מעשר, ולא דבר שמקבלים תמורתו. \u0003רב אשי אמר\u0004 תירוץ אחר: \u0003\"לא נתתי\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"לא אכלתי\", מה להלן\u0004 אכילה היא \u0003מגופו\u0004 של מעשר — \u0003אף כאן\u0004 נתינה היא \u0003מגופו.\u0004","על כל פנים שלושת \"ממנו\" הכתובים במעשר צריכים כל אחד לדרשה אחרת, ושואלים: \u0003ו\u0004אם כן \u0003אכתי\u0004 \u0005[\u0006ו\u0005עדיין]\u0006 \u0003מופנה מצד אחד הוא\u0004 ש\"ממנו\" אחד מופנה בפסח בלבד לגזירה שווה. \u0003הניחא למאן ד\u0004\u0003אמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 שמגזירה שווה המופנה אפילו מצד אחד \u0003למדין ואין משיבין\u0004 עליה, אף שיש להשיב ולדחות מפני טעם כלשהו. \u0003אלא למאן ד\u0004\u0003אמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי בגזירה שווה המופנה מצד אחד \u0003למדין ומשיבין, מאי איכא למימר\u0004 \u0005[מה\u0006 אם כן \u0005יש לומר]?\u0006 שהרי כפי שאמרנו יש מה להשיב על ההשוואה בין פסח ומעשר!","ומשיבים: \u0003הך\u0004 \u0005[זו]\u0006 ההלכה שאמר \u0003ר' אבהו\u0004 לענין ביעור בשמן תרומה — \u0003מ\u0004דברי \u0003רב נחמן אמר רבה בר אבוה נפקא\u0004 \u0005[יוצאת],\u0006 ש\u0003אמר רב נחמן אמר רבה בר אבוה: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"ואני הנה נתתי לך את משמרת תרומתי\"\u0004 (במדבר יח, ח) — \u0003בשתי תרומות הכתוב מדבר: אחת תרומה טהורה, ואחת תרומה טמאה,\u0004 שאת שתיהן צריך לשמור. \u0003ו\u0004מלשון הכתוב נלמד גם כן כי \u0003אמר רחמנא\u0004 \u0005[אמרה תורה]\u0006 \"נתתי \u0003לך\"\u0004 — משמעו: \u0003שלך תהא\u0004 (תהיה), ותרומה טהורה אוכל אותה ומשתמש בה לצרכיו, וטמאה — \u0003להסקה תחת תבשילך.\u0004 ומכאן שמותר לבער תרומה טמאה, ו\"ממנו\" שכתוב במעשר הוא מופנה, והרי כאן מופנה משני צדדים.","שנינו במשנה: \u0003וכל הטמאים\u0004 וכו' אסורים לאכול בתרומה, ושואלים: \u0003מנא הני מילי\u0004 \u0005[מניין דברים אלו]?\u0006 \u0003אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' ישמעאל: אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"איש איש מזרע אהרן והוא צרוע או זב\u0004 בקדשים לא יאכל\u0003\"\u0004 (ויקרא כב, ד), \u0003אי זהו דבר ששוה\u0004"],["\u0003בזרעו של אהרן,\u0004 שגם בניו וגם בנותיו אוכלים בשווה — \u0003הוי אומר זו תרומה.\u0004 ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003בחזה ושוק\u0004 של השלמים שגם אותם אוכלים כל זרע אהרן, זכרים ונקבות? ומשיבים: אין זה שווה בזרעו של אהרן, שכן \u0003אינה בחוזרת.\u0004 שאם בת כהן נישאה לישראל, ונפרדה מבעלה (בגט או באלמנות) בלא בנים, אף שחוזרת לאכול בתרומה, אינה אוכלת בחזה ושוק.","ומקשים: אם כן, \u0003תרומה נמי\u0004 \u0005[גם כן]\u0006 יש אופן שאינה אוכלת, שכן \u0003אינה בחללה!\u0004 ומשיבים: \u0003חללה לאו\u0004 \u0005[לא]\u0006 כ\u0003זרעו\u0004 של \u0003אהרן היא\u0004 נחשבת.","ושואלים על עיקר הדין שבברייתא שמחוסר כיפורים מותר בתרומה: \u0003וממאי דהאי\u0004 \u0005[וממה,\u0006 מניין יודע אתה, \u0005שזה,\u0006 מה שנאמר\u0005]\u0006 \u0003\"עד אשר יטהר\"\u0004 פירושו: \u0003עד דאיכא\u0004 \u0005[שיש]\u0006 \u0003הערב שמש, אימא\u0004 \u0005[אמור]:\u0006 \u0003עד דמייתי\u0004 \u0005[שיביא]\u0006 \u0003כפרה\u0004 ויהיה טהור טהרה גמורה?","ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך]\u0006 לומר כן, \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: בזב בעל שתי ראיות ובמצורע מוסגר\u0004 (ולא מוחלט) שהם טמאים אבל אינם צריכים להביא קרבן כפרה \u0003הכתוב מדבר, דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003\"טמא נפש\"\u0004 הנזכר בפסוק קודם, \u0003מה טמא נפש דלאו\u0004 \u0005[שאין]\u0006 \u0003בר כפרה הוא,\u0004 שאינו צריך להביא קרבן כפרה לטהרתו — \u0003הני נמי דלאו\u0004 \u0005[אלה,\u0006 זב ומצורע \u0005גם כן שלא]\u0006 \u0003בני כפרה נינהו\u0004 \u0005[הם]\u0006 וכגון זב בעל שתי ראיות ומצורע מוסגר, שנטהרים בהערב שמש בלבד.","ומקשים: \u0003ואימא, הני מילי\u0004 \u0005[ואמור\u0006 ש\u0005דברים אלה\u0006 אמורים\u0005]\u0006 במי \u0003דלאו בר\u0004 \u0005[שאינו בן]\u0006 \u0003כפרה\u0004 שאיננו חייב בקרבן כפרה, וזה די לו בהערב שמש, \u0003אבל\u0004 מי \u0003דבר\u0004 \u0005[\u0006מי \u0005ש\u0006הוא \u0005בן]\u0006 \u0003כפרה\u0004 וצריך קרבן לגמר טהרתו, שמא אינו אוכל בתרומה \u0003עד דמייתי\u0004 \u0005[שמביא]\u0006 \u0003כפרה?!\u0004","\u0003ותו\u0004 \u0005[ועוד],\u0006 \u0003הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003טבל ועלה\u0004 מן הטבילה — \u0003אוכל במעשר, העריב שמשו — אוכל בתרומה, הביא כפרה — אוכל בקדשים, מנא לן\u0004 \u0005[מניין לנו]\u0006 חילוקי הדינים הללו?","\u0003אמר רבא אמר רב חסדא: תלתא קראי כתיבי\u0004 \u0005[שלושה כתובים נאמרו]\u0006 לענין טהרה לקדשים; \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"ולא יאכל מן הקדשים כי אם רחץ בשרו במים\"\u0004 (ויקרא כב, ו), משמע \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003רחץ — טהור\u0004 מיד, ואוכל מיד אחר טבילה. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ובא השמש וטהר ואחר יאכל מן הקדשים\"\u0004 (שם ז), משמע שצריך הערב שמש. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכפר עליה הכהן וטהרה\"\u0004 (שם יב, ח), משמע שלפני הבאת קרבנה אין היולדת טהורה. \u0003הא כיצד? כאן למעשר, כאן לתרומה, כאן לקדשים.\u0004","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ואומר שמעשר יש להחמיר בו יותר? ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 לומר ש\u0003תרומה עדיפא\u0004 \u0005[עדיפה]\u0006 \u0003שכן\u0004 חומרות יתירות יש בה, שסימנן \u0003מחפ\"ז:\u0004 שטמא האוכלה חייב \u0003מ\u0004יתה, וזר האוכלה בשגגה חייב להוסיף עליה \u0003ח\u0004ומש, ואין לה \u0003פ\u0004דיון, ואסורה ל\u0003ז\u0004רים, מה שאין במעשר.","ושואלים שוב: \u0003אדרבה\u0004 (להיפך) \u0003מעשר עדיפא\u0004 \u0005[עדיף]\u0006 \u0003שכן הד\"ס ט\"ב:\u0004 שטעון \u0003ה\u0004באת מקום לירושלים, וצריך וי\u0003ד\u0004וי, וא\u0003ס\u0004ור לאונן, ואסור לבער ממנו ב\u0003ט\u0004ומאה, וחייב ב\u0003ב\u0004יעור, וכולם אינם בתרומה!","ומשיבים: \u0003אפילו הכי\u0004 \u0005[כך]\u0006 עונש \u0003מיתה\u0004 שיש בתרומה \u0003עדיפא\u0004 \u0005[עדיף],\u0006 ומראה שהיא חמורה יותר.","\u0003רבא אמר: בלא\u0004 הנימוק של \u0003מיתה עדיפא נמי לא מצית אמרת\u0004 \u0005[גם כן אינך יכול לומר\u0006 כך\u0005],\u0006 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפסוק הראשון המדבר על זה שנטהר בטבילה בלבד: \"נפש אשר תגע בו\" (שם כב, ו), ומהמלה \u0003\"נפש\",\u0004 למדים: \u0003איזהו דבר ששוה בכל נפש — הוי אומר זה מעשר,\u0004 מה שאין כן בתרומה שהיא לכהנים בלבד.","ומקשים על משנה זו אותה הקושיה: \u0003ואכתי, הני מילי היכא דלאו בר\u0004 \u0005[ועדיין דברים אלה\u0006 אמורים \u0005היכן שאיננו בן]\u0006 \u0003כפרה, אבל\u0004 שמא \u0003היכא דבר\u0004 \u0005[היכן ש\u0006הוא \u0005בן]\u0006 \u0003כפרה\u0004 כמו מצורע מוחלט — לא יאכל בתרומה \u0003עד דמייתי\u0004 \u0005[שיביא]\u0006 \u0003כפרה!\u0004","\u0003אמר אביי: תרי קראי כתיבי\u0004 \u0005[שני כתובים נאמרו]\u0006 \u0003ביולדת; כתיב\u0004 \u0005[נאמר]\u0006 בה: \u0003\"עד מלאת ימי טהרה\"\u0004 (שם יב, ד), משמע: \u0003כיון שמלאו ימיה\u0004 והעריב השמש של היום האחרון — \u0003טהרה,\u0004 ואינה צריכה תיקון אחר. \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"וכפר עליה הכהן וטהרה\"\u0004 (שם ח), הרי שעדיין צריכה לכפרה?! \u0003הא כיצד? כאן\u0004 שדי לה בהערב שמש — \u0003לתרומה, כאן\u0004 שצריכה בנוסף לכך כפרה — \u0003לקדשים.\u0004 ויולדת הרי היא מחוסרת כפרה, ומשמע שלאכילת תרומה די לה בהערב שמש!","ומקשים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ונחמיר בתרומה יותר! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003קדש חמור, שכן\u0004 יש בו חומרות יתירות שסימנן \u0003פנקעכ\"ס:\u0004 יש בו דין \u0003פ\u0004 יגול, ודין \u0003נ\u0004 ותר, והוא \u0003ק\u0004 רבן לה', וחייבים עליו קרבן מ\u0003ע\u0004 ילה, וחייבים עליו \u0003כ\u0004רת כשאוכלן בטומאת הגוף, וא \u0003ס\u0004 ור לאונן.","ושואלים שוב: \u0003אדרבה\u0004 (להיפך) \u0003תרומה חמורה, שכן\u0004 יש בה חומרות שסימנן \u0003מחפ\"ז\u0004 (\u0003מ\u0004יתה, \u0003ח\u0004 ומש, \u0003פ\u0004 דיון, \u0003ז\u0004 ר)!","ומשיבים: \u0003הנך נפישן\u0004 \u0005[אלה\u0006 הנימוקים להחמיר בקדשים \u0005מרובים].\u0006 \u0003רבא אמר:\u0004 גם \u0003בלא\u0004 הטעם של \u0003הנך נפישן\u0004 \u0005[אלה מרובים]\u0006 \u0003לא מצית אמרת\u0004 \u0005[אינך יכול לומר]\u0006 שהפסוק המטהרה מיד נאמר בקדשים, שהרי \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכפר עליה הכהן וטהרה\" — מכלל\u0004 הדברים אתה למד \u0003שהיא טמאה\u0004 במידה מסויימת עד הבאת הקרבן, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר ש\u0003בקדשים\u0004 מותר מיד בהערב שמש, הלא \u0003איקרי כאן\u0004 \u0005[קרא כאן]\u0006 את האמור בפסוק אחר: \u0003\"והבשר אשר יגע בכל טמא לא יאכל\"\u0004 (שם ז, יט), משמע שכל דבר שיש בו עדיין כל טומאה אוסר בקדשים. \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שמדובר שם \u0003בתרומה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: ומי מצית אמרת\u0004 \u0005[והאם יכול אתה לומר]\u0006 כי \u0003תרומה כתיבא הכא\u0004 \u0005[נאמרה כאן]\u0006 בכתוב של \"עד מלאת ימי טהרה\"? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 נאמר בתחילת דיני הלידה: \u0003\"דבר אל בני ישראל\"\u0004 (שם יב, ב), ודרשו: \u0003אין לי אלא בני ישראל\u0004 — \u0003גיורת ושפחה משוחררת מנין? תלמוד לומר: \"אשה\"\u0004 מכל מקום. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שמדובר כאן \u0003בתרומה,\u0004 וכי \u0003גיורת ושפחה בנות מיכל\u0004 \u0005[אכילת]\u0006 \u0003תרומה נינהו\u0004 \u0005[הן]?\u0006 הלא הן אסורות לכהן, ואין דרך איפוא שתאכלנה תרומה!","\u0003אמר רבא: ו\u0004כי \u0003לא\u0004 מדבר הכתוב גם בתרומה?"],["\u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 שם בפרשת היולדת: \u0003\"בכל קדש לא תגע\"\u0004 (ויקרא יב, ד) — \u0003לרבות התרומה\u0004 שהיא נלמדת מן הריבוי \"כל קודש\". \u0003אלא קרא, מילי מילי קא חשיב\u0004 \u0005[הכתוב, דברים דברים מונה],\u0006 כל אחד לעצמו ולא כולם מדברים בענין תרומה.","ושואלים: \u0003ותלתא קראי\u0004 \u0005[ושלושה כתובים]\u0006 \u0003בתרומה למה לי?\u0004 ומשיבים: \u0003צריכי\u0004 \u0005[נצרכו]\u0006 כולם. \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003מ\"עד אשר יטהר\"\u0004 (שם כב, ד) בלבד, \u0003לא הוה ידענא במאי\u0004 \u0005[היינו יודעים במה]\u0006 צריכה להיות הטהרה, אם בטבילה בלבד או באופן אחר, ולכן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"ובא השמש וטהר\"\u0004 (שם ז), לומר שצריך גם הערב שמש.","\u0003ואי כתב רחמנא\u0004 \u0005[ואילו אמרה התורה]\u0006 רק \u0003\"ובא השמש\",\u0004 הייתי אומר: \u0003הני מילי דלאו בר\u0004 \u0005[דברים אלה\u0006 אמורים במקרה \u0005שאינו בן]\u0006 \u0003כפרה, אבל דבר\u0004 \u0005[\u0006מי \u0005ש\u0006הוא \u0005בן]\u0006 \u0003כפרה אימא\u0004 \u0005[אמור]\u0006 שאינו נטהר \u0003עד דמייתי\u0004 \u0005[שיביא]\u0006 \u0003כפרה\u0004 \u0005—\u0006 \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"עד מלאת\u0004 ימי טהרה","\u0003\"\u0004(שם יב, ד), שעם מלאת הימים טהורה לתרומה, ואינה צריכה קרבן כפרה. \u0003ואי כתב רחמנא\u0004 \u0005[ואילו אמרה התורה]\u0006 רק \u0003\"עד מלאת\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שנטהרת מיד כאשר עברו ימי הטומאה \u0003אפילו בלא טבילה\u0004 — \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]:\u0006 \u0003\"עד אשר יטהר\".\u0004","ושואלים: \u0003ולהך תנא דפליג עליה דתנא דבי\u0004 \u0005[ולתנא זה החולק עליו,\u0006 על \u0005התנא של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל,\u0004 ש\u0003אמר\u0004 כי \u0003בזב בעל שלש ראיות ובמצורע מוחלט הכתוב מדבר,\u0004 שצריכים להביא קרבן כשנטהרים, \u0003ו\u0004אם כן \u0003האי\u0004 \u0005[וזה]\u0006 הכתוב \u0003\"עד אשר יטהר\"\u0004 יש איפוא לפרשו: \u0003עד דמייתי\u0004 \u0005[שיביא]\u0006 \u0003כפרה,\u0004 ואם כן \u0003תרי קראי\u0004 \u0005[שני כתובים]\u0006 \u0003בקדשים\u0004 שצריכים טהרה אף בקרבן \u0003למה לי?\u0004","ומשיבים: \u0003צריכי\u0004 \u0005[צריכים\u0006 הם\u0005],\u0006 \u0003דאי כתב רחמנא\u0004 \u0005[שאם\u0006 היתה \u0005אומרת התורה]\u0006 רק \u0003ביולדת\u0004 — הייתי אומר \u0003משום\u0004 ש\u0003מרובה טומאתה\u0004 שנמשכת ימים רבים, \u0003אבל בזב אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא, ואי כתב רחמנא\u0004 \u0005[ואם\u0006 היתה \u0005אומרת התורה]\u0006 \u0003בזב,\u0004 הייתי אומר שזב חמור, מפני ש\u0003לא הותר מכללו,\u0004 שהרי טומאתו היא לכל ענין ואין לה צד היתר, \u0003אבל יולדת\u0004 שמותרת וטהורה לבעלה בתוך הזמן הזה בימי טהרה, \u0003אימא\u0004 \u0005[אמור\u0006 ש\u0003לא,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 את שניהם.","ושואלים: אם כן, הכתוב האמור בדבר הנטמא בשרץ \u0003\"במים יובא וטמא עד הערב\u0004 וטהר\u0003\"\u0004 (שם יא, לב) \u0003למה לי? אמר ר' זירא: לנגיעה,\u0004 שעד שלא היה הערב שמש לא רק שאסור באכילת תרומה, אלא גם מטמא אותה בנגיעה.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 נאמר: \u0003\"וטמא\" — יכול\u0004 יהיה טמא עד הערב \u0003לכל, תלמוד לומר: \"וטהר\",\u0004 משמע שכבר נטהר מקודם להערב שמש לאחר שטבל. \u0003אי\u0004 \u0005[אם]\u0006 \u0003\"וטהר\" — יכול לכל, תלמוד לומר: \"וטמא\". הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניישב את הסתירה? \u0003כאן — למעשר,\u0004 שנטהר בטבילה בלבד, \u0003כאן — לתרומה,\u0004 צריך הערב שמש.","ושואלים: \u0003ואיפוך אנא\u0004 \u0005[ואהפוך אני]\u0006 ואומר שיש להחמיר יותר במעשר! ומשיבים: \u0003מסתברא כי היכי דחמירא\u0004 \u0005[מסתבר כמו שחמורה]\u0006 \u0003אכילה\u0004 של \u0003תרומה מאכילה\u0004 של \u0003מעשר — הכי נמי\u0004 \u0005[כך גם כן]\u0006 \u0003חמירא\u0004 \u0005[חמורה]\u0006 ה\u0003נגיעה\u0004 ב\u0003תרומה מנגיעה\u0004 ב\u0003מעשר.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 \u0003נגיעה\u0004 ב\u0003תרומה מהכא נפקא\u0004 \u0005[מכאן\u0006 היא \u0005יוצאת,\u0006 נלמדת\u0005],\u0006 שנאמר: \u0003\"בכל קדש לא תגע\"\u0004 (שם יב, ד) — הרי זו \u0003אזהרה לאוכל\u0004 בטומאה. \u0003או אינו אלא לנוגע,\u0004 כפשוטו?","\u0003תלמוד לומר: \"בכל קדש לא תגע ואל המקדש לא תבא\"\u0004 (שם), \u0003מקיש\u0004 (משווה הכתוב) \u0003קדש למקדש, מה מקדש\u0004 מדובר במקרה שעושה \u0003דבר שיש בו נטילת נשמה,\u0004 כלומר, שענוש כרת על עבירה זו, \u0003אף קדש — דבר שיש בו נטילת נשמה,\u0004 כגון אכילת קודש בטומאה, \u0003ובנגיעה\u0004 בטומאה \u0003נטילת נשמה ליכא\u0004 \u0005[אין],\u0006","\u0003והאי דאפקיה\u0004 \u0005[וזה שהוציאו],\u0006 שביטא הכתוב את הדבר \u0003בלשון נגיעה — הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003נגיעה\u0004 דינה \u0003כאכילה,\u0004 שגם היא אסורה לטמא עד הערב שמש, אבל עיקרו של הכתוב הוא באכילה בטומאה.","שנינו במשנה שכהן שהוא \u0003פצוע דכא\u0004 וכרות שפכה, שלא בא על אשתו, הרי היא אוכלת מכוחו בתרומה, ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 הסבור כי ה\u0003משתמרת לביאה פסולה,\u0004 כלומר, מקודשת לאדם שביאתו פוסלת אותה, \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003אכלה\u0004 \u0005[אוכלת]\u0006 בתרומה? \u0003אמר ר' אלעזר: במחלוקת שנויה\u0004 הלכה זו \u0003ו\u0004שיטת \u0003ר' אלעזר ור' שמעון היא\u0004 (לעיל יבמות נו, ב), שאמרו כעין זה באלמנה המאורסת לכהן גדול, שכל עוד לא בא עליה אוכלת בתרומה בגללו.","\u0003ר' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהיא כשיטת \u0003ר' מאיר\u0004 שם, הפוסל באלמנה, ובכל זאת \u0003שאני הכא\u0004 \u0005[שונה כאן],\u0006 \u0003שכבר אכלה\u0004 בתרומה, לפני שנעשה פצוע דכא. וכיון שלא נעשה בה מעשה לפוסלה הריהי בחזקתה לאכילת תרומה.","\u0003ו\u0004אילו \u0003ר' אלעזר\u0004 סבור כי הנימוק \u0003שכבר אכלה — לא אמרינן\u0004 \u0005[אין אנו אומרים],\u0006 \u0003דאי לא תימא הכי\u0004 \u0005[שאם אין אתה אומר כן]\u0006 שאין ממש בנימוק זה, \u0003בת ישראל שנשאת לכהן, ומת בעלה\u0004 בלי להשאיר צאצאים \u0003תאכל\u0004 בתרומה מכוחו מפני \u0003שכבר אכלה\u0004 בחייו, והרי מפורש בכתוב שאינו כן. משמע, שהעובדה שכבר אכלה אינה מתירה אותה.","\u0003ור' יוחנן\u0004 סבור שאין הדברים שווים: \u0003התם\u0004 \u0005[שם]\u0006 כשמת הבעל — \u0003פקע קנייניה\u0004 \u0005[קניינו]\u0006 של הבעל בה כשמת ולכך אינה יכולה לאכול עוד מכוחו, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 כשנעשה פצוע דכא — \u0003לא פקע קנייניה\u0004 \u0005[קניינו]\u0006 ואף שבעילתו אסורה, נישואיו לא בטלו.","שנינו במשנה \u0003איזהו פצוע\u0004 דכא. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו פצוע דכא — כל שנפצעו ביצים שלו, ואפילו אחת מהן. ו\u0004לא רק נפצעו, אלא \u0003אפילו ניקבו, ואפילו נמוקו\u0004 (נרקבו מחמת מכה), \u0003ואפילו חסרו\u0004 משהו מחמת סיבה אחרת. \u0003אמר ר' ישמעאל בנו של ר' יוחנן בן ברוקה: שמעתי מפי חכמים בכרם ביבנה: כל שאין לו אלא ביצה אחת — אינו אלא סריס חמה, וכשר.\u0004","ותוהים על הלשון: \u0003סריס חמה סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 הרי זה איננו סריס חמה, שהרי לא נולד כך אלא לאחר זמן נפגע! \u0003אלא\u0004 כך יש לומר: \u0003הרי הוא כסריס חמה, וכשר.\u0004","ושואלים: \u0003ו\u0004כי זה ש\u0003ניקב\u0004 בביצים \u0003לא מוליד,\u0004 ולכן נחשב כפצוע דכא? \u0003והא ההוא גברא דסליק לדיקלא\u0004 \u0005[והרי\u0006 מעשה ב\u0005אדם אחד שעלה לדקל]\u0006"],["\u0003וחרזיה סילוא\u0004 \u0005[ונקבו קוץ\u0006 מן הדקל\u0005]\u0006 \u0003בביצים, ונפק מיניה\u0004 \u0005[ויצא ממנו]\u0006 \u0003כחוט דמוגלא\u0004 \u0005[של מוגלה],\u0006 שבקע הקוץ עד לתוך האשך, \u0003ואוליד\u0004 \u0005[והוליד]\u0006 בנים! ומשיבים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שלח שמואל\u0004 מקרה זה \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב ואמר ליה\u0004 \u0005[לו]:\u0006 \u0003צא חזר\u0004 (חפש) \u0003על בניו מאין הם,\u0004 שלא האמין שאיש זה מסוגל להוליד, והבנים האלה הם בניו, אלא ודאי זנתה אשתו, והבנים הם מאחר.","\u0003אמר רב יהודה אמר שמואל: פצוע דכא בידי שמים\u0004 (מחמת מחלה) \u0003כשר. אמר רבא: היינו דקרינן\u0004 \u0005[זהו שאנו קוראים\u0006 בכתוב\u0005]\u0006 \u0003\"פצוע\" ולא קרינן\u0004 \u0005[ואין אנו קוראים]\u0006 \u0003\"הפצוע\",\u0004 ש\"הפצוע\" משמעו כל מי שיש בו מום זה מלידה, ואילו \"פצוע דכא\" משמעו רק המקרה המסויים של פציעה ממש.","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 מעין זה, \u0003נאמר: \"לא יבא פצוע\u0004 דכה\u0003\"\u0004 (דברים כג, ב) \u0003ונאמר\u0004 סמוך לזה \u0003\"לא יבא ממזר\"\u0004 (שם ג), \u0003מה להלן\u0004 בממזר — הרי הוא מום שנוצר \u0003בידי אדם\u0004 (הוריו שחטאו), \u0003אף כאן\u0004 פצוע דכא הוא \u0003בידי אדם.\u0004","\u0003אמר רבא: פצוע\u0004 הוא \u0003בכולן,\u0004 הן בביצים הן בגיד, \u0003דך\u0004 (שנמעך) — \u0003בכולן, כרות\u0004 — הרי הוא \u0003בכולן.\u0004 ומפרט: \u0003פצוע בכולן; בין שנפצע הגיד, בין שנפצעו ביצים, בין שנפצעו חוטי ביצים\u0004 (צינורות הזרע). וכן \u0003דך בכולן; בין שנידך הגיד, בין שנידכו ביצים, בין שנידכו חוטי ביצים. כרות בכולן — בין שנכרת הגיד, בין שנכרתו ביצים, בין שנכרתו חוטי ביצים.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003לרבא: ממאי דהאי\u0004 \u0005[ממה,\u0006 מניין יודעים אנו, \u0005שזה]\u0006 \u0003פצוע דכא\u0004 הוא \u0003באותו מקום,\u0004 באבר המין? \u0003אימא\u0004 \u0005[אמור]\u0006 שפצוע \u0003מראשו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מ\u0004כיון ש\u0003לא מנה ביה\u0004 \u0005[בו]\u0006 \u0003דורות,\u0004 כמה דורות אסורים לבוא בקהל ממנו (כמו שאמרה התורה בעמוני מואבי וממזר), \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי המובן הוא \u0003באותו מקום,\u0004 שזהו פגם הגורם שלא יהיה מסוגל להוליד ולכן אין לו דורות היוצאים ממנו.","ושואלים: \u0003ודלמא האי\u0004 \u0005[זה]\u0006 ש\u0003לא מנה בו דורות\u0004 הוא מטעם הלכתי: \u0003דאיהו\u0004 \u0005[שהוא]\u0006 \u0003הוא\u0004 ש\u0003אסור,\u0004 ואולם \u0003בריה ובר בריה\u0004 \u0005[בנו ובן בנו]\u0006 \u0003כשר?\u0004","ומשיבים, שהלימוד בדרך אחרת: \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003כרות שפכה, מה כרות שפכה — באותו מקום,\u0004 שממנו נשפך הזרע \u0003אף האי נמי\u0004 \u0005[אף זה,\u0006 פצוע דכא, \u0005גם כן]\u0006 \u0003באותו מקום.\u0004","ושואלים: \u0003וכרות שפכה גופיה\u0004 \u0005[עצמו]\u0006 \u0003ממאי\u0004 \u0005[ממה]\u0006 יודע אתה שפגם \u0003באותו מקום הוא? אימא משפתיה\u0004 \u0005[אמור משפתיו]\u0006 שהרי גם משם נשפך רוק! ומשיבים: \u0003\"שפכה\" כתיב\u0004 \u0005[נאמר]\u0006 — \u0003במקום ששופך\u0004 (שותת) ולא שיוצא בזריקה.","ומקשים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 \u0003מחוטמו?\u0004 ומשיבים: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"בשפוך\"\u0004 במקום שלעיתים שופך בלי כריתה? \u0003\"כרות שפכה\" כתיב\u0004 \u0005[נאמר]\u0006 \u0003מי שעל ידי כריתה שופך,\u0004 אבל \u0003שלא על ידי כריתה — אינו שופך אלא מקלח\u0004 בזינוק, \u0003לאפוקי האי\u0004 \u0005[להוציא\u0006 למעט את \u0005זה]\u0006 החוטם, \u0003דאידי ואידי\u0004 \u0005[שזה וזה\u0006 בין כרות בין אינו כרות\u0005]\u0006 \u0003שופך הוא.\u0004","\u0003במתניתא תנא\u0004 \u0005[בברייתא שנה]\u0006 בענין זה, \u0003נאמר: \"לא יבא פצוע דכה\"\u0004 (שם ב) \u0003ונאמר: \"לא יבא ממזר\"\u0004 (שם ד), \u0003מה להלן\u0004 הממזרות שייכת \u0003באותו מקום,\u0004 כלומר, בענין של מין, \u0003אף כאן באותו מקום\u0004 השייך למין.","ודנים במקרה מסויים: \u0003ניקב\u0004 באבר \u0003למטה מעטרה,\u0004 וממשיך הנקב עד \u0003שכנגדו\u0004 (מולו), והצד האחר היה \u0003למעלה מעטרה, סבר ר' חייא בר אבא לאכשורי\u0004 \u0005[להכשירו]\u0006 שסבר שנקב במקום עטרה אוסר רק אם כולו במקום העטרה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אסי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר ר' יהושע בן לוי: עטרה כל שהיא\u0004 ללא נקב \u0003מעכבת.\u0004 כלומר, גבול ההיתר הוא רק כשהנקב במקום העטרה בלבד ולא כנגדו, ומכיון שעובר עד למעלה על כל אורכה של העטרה, ודאי שהוא מאבד את בכך כושר ההולדה.","שנינו במשנה: \u0003ואם נשתייר מעטרה\u0004 כמלא חוט — כשר. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבינא וקמיבעיא ליה\u0004 \u0005[ונסתפק לו]\u0006 בבעיה זו: \u0003מלא החוט שאמרו, על פני כולה או על פני רובה? אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא תוספאה\u0004 (בעל התוספתא) \u0003לרבינא: מלא החוט\u0004 שאמרו — הכוונה \u0003על פני רובה, וכלפי רישא,\u0004 כלומר, דווקא בחלק שהוא כלפי ראשו, כלפי הגוף.","\u0003אמר רב הונא:\u0004 אם נחתך הגיד \u0003כקולמוס\u0004 שהוא מחודד מכל צד — \u0003כשרה,\u0004 ואם נחתך \u0003כמרזב\u0004 שחלקו מגולה — \u0003פסולה.\u0004 והוא מסביר: \u0003האי\u0004 \u0005[זה]\u0006 כמרזב פסול — מפני ש\u0003שליט בה אוירא\u0004 \u0005[שולט בו האויר]\u0006 ואיננו יכול להזריע, \u0003והאי\u0004 \u0005[וזה]\u0006 קולמוס כשירה — מפני ש\u0003לא שליט בה אוירא\u0004 \u0005[שולט בו האויר].\u0006 \u0003ורב חסדא אמר\u0004 להיפך: \u0003כמרזב — כשרה, כקולמוס — פסולה!\u0004 מדוע? \u0003האי\u0004 \u0005[זה]\u0006 שהוא כמרזב — \u0003גריד\u0004 \u0005[מתחכך]\u0006 בדופני הרחם ומתחמם המזריע, \u0003והאי\u0004 \u0005[וזה]\u0006 שהוא כקולמוס — \u0003לא גריד\u0004 \u0005[אינו מתחכך]\u0006 מפני שהוא דק ביותר.","\u0003אמר רבא: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב הונא מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, ש\u0003האי לא שליט בה אוירא והאי שליט בה אוירא\u0004 \u0005[זה אין שולט בו האויר וזה שולט בו האויר],\u0006 כי \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום גרידותא\u0004 \u0005[החיכוך]\u0006 — \u0003מידי דהוה אברזא דחביתא\u0004 \u0005[כמו שהוא\u0006 ב\u0005ברז החבית]\u0006 שקצה הברז הוא מחודד, ותוחבים אותו בנקב החבית עד שהוא נוגע בו, ואף כאן יכול המגע להיות בנקודה רחוקה יותר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר: הכי\u0004 \u0005[כך]\u0006 \u0003אמר מר זוטרא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב פפא: הלכתא\u0004 \u0005[הלכה]\u0006 \u0003בין כקולמוס בין כמרזב — כשרה. מיהו, מיבעיא ליה\u0004 \u0005[אבל, נשאלה לו]:\u0006 האם הכוונה היא \u0003למטה מעטרה,\u0004 כלומר, במקום הגיד עצמו, \u0003או למעלה\u0004 מעטרה? ומשיבים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שמדובר \u0003למעלה מעטרה, דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 לומר שמדובר \u0003למטה מעטרה,\u0004 כלומר, בעטרה עצמה — הרי \u0003אפילו נכרת הגיד\u0004 עצמו לגמרי עם חלק מהעטרה \u0003נמי\u0004 \u0005[גם כן]\u0006 הוא כשר, ובלבד שישאר משהו מן העטרה עצמה. ומעירים: \u0003ורבינא\u0004 רק \u0003לשבושי\u0004 \u0005[להטעות]\u0006 את \u0003מרימר הוא דבעי\u0004 \u0005[שרצה],\u0006 שרצה לבחון אותו אם יבין את הדבר.","מסופר: \u0003ההוא עובדא דהוה\u0004 \u0005[אותו מעשה שהיה]\u0006 \u0003ב\u0004עיר \u0003מתא מחסיא\u0004 באדם שהעטרה שלו נעשתה כמרזב, \u0003שפייה\u0004 \u0005[גרר,\u0006 חתך\u0005]\u0006 \u0003מר בר רב אשי\u0004 את הבשר מכל צד עד שנעשה \u0003כקולמוס ואכשריה\u0004 \u0005[והכשיר אותו]\u0006 לבוא בקהל. \u0003ההוא עובדא דהוה\u0004 \u0005[אותו מעשה שהיה]\u0006 \u0003ב\u0004עיר \u0003פומבדיתא שאיסתתים גובתא\u0004 \u0005[נסתם צינור]\u0006 של \u0003שכבת הזרע\u0004 של אותו איש, \u0003ואפיק\u0004 \u0005[והוציא\u0006 זרע\u0005]\u0006 \u0003במקום קטנים\u0004 במקום יציאת מי רגלים. \u0003סבר רב ביבי בר אביי לאכשורי\u0004 \u0005[להכשירו]\u0006 שהרי איננו בגדר פצוע וכרות. \u0003אמר רב פפי: משום דאתו\u0004"],["\u0003ממולאי\u0004 \u0005[שאתם באים מאומללים]\u0006 ממשפחה אומללה, מבית עלי, \u0003אמריתו מילי מוליתא\u0004 \u0005[אומרים אתם דברים אומללים,\u0006 ופגומים\u0005]?\u0006 \u0003במקומה — מבשלה\u0004 \u0005[מבשלת]\u0006 שכבת הזרע וגומרת להזריע, \u0003שלא במקומה — לא מבשלה\u0004 \u0005[מבשלת],\u0006 וכיון שאינו יכול להוליד, הרי הוא כפצוע דכא ופסול.","\u0003אמר רב יהודה אמר שמואל: ניקב\u0004 הגיד, \u0003ונסתם\u0004 אחר כך בבשר, שהפצע הגליד, \u0003כל שאילו נקרי\u0004 \u0005[רואה קרי]\u0006 \u0003ו\u0004אז \u0003נקרע\u0004 שנית — \u0003פסול. ואי לאו\u0004 \u0005[ואם לא] —\u0006 \u0003כשר. הוי\u0004 \u0005[דן]\u0006 \u0003בה רבא: היכא\u0004 \u0005[היכן]\u0006 היה הנקב? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה \u0003למטה מעטרה\u0004 (בקצה האיבר), מדוע יפסול שם הנקב? \u0003אפילו נכרת\u0004 כולו \u0003נמי\u0004 \u0005[גם כן]\u0006 כשר, \u0003אלא\u0004 הכוונה היא \u0003ב\u0004מקום \u0003עטרה עצמה,\u0004 כלומר, בנקודת המגע בין העטרה והגיד. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 \u0003אמר רב מרי בר מר אמר מר עוקבא אמר שמואל: ניקב בעטרה עצמה ונסתם, כל שאילו נקרי\u0004 \u0005[רואה קרי]\u0006 \u0003ונקרע — פסול, ואי לאו\u0004 \u0005[ואם לא] —\u0006 \u0003כשר.\u0004","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רבא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה לרב יוסף: ילמדנו רבינו, היכי עבדינן\u0004 \u0005[איך אנו עושים]\u0006 כדי לבדוק אם הנקב הזה סתום כראוי או לא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מייתינן נהמא חמימא דשערי, ומנחינן ליה אבי פוקרי, ומקרי, וחזינן ליה\u0004 \u0005[מביאים אנו לחם חם של שעורים ומניחים אותו בבית\u0006 פי \u0005הטבעת, ו\u0006מחמת החום הוא \u0005רואה קרי, ואנו רואים אותו]\u0006 אם הנקב נשאר סתום.","\u0003אמר אביי: אטו כולי עלמא\u0004 \u0005[וכי כל העולם]\u0006 כמו \u0003יעקב אבינו הואי\u0004 \u0005[הוא]?\u0006 \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"כחי וראשית אוני\"\u0004 (בראשית מט, ג), שאמרו \u0003שלא ראה קרי מימיו,\u0004 וראובן בכורו בא מטיפת זרע ראשונה (\"ראשית אוני\") שיצאה ממנו. ובודאי אין צורך באמצעי זה כדי לגרום שאדם יראה קרי!","\u0003אלא, אמר אביי\u0004 די באמצעי אחר: \u0003מעברינן קמיה\u0004 \u0005[מעבירים לפניו]\u0006 \u0003בגדי צבעונין\u0004 של אשה, והוא מהרהר ורואה קרי. \u0003אמר רבא: אטו כולי עלמא\u0004 \u0005[וכי כל העולם]\u0006 \u0003ברזילי הגלעדי הוא\u0004 שדרשו עליו שהיה שטוף בזימה, ובודאי לא כל אדם רואה קרי מהרהור כזה בלבד. \u0003אלא מחוורתא כדשנין מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כמו שהסברנו מתחילה]\u0006 כיצד עושים, אף שלא כל אדם זקוק לכך.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ניקב — פסול, מפני שהוא שותת\u0004 ואין הזרע מקלח, \u0003נסתם\u0004 אחר כך בבשר — \u0003כשר, מפני שהוא מוליד. וזהו פסול שחוזר להכשירו.\u0004 ושואלים: ההדגשה במלה \u0003\"זהו\" למעוטי מאי\u0004 \u0005[למעט\u0006 את \u0005מה]?\u0006 ומשיבים: \u0003למעוטי\u0004 \u0005[למעט]\u0006 בנושא אחר — \u0003קרום שעלה\u0004 בנקב שנעשה \u0003מחמת מכה בריאה\u0004 של בהמה, ש\u0003אינו\u0004 \u0005[שאינו]\u0006 נחשב \u0003קרום\u0004 ואינו מחזירה להכשירה.","\u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב אידי בר אבין לאביי: היכי עבדינן\u0004 \u0005[כיצד אנו עושים]\u0006 לרפואה, לסתום נקב כזה? אמר לו \u0003מייתינן שערתא\u0004 \u0005[מביאים שעורה]\u0006 שיש בה צד דק וחד, \u0003ומסרטינן ליה\u0004 \u0005[וסורטים אותו]\u0006 סביב הנקב, \u0003ומייתינן תרבא\u0004 \u0005[ומביאים חלב],\u0006 \u0003ושייפינן\u0004 \u0005[ומורחים]\u0006 על המקום, \u0003ומייתינן שומשנא גמלא ומנכתינן ליה\u0004 \u0005[ומביאים נמלה גדולה ו\u0006גורמים לה ש\u0005תנשוך אותו]\u0006 ועל ידי נשיכתה יוצא דם מהמקום ונוצר גלד שבמשך הזמן מתרפא בשל בשר חדש הגדל במקום, \u0003ופסקינן ליה לרישיה\u0004 \u0005[וחותכים את ראשה]\u0006 של הנמלה ומשאירים אותו שם כדי שיישאר חיבור זה עד לריפוי המוחלט. ומעירים: \u0003ודוקא\u0004 על ידי \u0003שערתא\u0004 \u0005[שעורה]\u0006 עושים זאת, \u0003אבל פרזלא מזרף זריף\u0004 \u0005[ברזל\u0006 גורם ל\u0005דלקת],\u0006 ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים ב\u0003קטן\u0004 (בנקב קטן), \u0003אבל גדול — מיקפולי מיקפל\u0004 \u0005[מתקפל]\u0006 לבסוף ושוב נפתח.","\u0003אמר רבה בר רב הונא: המטיל מים משתי מקומות\u0004 שנראה שיש נקב או פגם אחר באברו, \u0003פסול\u0004 משום פצוע דכא. \u0003אמר רבא:\u0004 בעניינים אלה \u0003לית הלכתא\u0004 \u0005[אין הלכה]\u0006 \u0003לא כברא\u0004 \u0005[כבן]\u0006 \u0003ולא כאבא\u0004 \u0005[כאב],\u0006 \u0003ברא\u0004 \u0005[הבן]\u0006 — \u0003הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 לגבי דברי רבה בר רב הונא. ומה שאמר \u0003אבא\u0004 \u0005[האב]\u0006 — ש\u0003אמר רב הונא: נשים המסוללות זו בזו\u0004 שמתחככות זו בזו כדרך תשמיש, \u0003פסולות לכהונה,\u0004 שלדעתו יש בכך משום זנות.","ועל כך אמר רבה שאין הלכה כמותו, \u0003ואפילו ל\u0004דעת \u0003ר' אלעזר\u0004 ש\u0003אמר פנוי הבא על הפנויה שלא לשם אישות עשאה זונה, הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים בביאה של \u0003איש, אבל\u0004 ביאה של \u0003אשה — פריצותא בעלמא\u0004 \u0005[פריצות סתם]\u0006 היא ואינה עושה אותה זונה בכך.","\u0003פצוע דכא וכרות שפכה מותרין בגיורת ומשוחררת, ואינן אסורין אלא מלבא בקהל\u0004 של זרע ישראל בלבד, \u0003שנאמר: \"לא יבא פצוע דכה וכרות שפכה בקהל ה'\"\u0004 (דברים כג, ב).","\u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מרב ששת: פצוע דכא כהן מהו,\u0004 האם מותר הוא \u0003בגיורת ומשוחררת?\u0004 וצדדי השאלה: האם \u0003בקדושתיה קאי\u0004 \u0005[בקדושתו\u0006 ככהן הוא \u0005עומד],\u0006 שיש בו את כל קדושת כהונה \u0003ו\u0004לכן \u0003אסיר\u0004 \u0005[ואסור]\u0006 כשאר כהן, \u0003או דלמא לאו בקדושתיה קאי ושרי\u0004 \u0005[שמא לא בקדושתו\u0006 הוא \u0005עומד, ומותר]\u0006 בגיורת, כפצוע דכא ישראל?","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: תניתוה\u0004 \u0005[שניתם אותה\u0006 כבר\u0005],\u0006 ששנינו: \u0003פצוע דכא ישראל מותר בנתינה. ואי סלקא דעתך בקדושתיה קאי\u0004 \u0005[ואם עולה בדעתך\u0006 לומר שישראל זה \u0005בקדושתו\u0006 הוא \u0005עומד]\u0006 שיש בו כל קדושת ישראל \u0003אקרי\u0004 \u0005[שיקרא]\u0006 \u0003כאן\u0004 את איסור הקירבה בכנענים \u0003\"\u0004ו\u0003לא תתחתן בם\"\u0004 (שם ז, ג), משמע שמצבו כפצוע דכא מוציא אותו מדרגת הקדושה שהיה בה. וכך זה גם בכהן.","\u0003אמר רבא:\u0004 אין זו ראיה, \u0003אטו התם\u0004 \u0005[וכי שם]\u0006 איסור זה להתחתן בכנענים \u0003משום קדושה ולאו קדושה הוא?\u0004 הלא שם טעם האיסור הוא \u0003דלמא מוליד\u0004 \u0005[שמא יוליד]\u0006 \u0003בן ואזיל פלח\u0004 \u0005[וילך\u0006 ו\u0005יעבוד]\u0006 \u0003לעבודה זרה, והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים — \u0003בגויותן,\u0004 בהיותם גוים, שדווקא אז יש לחשוש, אבל \u0003כי מגיירי\u0004 \u0005[כאשר\u0006 הם \u0005מתגיירים]\u0006 כמו הנתינים, \u0003בישראל שרו\u0004 \u0005[\u0006הם \u0005מותרים],\u0006 \u0003ורבנן הוא דגזרו בהו\u0004 \u0005[וחכמים הם שגזרו בהם]\u0006 אפילו לאחר גירות ואסרו אותם כממזרים, אבל לא מחמת איסור תורה, \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 שלא להתחתן בהם — הרי זה דווקא \u0003בהנך\u0004 \u0005[באלה]\u0006 שהם \u0003בני אולודי\u0004 \u0005[הולדה],\u0006 \u0003אבל האי דלאו בר אולודי\u0004 \u0005[זה שאינו בן הולדה]\u0006 \u0003לא גזרו ביה רבנן\u0004 \u0005[בו חכמים].\u0006","ומקשים על רבא: \u0003אלא מעתה\u0004 לפי הסבר זה, \u0003ממזר\u0004 שמוזהר על כל איסורים שבתורה ואסור לשאת גויה, \u0003דבר אולודי\u0004 \u0005[שבן הולדה]\u0006 הוא, \u0003הכי נמי דאסיר\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאסור]\u0006 בנתינה מדברי סופרים? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003ממזרים ונתינים מותרים לבא זה בזה! אלא\u0004 יש לחזור מטעם זה ולומר טעם אחר: \u0003כי גזור רבנן\u0004 \u0005[כאשר גזרו חכמים]\u0006 שלא להתחתן בנתינים, גזרו רק \u0003בכשרים,\u0004 שלא יתערבו בנתינים, אבל \u0003בפסולים\u0004 לבוא בקהל \u0003לא גזור רבנן\u0004 \u0005[גזרו חכמים].\u0006","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא\u0004 עצמו, שמה שהעמיד את האיסור להתחתן בהם דווקא בעודם גויים, \u0003לאו מילתא היא\u0004 \u0005[לא דבר הוא],\u0006 כלומר, אין ממש בדברים, שהאיסור שלא להתחתן בהם נאמר רק בהיותם גויים, כי \u0003בגויותן,\u0004 בהיותם גוים, \u0003לית להו\u0004 \u0005[אין להם]\u0006 כלל ענין של \u0003חתנות\u0004 בהם, \u0003נתגיירו — אית להו\u0004 \u0005[יש להם]\u0006 ענין של \u0003חתנות\u0004 וחל עליהם איסור \"לא תתחתן\". ובכל זאת פצוע דכא מותר בהם.","\u0003מתיב\u0004 \u0005[מקשה\u0006 על כך\u0005]\u0006 \u0003רב יוסף,\u0004 הרי נאמר: \u0003\"ויתחתן שלמה את בת פרעה מלך מצרים\"\u0004 (מלכים א' ג, א), משמע שיש להם חתנות גם בהיותם גויים! ומשיבים: \u0003גייורי גיירה\u0004 \u0005[גייר אותה\u0006 לפני כן\u0005],\u0006 ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא קבלו גרים לא בימי דוד ולא בימי שלמה!\u0004 ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[כלום\u0006 מהו \u0005טעם הדבר]\u0006 שלא קיבלו גרים באותם הימים — משום שחששו שהגרים אינם מתגיירים לשם שמים \u0003אלא\u0004 מתאווים \u0003לשולחן מלכים\u0004 של דוד ושלמה,"],["\u0003הא לא צריכא ליה\u0004 \u0005[\u0006ו\u0005זו,\u0006 בת פרעה, \u0005אינה צריכה לו],\u0006 שהרי היא עצמה בת מלך, ולכן אין לפקפק בגיורה.","ומקשים מצד אחר: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 סיבה אחרת לאיסורה של בת פרעה — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003מצרית ראשונה היא,\u0004 שגם אם נתגיירה, דור ראשון של מצריים היא, ואסורה לבוא בקהל ה'! \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003הנך אזלי לעלמא והני אחריני נינהו\u0004 \u0005[אלה\u0006 שגזרה בהם התורה כבר \u0005הלכו\u0006 להם \u0005ל\u0006כל ה\u0005עולם, ואלה\u0006 שנמצאים במצרים \u0005אחרים הם],\u0006","\u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005],\u0006 \u0003אמר ר' יהודה: מנימין גר מצרי, היה לי חבר מתלמידי ר' עקיבא, אמר:\u0004 לאחר שהתגיירתי \u0003אני מצרי ראשון, ונשאתי\u0004 גיורת שהיא \u0003מצרית ראשונה, אשיא לבני\u0004 שהוא מצרי שני \u0003מצרית שניה כדי שיהא בן בני ראוי לבא בקהל,\u0004 משמע: אפילו בזמן המשנה המצריים אסורים!","\u0003אמר רב פפא: אנן\u0004 \u0005[אנו]\u0006 \u0003משלמה ליקו ונתיב\u0004 \u0005[נקום ונקשה]?\u0006 \u0003שלמה לא נסיב מידי\u0004 \u0005[נשא דבר],\u0006 \u0003דכתיב ביה\u0004 \u0005[שנאמר בו]:\u0006 \u0003\"מן הגוים אשר אמר ה' אל בני ישראל לא תבאו בהם והם לא יבאו בכם אכן יטו את לבבכם אחרי אלהיהם, בהם דבק שלמה לאהבה\"\u0004 (מלכים א' יא, ב), וכיון שהיו לשלמה נשים אסורות אחרות אין להקשות בענין בת פרעה, ובאמת, לא היו אלה נישואים בעלי תוקף כלל. \u0003אלא קשיא\u0004 \u0005[קשה]\u0006 הלשון \u0003\"ויתחתן\"\u0004 האמורה בבת פרעה!","ומשיבים: \u0003מתוך אהבה יתירה שאהבה, מעלה עליו הכתוב כאילו נתחתן בה\u0004 בנישואים שתופסים, אבל באמת לא היו אלה כלל נישואים תקפים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003פצוע דכא וכרות שפכה מותרים בגיורת ומשוחררת,\u0004 ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בנתינה\u0004 — \u0003אסירי\u0004 \u0005[אסורים]!\u0006 אם כן יש כאן סתירה לברייתא המתירה פצוע דכא בנתינה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 שאתה מדייק כך, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 ששנינו: \u0003ואינן אסורין אלא מלבא בקהל\u0004 ונדייק להיפך: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בנתינה שרו\u0004 \u0005[מותר],\u0006 שאינה נקראת \"קהל ה'\"! \u0003אלא מהא ליכא למשמע מינה\u0004 \u0005[מ\u0006משנה \u0005זו אין לשמוע,\u0006 להסיק, \u0005ממנה]\u0006 בדרך דיוק, ואין לנו אלא הלכה שלמדנו במפורש.","\u0003עמוני ומואבי\u0004 שנתגיירו — \u0003אסורים\u0004 לבוא בקהל, \u0003ואיסורן איסור עולם\u0004 לכל הדורות אחריהם, \u0003אבל נקבותיהם\u0004 גם אם הן עצמן התגיירו — \u0003מותרות מיד.\u0004","\u0003מצרי ואדומי אינם אסורים אלא עד שלשה דורות, אחד זכרים ואחד נקבות. ר' שמעון מתיר את הנקבות\u0004 של מצרי ואדומי \u0003מיד. אמר ר' שמעון: קל וחומר הדברים; ומה אם במקום שאסר את הזכרים איסור עולם\u0004 בעמונים ומואבים — \u0003התיר את הנקבות מיד, מקום שלא אסר את הזכרים אלא עד שלשה דורות — אינו דין שנתיר את הנקבות מיד?\u0004","\u0003אמרו לו: אם הלכה\u0004 אתה מוסר, ששמעת כך — \u0003נקבל\u0004 ממך, \u0003ואם לדין,\u0004 שאתה רוצה רק לדון מקל וחומר — \u0003יש תשובה\u0004 לקל וחומר זה. \u0003אמר להם: לא כי,\u0004 אף אם אני דן קל וחומר, אינני מסכים לטענתכם שיש לכם תשובה לפורכו, אבל מכל מקום \u0003הלכה אני אומר\u0004 ולא קל וחומר.","\u0003מנא הני מילי\u0004 \u0005[מניין הדברים הללו]\u0006 שעמונית ומואבית מותרות? \u0003אמר ר' יוחנן:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכראות שאול את דוד יוצא לקראת הפלשתי אמר אל אבנר שר הצבא בן מי זה הנער אבנר ויאמר אבנר חי נפשך המלך אם ידעתי\"\u0004 (שמואל א', יז, נה), ויש לתמוה: \u0003ו\u0004כי \u0003לא ידע,\u0004 לא הכיר, \u0003ליה\u0004 \u0005[אותו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 קודם לכן שדוד ניגן אצל שאול \u0003\"ויאהבהו מאד ויהי לו נשא כלים\"\u0004 (שם טז, כא)! \u0003אלא\u0004 תאמר כי \u0003אאבוה קא משאיל\u0004 \u0005[על אביו\u0006 של דוד \u0005היה שואל].\u0006","ומוסיפים לתמוה: \u0003ו\u0004כי את \u0003אביו\u0004 של דוד \u0003לא ידע,\u0004 לא הכיר, \u0003ליה\u0004 \u0005[אותו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 על ישי אבי דוד: \u0003\"והאיש בימי שאול זקן בא באנשים\"\u0004 (שם יז, יב) \u0003ואמר רב ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אבא: זה ישי אבי דוד שנכנס באוכלוסא\u0004 \u0005[בקהל גדול]\u0006 \u0003ויצא באוכלוסא,\u0004 שאיש גדול וחשוב היה, ובודאי ידעו הכל מי הוא!","אלא \u0003הכי קאמר\u0004 \u0005[כך אמר]\u0006 \u0003שאול,\u0004 שרצה לברר את פרטי היחוס של דוד \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004בני \u0003פרץ אתי\u0004 \u0005[\u0006הוא \u0005בא]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004בני \u0003זרח אתי\u0004 \u0005[\u0006הוא \u0005בא].\u0006 ומדוע חשובה ידיעה זו? — \u0003אי\u0004 \u0005[אם]\u0006 \u0003מ\u0004בני \u0003פרץ אתי\u0004 \u0005[\u0006הוא \u0005בא] —\u0006 \u0003מלכא הוי\u0004 \u0005[מלך יהיה],\u0006 לפי \u0003שהמלך פורץ לעשות דרך ואין ממחין בידו,\u0004 ונרמז הדבר בשם \"פרץ\". ו\u0003אי\u0004 \u0005[\u0006ו\u0005אם]\u0006 \u0003מ\u0004בני \u0003זרח אתי\u0004 \u0005[\u0006הוא \u0005בא]\u0006 — \u0003חשיבא בעלמא הוי\u0004 \u0005[\u0006איש \u0005חשוב בלבד יהיה]\u0006 אך לא מלך.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 שאול לאבנר \u0003שאל עליה\u0004 \u0005[עליו]\u0006 \u0003— דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וילבש שאול את דוד מדיו\"\u0004 (שם יז, לח) ומשמעו שהיו \u0003כמדתו\u0004 של דוד. \u0003וכתיב ביה\u0004 \u0005[ונאמר בו]\u0006 \u0003בשאול \"משכמו ומעלה גבוה מכל העם\"\u0004 (שם ט, ב) וכיון שראה שדוד דומה לו, והבגדים מתאימים לו, התחיל לחשוש שמא הוא המיועד למלוכה, ולכן שאל. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003דואג האדומי: עד שאתה משאיל עליו\u0004 (שואל אודותיו) \u0003אם הגון הוא למלכות אם לאו\u0004 \u0005[לא],\u0006 \u0003שאל עליו אם\u0004 בכלל \u0003ראוי\u0004 הוא \u0003לבא בקהל אם לאו\u0004 \u0005[לא].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 לפקפוק זה? — \u0003דקאתי\u0004 \u0005[ש\u0006הוא \u0005בא]\u0006 \u0003מרות המואביה,\u0004 והמואבים פסולים מלבוא בקהל לעולם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אבנר: תנינא\u0004 \u0005[\u0006הלא \u0005שנינו]:\u0006 \u0003עמוני — ולא עמונית, מואבי — ולא מואבית.\u0004 אמר לו: \u0003אלא מעתה\u0004 תפרש כמו כן שמה שנאמר \u0003\"ממזר\"\u0004 הכוונה \u0003ולא ממזרת?\u0004 אמר לו: \u0003\"ממזר\" כתיב\u0004 \u0005[נאמר],\u0006 שאיננו שם עצם אלא שם תואר, וכוונתו \u0003מום זר,\u0004 מי שיש בו מום הבא מחמת פריצת גדר ערוה, ולכן שם התואר הזה כולל זכרים ונקבות כאחד.","אמר לו: אם כן, תאמר גם: \u0003\"מצרי\" ולא מצרית!\u0004 ענה לו: \u0003שאני הכא דמפרש טעמא דקרא\u0004 \u0005[שונה כאן שמפורש טעם הכתוב]\u0006 באיסור העמונים: \u0003\"על\u0004 דבר \u0003אשר לא קדמו אתכם בלחם ובמים\"\u0004 (דברים כג, ה), וכיון ש\u0003דרכו של איש\u0004 לצאת החוצה \u0003לקדם\u0004 אורחים, \u0003ולא דרכה של אשה לקדם,\u0004 משום כך לא היתה סיבה לאסור את הנשים. ענה לו: \u0003היה להם לקדם אנשים לקראת אנשים ונשים לקראת נשים! אישתיק\u0004 \u0005[שתק]\u0006 אבנר, שלא ידע מה להשיב לקושיה זו.","\u0003מיד: \"ויאמר המלך שאל אתה בן מי זה העלם\"\u0004 (שמואל א' יז, נו), ומעירים: \u0003התם קרי ליה\u0004 \u0005[שם\u0006 בפסוק קודם \u0005קורא לו]\u0006 \u0003\"נער\",\u0004 ואילו \u0003הכא קרי ליה\u0004 \u0005[כאן קורא לו]\u0006 \u0003\"עלם\"\u0004 ושינוי הלשון בא לרמז — \u0003הכי קא אמר ליה\u0004 \u0005[כך אמר לו]\u0006 לדואג: \u0003הלכה נתעלמה\u0004 (\"העלם\") \u0003ממך\u0004 ואין אתה יודע מה הדין — \u0003צא ושאל בבית המדרש.\u0004 הלך לבית המדרש ו\u0003שאל, אמרו ליה\u0004 \u0005[לו]\u0006 הלכה היא: \u0003עמוני ולא עמונית, מואבי ולא מואבית.\u0004"],["\u0003אקשי להו\u0004 \u0005[הקשה להם]\u0006 \u0003דואג\u0004 את \u0003כל הני קושייתא\u0004 \u0005[אלה הקושיות]\u0006 משאר הפסולים, \u0003אישתיקו\u0004 \u0005[שתקו]\u0006 ולא ידעו להשיב. \u0003בעי לאכרוזי עליה\u0004 \u0005[רצה להכריז עליו\u0006 על דוד\u0005]\u0006 שהוא פסול לבוא בקהל, \u0003מיד \"ועמשא בן איש ושמו יתרא הישראלי אשר בא אל אביגל בת נחש\"\u0004 (שמואל ב' יז, כה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 במקום אחר, ששמו היה \u0003\"יתר הישמעאלי\"\u0004 (דברי הימים א' ב, יז), \u0003אמר רבא: מלמד שחגר חרבו כישמעאל\u0004 (כערבי), \u0003ואמר: כל מי שאינו שומע הלכה זו,\u0004 כלומר, אינו מקיים אותה — \u0003ידקר בחרב.\u0004 כי \u0003כך מקובלני מבית דינו של שמואל הרמתי: עמוני ולא עמונית, מואבי ולא מואבית.\u0004","ולענין מעשה זה שואלים: \u0003ומי מהימן\u0004 \u0005[והאם נאמן]\u0006 הוא להעיד בדבר כגון זה? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ר' אבא אמר רב: כל תלמיד חכם שמורה הלכה ובא, אם קודם המעשה\u0004 הנוגע לעצמו \u0003אמרה — שומעין לו, ואם לאו\u0004 \u0005[לא],\u0006 שאמר הלכה זו רק כאשר הדבר נוגע לו — \u0003אין שומעין לו,\u0004 שכיון שהוא נוגע בדבר אינו נאמן להעיד עליו. וכיון שנשא עמשא את בתו של ישי (כמפורש בספר דברי הימים שם) הרי הוא נוגע בדבר! ומשיבים: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003שמואל ובית דינו קיים,\u0004 וכיון שאפשר לשאול אותם מה היתה המסורת שבידם ודאי אינו משקר.","ושואלים: ו\u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 מכל אותם הדברים שהקשה דואג! ומשיבים: \u0003הכא תרגמו\u0004 \u0005[כאן,\u0006 בבבל, \u0005תרגמו,\u0006 הסבירו\u0005]:\u0006 \u0003\"כל כבודה בת מלך פנימה\"\u0004 (תהלים מה, יד), כלומר, אין כבודה של אשה לצאת לחוץ כלל, ולכן לא יצאו לקראת נשי ישראל. \u0003במערבא אמרי\u0004 \u0005[בארץ ישראל אומרים]\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יצחק, אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ויאמרו אליו איה שרה אשתך\u0004 ויאמר הנה באהל","\u0003\"\u0004(בראשית יח, ט), כלומר, שבחה של אשה שתהיה בבית. ומעירים: \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו במקור הטעם מדוע עמוניות ומואביות מותרות. ששנינו: \u0003\"עמוני\" ולא עמונית, \"מואבי\" ולא מואבית,\u0004 אלו \u0003דברי ר' יהודה,\u0004 כלומר, שהוא לומד זאת מלשון הכתוב המדבר בלשון זכר, ואילו \u0003ר' שמעון אומר,\u0004 מקור הטעם הוא בפסוק: \u0003\"על דבר אשר לא קדמו אתכם בלחם ובמים\"\u0004 (דברים כג, ה) — \u0003דרכו של איש לקדם,\u0004 ואין דרכה של אשה לקדם.","באותו ענין \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"פתחת למוסרי\"\u0004 (תהלים קטז, טז) — \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, שני מוסרות שהיו עלי\u0004 שאפשר היה לאסור אותי ואת משפחתי מלבוא בקהל בשבילן, \u0003פתחתם,\u0004 והם: \u0003רות המואביה ונעמה העמונית,\u0004 כי על ידי היתר המואביות והעמוניות — מותרים אנו לבוא בקהל.","\u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"רבות עשית אתה ה' אלהי נפלאתיך ומחשבתיך אלינו\"\u0004 (שם מ, ו) \u0003\"אלי\" לא נאמר אלא \"אלינו\"\u0004 — \u0003מלמד שהיה רחבעם\u0004 בן שלמה, נכדו של דוד \u0003יושב בחיקו של דוד, אמר לו: עלי ועליך נאמרו שתי מקראות הללו\u0004 שהרי רחבעם הוא בן נעמה העמונית.","ובאותו ענין \u0003דרש רבא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אז אמרתי הנה באתי במגלת ספר כתוב עלי\"\u0004 (שם ח), \u0003אמר דוד: אני אמרתי \"עתה באתי\",\u0004 וחיי הם ענין שנוצר רק עכשיו, \u0003ולא ידעתי שב\"מגילת ספר כתוב עלי\",\u0004 שכבר נרמז עניני בימי קדם, שכן \u0003התם כתיב\u0004 \u0005[שם נאמר]\u0006 בבנות לוט \u0003\"הנמצאת\"\u0004 (בראשית יט, טו), \u0003הכא כתיב\u0004 \u0005[כאן נאמר]:\u0006 \u0003\"מצאתי דוד עבדי בשמן קדשי משחתיו\"\u0004 (תהלים פט, כא), ואם כן, מציאה זו שנמצאה בבנות לוט שמהן יצאו עמון ומואב, היא דוד ומשפחתו.","\u0003אמר עולא אמר ר' יוחנן: בת גר עמוני כשרה\u0004 לא רק לישראל אלא גם \u0003לכהונה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא בר עולא לעולא: כמאן\u0004 \u0005[כ\u0006דעת \u0005מי]\u0006 אתה אומר זאת? \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה — הא\u0004 \u0005[הרי]\u0006 \u0003אמר: בת גר זכר כבת חלל זכר,\u0004 ואם כן כל בת גר פסולה לכהונה! \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003כ\u0004דעת \u0003ר' יוסי, פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר: אף גר שנשא גיורת — בתו כשרה לכהונה.\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שאמר זאת רק \u0003בהנך\u0004 \u0005[באלה],\u0006 הגרים, ש\u0003ראוין לבא בקהל, אבל האי\u0004 \u0005[זה]\u0006 גר עמוני ש\u0003אין\u0004 הוא \u0003ראוי לבא בקהל — לא\u0004 תהיה בתו כשירה לכהונה, \u0003מנא ליה\u0004 \u0005[מניין לו]\u0006 חילוק זה בדין?","ומשיבים: \u0003דיליף\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 \u0003מכהן גדול באלמנה,\u0004 שבתו נפסלה לכהונה. ובדרך זו נדייק: \u0003מה לכהן גדול באלמנה — שכן ביאתו בעבירה,\u0004 מה שאין כן בבת גר עמוני שיכולה לבוא בביאה כשירה.","אם כן \u0003חלל יוכיח\u0004 שביאתו עצמה איננה בעבירה ובניו אף הם חללים! ואם תטען: \u0003מה לחלל שכן\u0004 עיקר \u0003יצירתו בעבירה\u0004 ושמא משום כך פסולו מרובה —","\u0003כהן גדול יוכיח\u0004 שאין יצירתו בעבירה, ובתו מן האלמנה פסולה. \u0003וחזר הדין,\u0004 כלומר, אפשר להעביר את הדיון מצד אחד לצד שני, ואם כי:","\u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 לא זה דומה לזה ולא זה דומה לזה, \u0003הצד השוה שבהן:\u0004 שכל \u0003שאינו ברוב קהל,\u0004 שהם שונים בדינם מרוב ישראל \u0003ובתו פסולה — אף כאן\u0004 גר עמוני \u0003שאינו ברוב קהל,\u0004 שהרי אסור לו לבוא בקהל ישראל — \u0003ובתו פסולה.\u0004","אולם את ההוכחה הזו אפשר לדחות: \u0003מה להצד השוה שבהן שכן יש בהן צד עבירה\u0004 אם ביצירתם ואם בביאתם, ואילו בבת גר עמוני אין שום צד עבירה!","ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ודאי ב\u0004גר \u0003עמוני שנשא בת ישראל קאמרת\u0004 \u0005[אמרת]\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003ביאתו בעבירה\u0004 שהרי אסור לו לבוא בקהל — מכל מקום \u0003בתו כשרה\u0004 לכהונה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן]\u0006 זה באמת היה חידושו של ר' יוחנן.","\u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רבין\u0004 מארץ ישראל לבבל \u0003אמר\u0004 בשם \u0003ר' יוחנן: בת גר עמוני, ובת מצרי שני\u0004 (שהוא עצמו אסור לבוא בקהל) שנשאו בת ישראל, \u0003ר' יוחנן אמר: כשרה\u0004 לכהונה, \u0003וריש לקיש אמר: פסולה\u0004 לכהונה. וטעם דבריהם: \u0003ריש לקיש אמר פסולה — דיליף לה\u0004 \u0005[שלומד אותה]\u0006 \u0003מכהן גדול באלמנה,\u0004 שכל שביאתו בעבירה בתו אסורה לכהונה. \u0003ר' יוחנן אמר כשרה —\u0004"],["\u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' זכאי קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן\u0004 ברייתא זו: מה שנאמר בכהן גדול: \u0003\"כי אם בתולה מעמיו יקח אשה\"\u0004 (ויקרא כא, יד) \u0003להביא\u0004 (לרבות) \u0003גיורת מכנה\u0004 (מבוססת, שלימה), זו שנולדה בקדושת ישראל, שהיא ממשפחה של גרים כשרים — \u0003שהיא כשרה לכהונה. ואמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: לריבוי זה \u0003אני שונה \"עמיו\",\u0004 ועוד לשון ריבוי \u0003\"מעמיו\",\u0004 כלומר, אפילו כשהיא ממקצת עמיו ומעם אחר — \u0003להביא בתולה הבאה משני עממין,\u0004 כלומר, מצירוף בני זוג השייכים לשני עמים שונים, \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003גיורת מכנה ותו לא\u0004 \u0005[ולא עוד]?\u0006","שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003\"שני עממין\"\u0004 אלה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003עמוני שנשא עמונית, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003משני עממין\u0004 שהם מבחינת הדין נחשבים כשני עמים שונים, שכן \u0003זכרים אסורין ונקבות מותרות,\u0004 אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003גיורת מכנה\u0004 שדובר בה, שהרי היא גיורת כשירה לכל דבר. \u0003אלא\u0004 המדובר \u0003בעמוני שנשא בת ישראל\u0004 שהם שני עמים.","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 באופן אחר: \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אני שונה \"עמיו\" \"מעמיו\" להביא בתולה הבאה משני עממין\u0004 ישראלית וגר, \u0003ו\u0004אותו גר הוא \u0003מעם שיש בו שני עממין,\u0004 כלומר, עמוני ומואבי (שהנקבות שבהם מותרות), \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 \u0003גיורת מכנה ותו לא\u0004 \u0005[ולא עוד]?\u0006","ושואלים: \u0003ולהך לישנא\u0004 \u0005[וללשון\u0006 שניה \u0005זו]\u0006 שאמרנו, \u0003בת מצרי שני\u0004 שנשא ישראלית באיסור, אותה בת שהיא \u0003כשרה לכהונה מנא ליה\u0004 \u0005[מניין לו]?\u0006 שהרי במצרים אין חילוק בין זכרים לנקבות! \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003דיליף\u0004 \u0005[שלומד]\u0006 \u0003מעמוני שנשא בת ישראל\u0004 — אולם אפשר להקשות: \u0003מה לעמוני שנשא\u0004 באיסור \u0003בת ישראל\u0004 ונולדה לו בת, שאף שהיא עמונית, הריהי מותרת, \u0003שכן נקבות\u0004 עמוניות \u0003מותרות\u0004 לגמרי ואיסור קל הוא, ולכן בתו מותרת לכהונה, מה שאין כן במצרי שנשא בת ישראל, שאין זרעו כשר אלא מדור שלישי.","ואומרים: אם כן, \u0003מצרי שני שנשא מצרית שניה יוכיח,\u0004 שהוולד כשר לקהל, שדור שלישי הוא, ומותר!","ודוחים: \u0003מה למצרי שני שנשא מצרית שניה שכן אין ביאתו בעבירה,\u0004 שהרי מותר לו לשאתה, מה שאין כן בעמוני שנשא בת ישראל.","ויש לחזור לראיה הראשונה: \u0003עמוני שנשא בת ישראל יוכיח\u0004 שביאתו בעבירה, ואף על פי כן הוולד כשר. \u0003וחזר הדין\u0004 מצד זה לצד זה לא ראי זה כראי זה ולא ראי זה כראי זה, הצד השווה שבהם שהם מותרים.","\u0003אמר רב יוסף: היינו דשמענא ליה\u0004 \u0005[זהו ששמעתי אותו]\u0006 את \u0003רב יהודה\u0004 ש\u0003אמר\u0004 בדרשתו את ענין הייתור \u0003\"עמיו\" \"מעמיו\", ולא ידענא\u0004 \u0005[ידעתי]\u0006 \u0003מאי קאמר\u0004 \u0005[מה הוא אומר],\u0006 ועכשיו אני מבין שרצה לדרוש להכשיר בת של עמוני שנשא בת ישראל וכר' יוחנן.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב שמואל בר יהודה\u0004 מארץ ישראל לבבל, \u0003אמר: הכי תנא קמיה\u0004 \u0005[כך שנה לפניו]\u0006 ר' זכאי: \u0003אשה עמונית כשרה, בנה מעמוני פסול, ובתה מעמוני כשרה. במה דברים אמורים — בעמוני ועמונית שנתגיירו, אבל בתה מעמוני\u0004 גוי — \u0003פסולה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003פוק תני לברא\u0004 \u0005[צא ושנה בחוץ],\u0006 כלומר, ברייתא זו שהבאת אינה מן הברייתות הראויות להיכנס לבית המדרש. כי \u0003מאי דאמרת\u0004 \u0005[מה שאמרת]\u0006 \u0003אשה עמונית כשרה\u0004 — דבר זה ידוע, ואין צריך לאמרו, שהרי פירשו: \u0003עמוני ולא עמונית.\u0004 ומה שאמרת כי \u0003בנה מעמוני פסול\u0004 — גם את זה אין צורך לומר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003עמוני הוא.\u0004","אולם המשך דבריך שאמרת: \u0003ובתה מעמוני כשרה, למאי\u0004 \u0005[למה\u0006 לאיזה ענין\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם לומר]\u0006 לענין \u0003לבא בקהל\u0004 — אין צריך לומר זאת, \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003אמה כשרה\u0004 לקהל, \u0003היא\u0004 בתה \u0003מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שכשרה? \u0003אלא\u0004 ודאי הכוונה \u0003לכהונה.\u0004","ובהמשך: \u0003במה דברים אמורים — בעמוני ועמונית שנתגיירו, אבל בתה מעמוני פסולה.\u0004 ונברר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"בתה מעמוני\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003עמוני שנשא עמונית\u0004 ונתגיירו שניהם — אם כן \u0003היינו גיורת מכנה,\u0004 זו שדובר בה קודם שכשרה! \u0003אלא עמוני שנשא בת ישראל\u0004 בעבירה, ולשיטה זו הבת פסולה לכהונה, אולם הלא לדעת ר' יוחנן כשרה היא, ולכן \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003פוק תני לברא\u0004 \u0005[צא\u0006 ו\u0005שנה בחוץ],\u0006 שאין ברייתא זו מוסמכת ללמוד ממנה.","שנינו במשנה: \u0003מצרי ואדומי אינן אסורין\u0004 אלא שלושה דורות בין זכרים בין נקבות, ור' שמעון מתיר את הנקבות מקל וחומר. ואמרו לו חכמים שלקל וחומר זה יש תשובה. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 היא \u0003תשובה\u0004 זו שרמזו לה?","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: משום דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 \u0003עריות יוכיחו שלא אסר בהן אלא עד שלשה דורות,\u0004 שהרי קירבת ערוה לא נאסרה מן התורה אלא עד שלושה דורות, כגון בתו ובת בתו, או אמו ואם אמו, ואסר בהם \u0003אחד זכרים ואחד נקבות!\u0004","את הראיה הזו דוחים: \u0003מה לעריות — שכן\u0004 חמורות הן, משום שיש בהן עונש \u0003כרת!\u0004 ומשיבים: \u0003ממזר יוכיח\u0004 שאין בו כרת, ודינו שווה בין בזכרים בין בנקבות.","ודוחים: \u0003מה לממזר\u0004 שיש בו צד חמור, \u0003שכן אינו ראוי לבא בקהל לעולם\u0004 בכל הדורות. אם כן — \u0003עריות יוכיחו\u0004 שאחרי שלושה דורות אין בהן איסור, ולאחרים שאינם קרוביהן מותרים מיד. \u0003וחזר הדין\u0004 מצד זה לצד זה,","\u0003לא ראי זה כראי זה ולא ראי זה כראי זה,\u0004 אין זה דומה לזה ואין זה דומה לזה, \u0003הצד השוה שבהן — שאסורין אחד זכרים ואחד נקבות, אף אני אביא מצרי ומצרית שיהיו אסורין, אחד זכרים ואחד נקבות.\u0004","ודוחים: \u0003מה להצד השוה שבהן שכן יש בהן צד כרת,\u0004 אם בביאת הערוה בעצמה ואם ביצירתו של הממזר, שהרי אין ממזר אלא מחיוב כרת.","\u0003ורבנן\u0004 \u0005[וחכמים]\u0006 לומדים זאת \u0003מחלל\u0004 שהוא נוצר \u0003מ\u0004ביאת \u0003חייבי עשה,\u0004 כגון הוולד הנולד לכהן גדול מזו שאינה בתולה שאסורים בין הזכרים ובין הנקבות. \u0003וכ\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 שאמר שהוולד חלל.","\u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003\"לא כי\"\u0004 שאמר ר' שמעון — \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]:\u0006 \u0003לדידי לא סבירא לי\u0004 \u0005[לי עצמי,\u0006 לשיטתי, \u0005אינני סובר]\u0006 \u0003כר' אליעזר בן יעקב,\u0004 ואין לכם תשובה לדברי על פי שיטתי. ו\u0003לדידכו\u0004 \u0005[ולכם]\u0006 \u0003דסבירא לכו\u0004 \u0005[שאתם סבורים]\u0006 \u0003כר' אליעזר בן יעקב\u0004 — מכל מקום \u0003הלכה אני אומר,\u0004 שכך מסורת בידי שנקבות של מצרי ואדומי מותרות.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להן ר' שמעון: הלכה אני אומר, ועוד: מקרא מסייעני,\u0004 שהרי נאמר בפסוק \u0003\"בנים\u0004 אשר יוולדו להם\u0003\"\u0004 (דברים כג, ט), ודרשו: \"בנים\" \u0003ולא בנות.\u0004","ומפרשים את הענין על פי ברייתא, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 במצרי ובאדומי \u0003\"בנים\" ולא בנות\u0004 נאסרו, אלו \u0003דברי ר' שמעון. אמר ר' יהודה, הרי הוא אומר: \"בנים אשר יולדו להם דור שלישי\u0004 יבא להם בקהל ה'\u0003\"\u0004 (דברים כג, ט), משמע ש\u0003הכתוב תלאן בלידה\u0004 (\"אשר יולדו\") ואין מחלקים בין זכר ונקיבה, אלא בלידת הדור השלישי.","\u0003אמר ר' יוחנן: אי לאו\u0004 \u0005[אם לא]\u0006 ש\u0003אמר ר' יהודה\u0004 כי \u0003הכתוב תלאן בלידה — לא מצא ידיו ורגליו בבית המדרש.\u0004 כלומר, היה מגיע לידי סתירה מתוך שיטתו שלו. ומדוע, \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שלדעת ר' יהודה \u0003קהל גרים איקרי\u0004 \u0005[נקרא]\u0006 גם הוא \u0003קהל\u0004 ה',"],["אם כן \u0003מצרי שני במאי\u0004 \u0005[במה]\u0006 \u0003יטהר\u0004 זרעו שיוכל להיות דור שלישי, הרי אסור לבוא בקהל? שהרי אינו יכול לשאת לא בת ישראל ולא גיורת! ומשיבים: \u0003דלמא דאי עבר ונסיב\u0004 \u0005[שמא שאם עבר ונשא]\u0006 גיורת או בת ישראל. ודוחים: במקרה של \u0003\"דאי\"\u0004 \u0005[\"שאם\"]\u0006 \u0003לא כתיב קרא\u0004 \u0005[נאמר\u0006 הכתוב\u0005],\u0006 שאין הכתוב מדבר אודות דבר הבא רק על ידי מעשה אסור.","ומקשים: \u0003הרי ממזר,\u0004 שהוא מקרה של \u0003\"דאי\"\u0004 \u0005[\"שאם\"],\u0006 \u0003וכתביה קרא\u0004 \u0005[ואמרו הכתוב],\u0006 שהרי ממזר יצירתו בעבירה! ומשיבים: \u0003\"דאי\" לאיסורא\u0004 \u0005[\"שאם\" לאיסור] —\u0006 \u0003כתב, \"דאי\" להיתרא\u0004 \u0005[\"שאם\" להיתר] —\u0006 \u0003לא כתב,\u0004 שיתכן שיהא כתוב במקרא דבר שנעשה באיסור — כדי לאסור אותו או להחמיר עליו. אבל היתר של דבר שנוצר רק מתוך איסור — לא נכתב.","ומקשים: \u0003הרי מחזיר גרושתו\u0004 אחרי שהיתה נשואה לאחר, שיש שם \u0003\"דאי\" להיתרא\u0004 \u0005[\"שאם\" להיתר]\u0006 \u0003וכתביה\u0004 \u0005[וכתבו]?\u0006 שכן מן הכתוב בענין זה \"תועבה היא\" למדים אנו, שאף שהיא עצמה אסורה — מכל מקום אם עברה וחזרה ונישאה לבעלה הראשון, בניה כשרים! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 \u0003משום עיקר איסורא\u0004 \u0005[האיסור]\u0006 \u0003הוא דכתביה\u0004 \u0005[שכתבו]\u0006 שאסור לבעלה להחזירה, ואת ההיתר לגבי הבנים למדים אנו בדרך אגב.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 נאמר: \"בנים אשר יוולדו להם דור שלישי יבוא להם בקהל ה'\" (דברים כג, ט), ויש לתמוה: \u0003אם נאמר\u0004 בכתוב זה \u0003\"בנים\" למה נאמר\u0004 גם \u0003\"דורות\", ואם נאמר \"דורות\" למה נאמר \"בנים\"?\u0004 שהרי היה יכול לכתוב \"בן שלישי יבוא\", או \"דור שלישי יבוא\" ולא לכתוב כלל \"בנים\"! ומסבירים: \u0003אם\u0004 היה \u0003נאמר \"בנים\"\u0004 בלבד \u0003ולא נאמר \"דורות\", הייתי אומר\u0004 שהדבר תלוי בבנים: \u0003בן ראשון ושני\u0004 שנולד למצרי \u0003אסור, שלישי — מותר, לכך נאמר\u0004 גם \u0003\"דורות\"\u0004 ללמד שאין הדבר תלוי במספר הבנים אלא בדורות.","\u0003ו\u0004להיפך, \u0003אם\u0004 היה \u0003נאמר \"דורות\"\u0004 (\"דור שלישי\") בלבד \u0003ולא\u0004 היה \u0003נאמר \"בנים\", הייתי אומר\u0004 שמונים את סדר הדורות רק \u0003ל\u0004מן \u0003אותן העומדים על הר סיני,\u0004 שדור שלישי נחשב מאותם שהיו באותה תקופה ושלושה דורות לאחר מכן מותר, \u0003לכך נאמר \"בנים\".\u0004","נאמר בפסוק: \u0003\"\u0004בנים אשר יולדו להם דור שלישי יבוא \u0003להם\"\u0004 (דברים כג, ט), ופירושו: \u0003מהם מנה,\u0004 כלומר, מאותם שנתגיירו אתה מתחיל למנות דורות, שהם עצמם נחשבים דור ראשון ובני בניהם מותרים. ועוד למדים מ\u0003\"להם\"\u0004 הכתוב בלשון רבים — \u0003הלך אחר פסולן,\u0004 שאם נשא מצרי אשה ישראלית, או שמצרית נישאה לישראלי באיסור — הנולד מהם, אף שאחד מהוריו אינו פסול — הריהו הולך אחר הפסול ומונים לו עד דור שלישי.","ומעירים: \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"להם\" ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"אשר יולדו\". דאי כתב רחמנא\u0004 \u0005[שאילו אמרה התורה]\u0006 רק \u0003\"אשר יולדו\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מבניהם מנה\u0004 דורות, על כן \u0003כתב רחמנא\u0004 \u0005[כתבה התורה]\u0006 \u0003\"להם\"\u0004 — שהם עצמם נקראים דור ראשון. \u0003ואי כתב רחמנא\u0004 \u0005[ואילו כתבה התורה]\u0006 רק \u0003\"להם\", הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003מצרית מעוברת שנתגיירה היא ובנה\u0004 (העובר) הם נחשבים \u0003חד\u0004 \u0005[אחד],\u0006 שהבן נחשב כחלק ממנה, וגם הוא ייחשב מצרי ראשון, על כן \u0003כתב רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"אשר יולדו\"\u0004 שהדבר תלוי בלידה, והוולד הזה נחשב מצרי שני.","\u0003ו\u0004עוד \u0003איצטריך למיכתב\u0004 \u0005[הוצרך לכתוב]\u0006 \u0003\"להם\" הכא\u0004 \u0005[כאן]\u0006 לגבי מצרי, לומר שהולכים אחרי הפסול, \u0003ואיצטריך למיכתב\u0004 \u0005[והוצרך לכתוב]\u0006 \u0003\"לו\" גבי\u0004 \u0005[אצל]\u0006 \u0003ממזר\u0004 (\"גם דור עשירי לא יבוא לו\". שם ג).","\u0003דאי כתב רחמנא הכא\u0004 \u0005[שאילו כתבה התורה\u0006 רק \u0005כאן]\u0006 במצרי, הייתי אומר כי רק בו הולכים אחרי פסול \u0003משום\u0004 שהוא \u0003בא\u0004 ונוצר \u0003מטיפה\u0004 (זרע) \u0003פסולה,\u0004 של מי שאינו ישראלי, \u0003אבל ממזר\u0004 ש\u0003בא מטיפה כשרה,\u0004 שהרי הוריו, אף שחטאו, ישראלים כשרים היו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן השמיע לנו בממזר.","\u0003ו\u0004להיפך: \u0003אי כתב רחמנא\u0004 \u0005[אילו כתבה התורה]\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003ממזר\u0004 הייתי אומר \u0003משום\u0004 ש\u0003אין\u0004 הוא \u0003ראוי\u0004 לבוא \u0003בקהל לעולם, אבל הכא\u0004 \u0005[כאן]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 לכן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שניהם.","\u0003אמר רבה בר בר חנה אמר ר' יוחנן: מצרי שני שנשא מצרית ראשונה — בנה שלישי הואי\u0004 \u0005[הוא].\u0006 ומעירים: \u0003אלמא קסבר\u0004 \u0005[מכאן\u0006 ש\u0005סבור\u0006 הוא\u0005]\u0006 כי \u0003בתר דידיה שדינן ליה\u0004 \u0005[אחריו,\u0006 אחר האב, \u0005אנחנו מטילים,\u0006 מחשיבים \u0005אותו]\u0006 ולא לפי אמו,","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב יוסף\u0004 על כך ממה ששנינו, \u0003ר' טרפון אומר: יכולין ממזרים ליטהר\u0004 במשך הדורות. \u0003כיצד? ממזר נשא שפחה\u0004 — הרי \u0003הולד עבד. שחררו\u0004 אביו הממזר, שהוא בעל השפחה, את הוולד — \u0003נמצא\u0004 הוולד \u0003בן חורין,\u0004 וכשר. \u0003אלמא בתר דידה שדינן ליה\u0004 \u0005[מכאן\u0006 ש\u0005אחריה,\u0006 אחרי האשה, \u0005אנחנו מטילים,\u0006 מחשיבים \u0005אותו],\u0006 שאומרים שהוולד איננו ממזר אלא עבד! ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 בעבדים ש\u0003אמר קרא\u0004 \u0005[\u0006ה\u0005כתוב]:\u0006 \u0003\"האשה וילדיה תהיה לאדניה\"\u0004 (שמות כא, ד), ומכאן שלגבי שפחה אין הולכים כלל אחר האב.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו, \u0003אמר ר' יהודה: מנימין גר מצרי, היה לי חבר, מתלמידי ר' עקיבא, ואמר: אני מצרי ראשון, ונשאתי מצרית ראשונה, אשיא לבני מצרית שניה, כדי שיהא בן בני ראוי לבא בקהל. ואי סלקא דעתך בתריה דידיה שדינן ליה\u0004 \u0005[ואם עולה על דעתך\u0006 לומר ש\u0005אחריו אנחנו מטילים,\u0006 מחשיבים \u0005אותו\u0006 את הוולד\u0005]\u0006 \u0003אפילו\u0004 אם ישא אותו בן מצרית \u0003ראשונה נמי\u0004 \u0005[גם כן]\u0006 יהיה בן בנו מותר! ומשיבים: \u0003הא אמר ליה\u0004 \u0005[הרי\u0006 כבר \u0005אמר לו]\u0006 \u0003ר' יוחנן לתנא: תני\u0004 \u0005[שנה]\u0006 מצרית \u0003ראשונה.\u0004","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן\u0004 להיפך: \u0003מצרי שני שנשא מצרית ראשונה — בנה שני הואי\u0004 \u0005[הוא].\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 אנו רואים כי \u0003בתר אימיה שדינן ליה\u0004 \u0005[אחר אמו אנחנו מטילים,\u0006 מחשיבים \u0005אותו],\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' יוחנן: הפריש\u0004 קרבן \u0003חטאת\u0004 (המובא מן הנקיבה) כשהיא \u0003מעוברת, וילדה\u0004 אחר כך נקיבה, אם \u0003רצה — מתכפר בה\u0004 והוולד ירעה עד שיפול בו מום וייפדה ויפלו דמיו לנדבה, ואם \u0003רצה — מתכפר בולדה\u0004 והיא עצמה תרעה עד שיפול בה מום.","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003עובר לאו\u0004 \u0005[לא]\u0006 \u0003ירך אמו הוא\u0004 אלא נחשב כיצור בפני עצמו, למרות שאיננו נפרד ממנה עדיין — \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כמפריש שתי חטאות לאחריות,\u0004 שאדם החושש שמא יאבד קרבן חטאתו ומפריש שתים, שישתמש בכל אחת מהן שירצה, \u0003ואמר\u0004 על כך \u0003רב אושעיא: הפריש שתי חטאות לאחריות — מתכפר באחת מהן, והשניה תרעה\u0004 עד שיפול בה מום, ותיפדה.","\u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003עובר ירך אמו הוא\u0004 ונחשב כחלק ממנה, אם כן \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003ולד חטאת, וולד חטאת למיתה אזיל\u0004 \u0005[הולך],\u0006 שאין מניחים לוולד הזה לרעות, אלא גורמים לו שימות כיון שנתקדש בקדושת חטאת אגב אמו, ובודאי אי אפשר להתכפר בו. נמצא שר' יוחנן עצמו סבור כי אין הוולד נחשב כחלק מאמו, ומדוע בענין המצרי אומרים שהולך אחר אמו?","\u0003אישתיק\u0004 \u0005[שתק]\u0006 רב דימי שלא מצא דרך להשיב לו לפי שעה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי מדעת עצמו: \u0003דלמא שאני התם\u0004 \u0005[שמא שונה שם]\u0006 בענין מצרי ומצרית, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בהם \u0003\"אשר יולדו\"\u0004 (דברים כג, ט), כלומר, \u0003הכתוב תלאו בלידה,\u0004 ולכן הכל תלוי בלידת הבנים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב דימי: אכן \u0003קרקפנא\u0004 (בעל ראש) כלומר, אדם גדול וחשוב, \u0003חזיתיה לרישך ביני עמודי\u0004 \u0005[ראיתי את ראשך בין העמודים]\u0006 של בית המדרש בטבריה \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אמר ר' יוחנן להא שמעתא\u0004 \u0005[את ההלכה הזו],\u0006 כלומר, כיוונת ממש לדברי ר' יוחנן כאילו היית שם.","ומבררים עוד את הנושא, \u0003טעמא\u0004 \u0005[הטעם],\u0006 דווקא כאן במצרי, משום \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אשר יולדו\"\u0004 ולכן הולכים הוולדות אחר האם דווקא, \u0003הא בעלמא\u0004 \u0005[הרי בכלל],\u0006 בשאר אסורי קהל — \u0003בתר אבוה שדינן ליה\u0004 \u0005[אחרי אביו אנו מטילים אותו].\u0006 ושואלים: \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רבא: גויה מעוברת שנתגיירה — בנה\u0004 (שהיה אז עובר), \u0003אין צריך טבילה. אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין צריך טבילה?\u0004 הרי אין הוא הולך אחר אמו!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהטעם הוא \u0003משום\u0004 מה שאמר \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: דבר תורה,\u0004 כלומר, דין תורה עצמו לענין טבילה הוא: אם היה \u0003רובו\u0004 של הטובל מכוסה \u0003ו\u0004חוצץ בדבר שהוא \u0003מקפיד עליו,\u0004 שמעונין להסירו — הרי זה \u0003חוצץ\u0004 כל עוד לא הסירו, והטבילה אינה טבילה, אבל \u0003רובו שאינו מקפיד עליו,\u0004 שאינו מעונין להסירו — \u0003אינו חוצץ.\u0004 לפי שיטה זו אפשר לומר שהעובר שהיה מכוסה במעטה (בגוף אמו) אך כיון שאיננו מקפיד עליו, שהרי צריך לה, אפשר לחשוב זאת כאילו העובר עצמו טבל במים."],["\u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב כהנא: לא שנו\u0004 שאם אין מקפיד עליו אינו חוצץ \u0003אלא\u0004 כשמכוסה \u0003רובו, אבל\u0004 אם מכוסה \u0003כולו\u0004 — \u0003חוצץ\u0004 מדין תורה, אפילו אם אינו מקפיד! ומשיבים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003עובר דהיינו רביתיה\u0004 \u0005[שזהו\u0006 טבע \u0005גידולו],\u0006 שמאחר וזהו מקום גידולו, אין לומר שרחם אמו מהווה חציצה עבורו, ולכן נחשב לו כאילו הוא עצמו טבל.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רבינא\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן:\u0004 לענין יוחסין, \u0003באומות,\u0004 בעודם גויים, \u0003הלך אחר הזכר,\u0004 ואם נישאו לאחר ש\u0003נתגיירו — הלך אחר\u0004 ה\u0003פגום שבשניהם.\u0004 ומסבירים: \u0003באומות הלך אחר הזכר — כדתניא\u0004 \u0005[כ\u0006מו \u0005ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003מנין לאחד מן האומות שבא על הכנענית והוליד בן, שאתה רשאי לקנותו בעבד\u0004 ואיננו קרוי כנעני שאסור לקיימו בארץ — \u0003שנאמר: \"וגם מבני התושבים הגרים עמכם מהם תקנו\"\u0004 (ויקרא כה, מה).","\u0003יכול אפילו אחד מן הכנענים שבא על אחת מן האומות והוליד\u0004 ממנה \u0003בן, שאתה רשאי לקנותו בעבד — תלמוד לומר: \"אשר הולידו בארצכם\"\u0004 (שם), לומר: \u0003מן הנולדים בארצכם,\u0004 שאמם ודאי כנענית, שכן מדרך האשה שלא לצאת ממקומה, ואם נולד בארץ ודאי שאמו היא הכנענית ומותר לקנותו, \u0003ולא מן הגרים בארצכם,\u0004 כלומר, לא מבני הכנענים שנולדו בחוץ לארץ (ואמם מן האומות ואינה כנענית, שאם היתה כנענית לא היתה יוצאת ממקומה) והיו גרים בארץ, שבאו לגור בארץ אצל אביהם, שאותם אסור להחזיק אפילו כעבדים מכיון שמתייחסים אחרי אביהם הכנעני. שמסתבר שלא בא הכתוב לאסור אלא את זה שאביו כנעני.","שנינו שאם \u0003נתגיירו הלך אחר פגום שבשניהם.\u0004 ושואלים: \u0003במאי\u0004 \u0005[במה,\u0006 באיזה מקרה מדובר כאן\u0005]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003במצרי שנשא עמונית — מאי\u0004 \u0005[מה]\u0006 \u0003פגום שבשניהם אית\u0004 \u0005[יש]\u0006 \u0003בה?\u0004 שכיון שההלכה היא \u0003עמוני ולא עמונית\u0004 הרי היא איננה פגומה כלל! \u0003אלא\u0004 מדובר \u0003בעמוני שנשא מצרית.\u0004 ואז, \u0003אי\u0004 \u0005[אם]\u0006 הילד \u0003זכר הוי\u0004 \u0005[הוא] —\u0006 \u0003שדייה בתר\u0004 \u0005[הטל אותו אחר]\u0006 אביו ה\u0003עמוני,\u0004 וייחשב כעמוני ופסול לבוא בקהל לעולם, \u0003אי\u0004 \u0005[אם]\u0006 \u0003נקבה הוי\u0004 \u0005[היא]\u0006 — \u0003שדייה בתר\u0004 \u0005[הטל אותה אחר]\u0006 ה\u0003מצרית\u0004 ותיחשב כמצרית שניה.","\u0003ממזרין ונתינין\u0004 (בני הגבעונים שנתגיירו בזמן יהושע) \u0003אסורין\u0004 לבוא בקהל, \u0003ואיסורן איסור עולם\u0004 לכל דורותיהם, \u0003אחד זכרים ואחד נקבות.\u0004","\u0003אמר ריש לקיש: ממזרת לאחר עשרה דורות מותרת.\u0004 כיצד? \u0003יליף\u0004 \u0005[לומד]\u0006 \u0003\"עשירי\" \"עשירי\"\u0004 בגזירה שווה \u0003מעמוני ומואבי,\u0004 שנאמר בממזר: \"לא יבוא ממזר בקהל ה' גם דור עשירי לא יבוא לו בקהל ה'\" (דברים כג, ג), ונאמר בעמוני ומואבי: \"לא יבוא עמוני ומואבי בקהל ה' גם דור עשירי לא יבוא להם בקהל ה'\" (שם ד), וכך הוא לומד: \u0003מה להלן\u0004 בעמוני ומואבי \u0003נקבות מותרות — אף כאן נקבות מותרות.\u0004","ומקשים: \u0003אי\u0004 \u0005[או]\u0006 \u0003מה להלן\u0004 בעמוני, הנקבות מותרות \u0003מיד, אף כאן\u0004 בממזר יהיו מותרות \u0003מיד!\u0004 ומשיבים: \u0003כי אהני\u0004 \u0005[כאשר הועילה]\u0006 ה\u0003גזירה שוה,\u0004 הרי זה \u0003מ\u0004דור \u0003עשירי ואילך.\u0004","ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ממזרים ונתינין אסורין, ואיסורן איסור עולם, אחד זכרים ואחד נקבות!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 לריש לקיש, משום שהוא סבור שיש מחלוקת בדבר; \u0003הא\u0004 \u0005[זה]\u0006 דברי ריש לקיש, \u0003כמאן דאמר דון מינה ומינה\u0004 \u0005[כ\u0006דעת \u0005מי שאומר למד ממנה וממנה],\u0006 כלומר, כאשר למדים דבר מדבר בגזירה שווה אין זה מוגבל רק לפרט אחד, אלא ממשיכים להשוות את שני הנושאים ככל האפשר גם בצדדים אחרים. וכן כאן, אף שעיקר הגזירה־שווה היתה לאסור ממזר איסור עולם, אולם ממשיכים עוד ולומדים היתר הנקיבה לאחר עשרה דורות.","\u0003הא כמאן דאמר דון מינה ואוקי באתרא\u0004 \u0005[זה,\u0006 משנתנו, \u0005כמי שאומר למד ממנה והעמד במקומה],\u0006 ולכן אפשר ללמוד דבר חדש רק למקומו, לענין מוגדר אחד, ואין ללמוד ממנו לענין אחר.","מובא כי \u0003שאלו את ר' אליעזר: ממזרת לאחר עשרה דרי\u0004 \u0005[דורות]\u0006 \u0003מהו\u0004 דינה? \u0003אמר להם: מי יתן לי דור שלישי\u0004 לממזרים, \u0003ואטהרנו,\u0004 כלומר, שאין הדבר שייך. ומעירים: \u0003אלמא קסבר ממזרא לא חיי\u0004 \u0005[מכאן\u0006 ש\u0005סבור\u0006 הוא ש\u0005ממזר איננו חי],\u0006 שמשמים גורמים לו שימות, ולכן אין שאלה זו מעשית. \u0003וכן אמר רב הונא: ממזרא לא חיי\u0004 \u0005[ממזר אינו חי].\u0006","ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003ממזרין אסורין ואיסורן איסור עולם\u0004 וכיצד יתכן הדבר אם אינו חי עד שיהיו ממנו אפילו שלושה דורות! \u0003אמר ר' זירא: לדידי מפרשא לי מיניה\u0004 \u0005[לי נתפרש\u0006 הדבר \u0005ממנו]\u0006 מאת \u0003רב יהודה: דידיע\u0004 \u0005[\u0006מי \u0005שידוע\u0006 כממזר\u0005]\u0006 — \u0003חיי\u0004 \u0005[חי]\u0006 הוא, כיון שאין חשש שיתערבו בו, ואולם זה \u0003דלא ידיע\u0004 \u0005[שאינו ידוע] —\u0006 \u0003לא חיי\u0004 \u0005[אינו חי],\u0006 אלא משמים ממיתים אותו כדי שלא יתערבו בו. \u0003דידיע ולא ידיע\u0004 \u0005[שידוע ואינו ידוע\u0006 בבירור\u0005]\u0006 אם ממזר הוא — \u0003עד תלתא דרי חיי\u0004 \u0005[שלושה דורות חי],\u0006 \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005]\u0006 — \u0003לא חיי\u0004 \u0005[אינו חי].\u0006","מסופר: \u0003ההוא דהוי בשבבותיה\u0004 \u0005[אדם אחד שהיה בשכנותו]\u0006 של \u0003ר' אמי\u0004 ולאחר בירור \u0003אכריז עליה דממזרא הוה\u0004 \u0005[הכריז עליו שממזר הוא].\u0006 \u0003בכי ואזיל\u0004 \u0005[היה בוכה והולך],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אמי: אין לך להצטער כל כך, שיש בכך גם יתרון כי \u0003חיים נתתי לך,\u0004 שהרי כפי שהסברנו כאשר הממזר מפורסם הוא יכול לחיות.","\u0003אמר רב חנא בר אדא: נתינים — דוד\u0004 המלך הוא ש\u0003גזר עליהם\u0004 שיהיו פסולים לבוא בקהל, \u0003שנאמר: \"ויקרא המלך לגבענים ויאמר אליהם והגבענים לא מבני ישראל המה\u0004 כי אם מיתר האמורי\u0003\"\u0004 (שמואל ב' כא, ב), שאפשר ללמוד מכאן שדוד הוא שקבע שאינם כבני ישראל, ולא יבואו בקהל ישראל, למרות שהתגיירו.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003גזר עלייהו\u0004 \u0005[עליהם]?\u0006 כדי להסביר את הדבר מביאים את כל השתלשלות הדברים. \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי רעב בימי דוד שלש שנים שנה אחרי שנה\"\u0004 (שם כא, א). \u0003שנה ראשונה אמר להם\u0004 דוד לבני ישראל: \u0003שמא עובדי עבודה זרה יש בכם,\u0004 וחטא זה הוא שגורם לעצירת גשמים, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועבדתם אלהים אחרים והשתחויתם להם.\u0004 וחרה אף ה' בכם \u0003ועצר את השמים ולא יהיה מטר וגו'\"\u0004 (דברים יא, טז-יז). \u0003בדקו, ולא מצאו\u0004 עוברי עבירה זו.","שנה \u0003שניה\u0004 שלא ירדו גשמים \u0003אמר להם: שמא עוברי עבירה\u0004 בזנות \u0003יש בכם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וימנעו רבבים ומלקוש לוא היה ומצח אשה זונה היה לך\u0004 מאנת הכלם\u0003\"\u0004 (ירמיהו ג, ג) מלמד שבגלל זנות יש עצירת גשמים. \u0003בדקו, ולא מצאו.\u0004","שנה \u0003שלישית אמר להם: שמא פוסקי צדקה ברבים יש בכם,\u0004 שמפרסמים ברבים שהם נותנים צדקה \u0003ו\u0004באמת \u0003אין נותנין, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נשיאים ורוח וגשם אין איש מתהלל במתת שקר\"\u0004 (משלי כה, יד), שמכלל זה נלמד גם שהמתהלל במתת שקר גורם שלא יהיה גשם. \u0003בדקו, ולא מצאו.\u0004","כיון שבדקו בכל ישראל אותם דברים שגורמים לעצירת גשם ולא מצאו, \u0003אמר: אין הדבר תלוי אלא בי, מיד: \"ויבקש דוד את פני ה'\"\u0004 (שמואל ב' כא, א). ושואלים \u0003מאי היא\u0004 \u0005[מה הוא]\u0006 כיצד עשה זאת? \u0003אמר ריש לקיש: ששאל באורים ותומים.\u0004","שואלים: \u0003מאי משמע\u0004 \u0005[מה המשמעות],\u0006 איך משתמע הדבר מהכתוב שמדובר באורים ותומים? \u0003אמר ר' אלעזר: אתיא\u0004 \u0005[בא,\u0006 נלמד\u0005]\u0006 הדבר בגזירה שווה \u0003\"פני\" \"פני\". כתיב הכא\u0004 \u0005[נאמר כאן]:\u0006 \u0003\"ויבקש דוד את פני ה'\" וכתיב התם\u0004 \u0005[ונאמר שם]:\u0006 \u0003\"ושאל לו במשפט האורים לפני ה'\"\u0004 (במדבר כז, כא), משמע שזה הוא הקרוי \"לפני ה'\".","בהמשך אותו ענין נאמר: \u0003\"ויאמר ה' אל שאול ואל בית הדמים על אשר המית את הגבענים\"\u0004 (שמואל ב' כא, א), ומסבירים: \u0003\"אל שאול\"\u0004 — שנענשו ישראל על \u0003שלא נספד כהלכה, \"ואל בית הדמים\" — \"על אשר המית את הגבענים\",\u0004 ותוהים: \u0003וכי היכן מצינו בשאול שהמית\u0004 את \u0003הגבעונים?\u0004 ומסבירים: \u0003אלא מתוך שהרג נוב עיר הכהנים שהיו\u0004 הכהנים \u0003מספיקין להם,\u0004 לגבעונים, \u0003מים ומזון\u0004 בשכר עבודתם, \u0003מעלה\u0004 (מחשיב) \u0003עליו הכתוב כאילו\u0004 הוא עצמו \u0003הרגן.\u0004","ותוהים: \u0003קא תבע\u0004 \u0005[תובע]\u0006 הקדוש ברוך הוא מצד אחד \u0003אל שאול שלא נספד כהלכה וקא תבע\u0004 \u0005[ותובע]\u0006 מצד שני \u0003על אשר המית הגבעונים\u0004 ונענשים על חטאיו?! ומשיבים: \u0003אין\u0004 \u0005[כן]\u0006 הוא, וכך צריך להיות, ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"בקשו את ה' כל ענוי\u0004 ה\u0003ארץ אשר משפטו פעלו\"\u0004 (צפניה ב, ג), \u0003באשר משפטו\u0004 לדין ולחובה — \u0003שם פעלו\u0004 להזכיר את פעלו הטוב של האדם.","\u0003אמר דוד:\u0004 לגבי הספדו של \u0003שאול, נפקו להו\u0004 \u0005[יצאו להם\u0006 כבר\u0005]\u0006"],["\u0003תריסר ירחי שתא\u0004 \u0005[שנים עשר חדשי שנה],\u0006 כלומר, מעבר לתקופת האבל של שנים עשר חודש כבר עברו כמה וכמה שנים, \u0003ולא דרכיה למספדיה\u0004 \u0005[ואין הדרך לספוד אותו]\u0006 לאחר זמן כה רב,","ובנוגע ל\u0003נתינים\u0004 (הגבעונים) \u0003ניקרינהו ונפייסינהו\u0004 \u0005[נקרא להם ונפייס אותם].\u0006 ולכן נאמר: \u0003\"ויקרא המלך לגבענים ויאמר אליהם... מה אעשה לכם ובמה אכפר וברכו את נחלת ה'. ויאמרו לו הגבענים אין לנו כסף וזהב עם שאול ועם ביתו ואין לנו איש וגו' יתן לנו שבעה אנשים מבניו והוקענום לה' וגו'\"\u0004 (שמואל ב' כא, ב-ו), \u0003מיפייס ולא פייסינהו\u0004 \u0005[\u0006ניסה ל\u0005פייסם\u0006 בדברים אחרים \u0005ולא התפייסו].\u0006","\u0003אמר\u0004 דוד: \u0003שלשה סימנים יש באומה זו\u0004 של ישראל, שהם \u0003הרחמנים, והביישנין, וגומלי חסדים. רחמנים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ונתן לך רחמים ורחמך והרבך\"\u0004 (דברים יג, יח). \u0003ביישנין — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ו\u0003בעבור תהיה יראתו על פניכם\"\u0004 (שמות כ, יז), ויראה שעל פניו של אדם היא ביישנותו. \u0003גומלי חסדים — דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"למען אשר יצוה את בניו ואת ביתו\u0004 אחריו ושמרו דרך ה' לעשות צדקה ומשפט\u0003\"\u0004 (בראשית יח, יט). \u0003כל שיש בו שלשה סימנים הללו — ראוי להדבק באומה זו\u0004 של ישראל, ומי שאין בו תכונות אלה איננו ראוי להיות קשור בישראל, וכיון שראה דוד את אכזריותם של הגבעונים, גזר עליהם שלעולם לא יתערבו עוד בישראל.","וממשיכים בהסברת סיפור המעשה, שנאמר: \u0003\"ויקח המלך את שני בני רצפה בת איה אשר ילדה לשאול את ארמני ואת מפבשת ואת חמשת בני מיכל בת שאול אשר ילדה לעדריאל בן ברזלי המחלתי\"\u0004 (שמואל ב' כא, ח). ושואלים: \u0003מאי שנא הני\u0004 \u0005[\u0006ב\u0005מה שונים אלה]\u0006 שבחר דווקא בהם ולא מצאצאי שאול האחרים? \u0003אמר רב הונא: העבירום\u0004 את צאצאי שאול \u0003לפני ארון\u0004 הברית, \u0003כל שארון קולטו\u0004 שנדבק לשם ולא יכול לזוז — \u0003למיתה, כל שאין ארון קולטו — לחיים.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חנא בר קטינא\u0004 נאמר: \u0003\"ויחמל המלך על מפיבשת בן יהונתן בן שאול\"\u0004 (שם ז), ואם בארון היה הדבר תלוי — מה מקום לחמלת המלך? ומשיבים: \u0003שלא העבירו\u0004 לפני הארון כלל.","ומעתה שואלים לגוף הדבר: \u0003וכי משוא פנים יש בדבר?\u0004 שאם מוסרים את ההחלטה בידי שמים, מדוע התערב דוד בדיני נפשות ומדוע לא העבירו? \u0003אלא\u0004 עונים בדרך אחרת: \u0003שהעבירו וקלטו\u0004 הארון, \u0003ובקש עליו\u0004 דוד \u0003רחמים, ופלטו.\u0004 ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 קשה: וכי \u0003משוא פנים יש בדבר? אלא, שבקש רחמים שלא יקלטנו הארון.\u0004 ולא עשה מעשה אחר.","על עצם המעשה המתואר במקרא מקשים, \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"לא יומתו אבות על בנים\u0004 ובנים לא ימותו על אבות איש בחטאו יומתו\u0003\"\u0004 (דברים כד, טז), ובני שאול לא חטאו כלל, ומדוע הומתו? \u0003אמר ר' חייא בר אבא אמר ר' יוחנן: מוטב שתעקר אות אחת\u0004 (ומצוה אחת) \u0003מן התורה\u0004 באופן כזה, \u0003ואל יתחלל שם שמים בפרהסיא.\u0004 שהרי המתת הגבעונים על ידי עם ישראל היה בה חילול השם, וכדי לתקן את הדבר עשו על פי דבריהם, למרות שהם נגד מצוות התורה.","נאמר שם: \u0003\"ותקח רצפה בת איה את השק ותטהו לה אל הצור מתחלת קציר עד נתך מים עליהם מן השמים ולא נתנה עוף השמים לנוח עליהם יומם ו\u0004את \u0003חית השדה לילה\"\u0004 (שמואל ב' כא, י), שלא ניתנו לקבורה עד ימות הגשמים. ומקשים: וכיצד זה השאירום בלא קבורה כל אותו זמן \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 במחוייבי מיתה: \u0003\"לא תלין נבלתו על העץ\"\u0004 (דברים כא, כג)!","\u0003אמר ר' יוחנן משום ר' שמעון בן יהוצדק: מוטב שתעקר אות אחת מן התורה ויתקדש שם שמים בפרהסיא.\u0004 כיצד? \u0003שהיו עוברים ושבים\u0004 מן הגויים \u0003אומרים: מה טיבן של אלו\u0004 התלויים כאן כל אותו זמן? אמרו להם: \u0003הללו בני מלכים הם.\u0004 ומששאלו \u0003ומה עשו\u0004 שנידונו בכך? היו עונים להם: \u0003פשטו ידיהם\u0004 וגרמו נזק \u0003בגרים גרורים,\u0004 כלומר, לא גרים של אמת אלא גרים שנגררו אחר עם ישראל רק מתוך חשבון. \u0003אמרו\u0004 אותם עוברים ושבים: \u0003אין לך אומה שראויה להדבק בה כזו. ומה בני מלכים\u0004 הפוגעים בגרים \u0003כך\u0004 עושים להם, \u0003בני הדיוטות על אחת כמה וכמה! ומה גרים גרורים כך\u0004 נוהגים בהם, \u0003ישראל\u0004 עצמם \u0003על אחת כמה וכמה!\u0004","\u0003מיד נתוספו על ישראל מאה וחמשים אלף\u0004 גרים, \u0003שנאמר: \"ויהי לשלמה שבעים אלף נשא סבל ושמנים אלף חצב בהר\"\u0004 (מלכים א' ה, כט), וכל אלה, מן הגרים היו. ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003ישראל הוו\u0004 \u0005[היו]\u0006 אותם החוצבים והסבלים? ומשיבים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה על דעתך],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006הרי \u0005נאמר]:\u0006 \u0003\"ומבני ישראל לא נתן שלמה עבד\"\u0004 (שם ט, כב).","ומקשים: מי אמר שפועלים אלה היו עבדים, \u0003ודלמא דוגזר בעלמא\u0004 \u0005[ושמא שכירות סתם]\u0006 היתה זו שעבדו עבור המדינה, ולא כעבדים. \u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 נלמד הדבר, שנאמר: \u0003\"ויספר שלמה כל האנשים הגירים אשר בארץ ישראל\u0004 אחרי הספר אשר ספרם דוד אביו \u0003וימצאו מאה וחמשים אלף\u0004 ושלושת אלפים ושש מאות. \u0003ויעש מהם שבעים אלף (נשא) סבל ושמנים אלף חצב בהר\u0004 ושלושת אלפים ושש מאות מנצחים להעביד את העם\u0003\"\u0004 (דברי הימים ב' ב, טז-יז), משמע שאותם סבלים וחוצבים אכן היו גרים, ומספר זה של גרים בא מן הגרים שהתגיירו בשל קידוש השם שהיה בעונשם של צאצאי שאול.","ושוב חוזרים ממעשה זה לעיקרו של הדיון, \u0003ונתינים\u0004 האם \u0003דוד גזר עליהם?\u0004 הלא \u0003משה גזר עליהם, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מחטב עציך עד שאב מימיך\"\u0004 (דברים כט, י), משמע שהיה מעמד מיוחד של חוטבי עצים ושואבי מים גם בימי משה, מן הגרים הגרורים שנוספו בימיו, והיו כחטיבה לעצמה שאינה ככל ישראל! ומשיבים: \u0003משה גזר לההוא דרא\u0004 \u0005[לאותו דור]\u0006 בלבד, שישארו נפרדים, ואילו \u0003דוד גזר לכולי דרי\u0004 \u0005[לכל הדורות].\u0006","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 הרי \u0003יהושע\u0004 הוא ש\u0003גזר עלייהו\u0004 \u0005[עליהם],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויתנם יהושע ביום ההוא חטבי עצים ושאבי מים לעדה ולמזבח ה'\"\u0004 (יהושע ט, כז)! ומשיבים: \u0003יהושע גזר\u0004 גזירה זו \u0003בזמן שבית המקדש קיים\u0004 (\"למזבח ה\"'), ו\u0003דוד גזר\u0004 אף \u0003בזמן שאין בית המקדש קיים.\u0004"],["\u0003בימי רבי בקשו להתיר נתינים,\u0004 להשוותם לכל ענין לשאר ישראל ולהתירם לבוא בקהל. \u0003אמר להם רבי:\u0004 אם אמנם שאת \u0003חלקנו נתיר\u0004 ונאמר שבית דין מפקיר את זכות עם ישראל להעביד את הגבעונים, וייעשו כעבדים משוחררים, אולם את \u0003חלק\u0004 ה\u0003מזבח מי יתיר?\u0004 והלא הם שייכים גם למקדש ולמזבח!","ומעירים: \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 דעה זו על מה שאמר \u0003ר' חייא בר אבא.\u0004 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: חלק עדה,\u0004 אותו חלק בשיעבוד הגבעונים לעדה — \u0003לעולם אסור\u0004 ואין לו היתר, \u0003חלק מזבח, בזמן שבית המקדש קיים — אסור,\u0004 בזמן ש\u0003אין בית המקדש קיים — שרי\u0004 \u0005[מותר].\u0006","\u0003אמר ר' יהושע: שמעתי\u0004 בשם רבותי \u0003שהסריס חולץ וחולצין לאשתו, ו\u0004שמעתי גם ש\u0003הסריס לא חולץ ולא חולצין לאשתו, ואין לי\u0004 דרך \u0003לפרש\u0004 את הסתירה הזו שבין המסורות הללו.","\u0003אמר ר' עקיבא: אני אפרש, סריס אדם,\u0004 כלומר, מי שנסתרס לאחר שנולד — \u0003חולץ וחולצין לאשתו, מפני שהיתה לו שעת הכושר\u0004 (שעה שהיה כשר בה). ואילו \u0003סריס חמה,\u0004 שנולד כשהוא סריס — \u0003לא חולץ ולא חולצין לאשתו, מפני שלא היתה לו שעת הכושר,\u0004 שהרי מתחילתו היה בגדר סריס, שלא היה מסוגל להוליד.","\u0003ר' אליעזר אומר: לא כי, אלא\u0004 להיפך: \u0003סריס חמה — חולץ וחולצין לאשתו, מפני שיש לו רפואה, סריס אדם — לא חולץ ולא חולצין לאשתו, מפני שאין לו רפואה.\u0004","\u0003העיד ר' יהושע בן בתירא על\u0004 אחד ושמו \u0003בן מגוסת שהיה בירושלים\u0004 והיה \u0003סריס אדם, ויבמו את אשתו, לקיים\u0004 ולאשר את \u0003דברי ר' עקיבא.\u0004","\u0003הסריס\u0004 חמה \u0003לא חולץ ולא מייבם, וכן איילונית,\u0004 אשה שיש בה פגם מהותי בכושר הרבייה ואינה יכולה ללדת — \u0003לא חולצת ולא מתייבמת.\u0004","\u0003הסריס שחלץ ליבמתו — לא פסלה\u0004 על ידי כך לכהונה, שחליצתו אינה נחשבת לחליצה. אולם אם \u0003בעלה — פסלה,\u0004 ומדוע, \u0003מפני שהיא בעילת זנות.\u0004 שכן ביאתו אין בה מצות ייבום ויש בה עבירה שבא על אשת אחיו. \u0003וכן איילונית שחלצו לה אחין\u0004 — \u0003לא פסלוה,\u0004 אבל אם \u0003בעלוה — פסלוה, מפני שבעילתה\u0004 להם \u0003בעילת זנות\u0004 היא.","שואלים: \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003שמעינן\u0004 \u0005[שומעים,\u0006 יודעים \u0005אנו]\u0006 כי \u0003ל\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 ש\u0003חייבי לאוין כחייבי כריתות דמו\u0004 \u0005[נחשבים]\u0006 לענין תפיסת קידושין, וכל הנובע מכך, \u0003וחייבי כריתות לאו\u0004 \u0005[לא]\u0006 \u0003בני חליצה וייבום נינהו\u0004 \u0005[הם],\u0006 וכיון שסריס אדם הוא בגדר פצוע דכא, יש לגביו איסור לא תעשה שישא אשה מישראל, ואם עבר ונשא — אין נישואיו תופסים לר' עקיבא, ומדוע תיחשב איפוא חליצתו חליצה!","\u0003אמר ר' אמי: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כגון שנשא אחיו\u0004 של סריס \u0003גיורת, ור' עקיבא סבר לה\u0004 \u0005[סבור\u0006 בזה\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' יוסי,\u0004 ש\u0003אמר\u0004 כי \u0003קהל גרים לא אקרי\u0004 \u0005[אינו נקרא]\u0006 \u0003קהל,\u0004 ולכן גם האסורים לבוא בקהל מותרים לשאת גיורת.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003יבומי נמי מייבם\u0004 \u0005[\u0006יוכל הסריס \u0005גם כן לייבם]\u0006 את הגיורת! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[\u0006אמנם \u0005כן, כך\u0006 הוא \u0005גם כן]\u0006 \u0003ואיידי\u0004 \u0005[ומתוך]\u0006 ש\u0003אמר ר' יהושע חולץ\u0004 שלדעתו קהל גרים נקרא קהל, \u0003אמר איהו נמי\u0004 \u0005[הוא גם כן]\u0006 \u0003חולץ,\u0004 והוא הדין שלדעתו גם מייבם.","ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 שכך הוא פירוש הדברים, \u0003דקתני\u0004 \u0005[ששנה\u0006 במשנתנו\u0005]:\u0006 \u0003העיד ר' יהושע בן בתירא על בן מגוסת שהיה בירושלים\u0004 והיה \u0003סריס אדם ויבמו את אשתו לקיים\u0004 ולחזק את \u0003דברי ר' עקיבא,\u0004 משמע שלשיטת ר' עקיבא גם לייבם מותר. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכך הוא.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבה:\u0004 ממה ששנינו: \u0003פצוע דכא, וכרות שפכה, סריס אדם, והזקן\u0004 שאינם יכולים להוליד — \u0003או חולצין או מייבמין.\u0004 ומבואר \u0003כיצד: מתו\u0004 אלה \u0003ולהם נשים, ולהם אחין, ועמדו אחין ועשו מאמר בנשותיהן,\u0004 או \u0003נתנו גט, או שחלצו — מה שעשו עשו, ואם בעלו\u0004 האחים וייבמו את הנשים הללו — \u0003קנו,\u0004 כפי שזה בכל יבמה.","ואם \u0003מתו אחין\u0004 של אלו, \u0003ועמדו הן ועשו מאמר בנשותיהן\u0004 של האחים, או \u0003נתנו גט או חלצו — מה שעשו עשו. ואם בעלו\u0004 וייבמו את נשותיהם של האחים שמתו — \u0003קנו, ואסור\u0004 להם \u0003לקיימן, משום שנאמר: \"לא יבא פצוע דכה וכרות שפכה בקהל ה'\"\u0004 (דברים כג, ב), \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003ב\u0004תוך \u0003קהל\u0004 ה' \u0003עסקינן\u0004 \u0005[אנו עוסקים]\u0006 שיש בהם איסור זה, ולא בגרים!","\u0003אלא אמר רבה:\u0004 יש לפרש את המשנה \u0003כגון שנפלה לו\u0004 לאדם יבמה, \u0003ולבסוף נפצע\u0004 ונסתרס, שמתחילה חלה עליו מצות ייבום, ולפיכך חולצת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אם כן \u0003ליתי\u0004 \u0005[שיבוא]\u0006 \u0003איסור פצוע\u0004 דכא \u0003ונידחי\u0004 \u0005[וידחה]\u0006 את ה\u0003עשה\u0004 של \u0003ייבום! מי לא תנן\u0004 \u0005[האם לא שנינו\u0006 במשנה\u0005]\u0006 בכגון זה, \u0003רבן גמליאל אומר:\u0004 שני אחים נשואים לשתי אחיות ואחת מהן קטנה שהשיאוה אחיה, שאין נישואיה מדברי תורה, ומת הנשוי לגדולה, \u0003אם מיאנה\u0004 הקטנה בבעלה — \u0003מיאנה,\u0004 ובטלו נישואיה, ומייבם את אחותה,","\u0003ואם לאו\u0004 \u0005[לא]\u0006 \u0003— תמתין\u0004 הקטנה, ולא יבעל אותה \u0003עד שתגדיל,\u0004 שהרי היא אסורה משום אחות זקוקתו, \u0003ו\u0004אז \u0003תצא הלזו,\u0004 האחרת, \u0003משום אחות אשה. אלמא, אתי\u0004 \u0005[מכאן\u0006 ש\u0005בא]\u0006 \u0003איסור אחות אשה ודחי\u0004 \u0005[ודוחה]\u0006 את מצות הייבום שחלה עליו קודם. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003ניתי\u0004 \u0005[יבוא]\u0006 \u0003איסור פצוע\u0004 דכא, \u0003ונידחי\u0004 \u0005[וידחה]\u0006 את חיוב הייבום!","\u0003אלא אמר רב יוסף:\u0004 שיטת \u0003האי תנא\u0004 \u0005[תנא זה]\u0006 של משנתנו — שיטת \u0003הך תנא דבי\u0004 \u0005[תנא זה של בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' עקיבא היא.\u0004 ש\u0003אמר:\u0004 רק \u0003מחייבי לאוין\u0004 של \u0003שאר\u0004 (שיש בהם צד של קירבת משפחה) \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003ממזר, מחייבי לאוין גרידי\u0004 \u0005[סתם]\u0006 \u0003לא הוי\u0004 \u0005[אינו]\u0006 \u0003ממזר,\u0004 ויש איפוא תפיסת נישואין גם לסריס ויכול לחלוץ.","לגופה של ההלכה שואלים: מדוע חלה בכלל על הסריס מצות ייבום, \u0003איקרי\u0004 \u0005[אקרא]\u0006 \u0003כאן\u0004 את האמור בפרשת ייבום \u0003\"להקים לאחיו שם\"\u0004 (שם כה, ז), \u0003והא לאו בר הכי\u0004 \u0005[וזה אינו\u0006 יכול לעשות \u0005כן]\u0006 עכשיו, גם אם היתה לו קודם שעת הכושר, ומה מקום לדין ייבום כזה?","\u0003אמר רבא: אם כן,\u0004 שאתה אומר שכל שאינו ראוי להוליד אין מצות ייבום חלה עליו, גם אם היתה לו שעת הכושר מקודם, אם כן \u0003אין לך אשה שכשרה ליבם,\u0004 שגם אם מת בעלה בדרך הטבע, מן הנמנע \u0003שלא נעשה בעלה סריס חמה שעה אחת קודם למיתתו,\u0004 שוודאי באותה שעה לא היה מסוגל להוליד והריהו איפוא כסריס, ולא חלה כלל מצות ייבום! אלא ודאי, כיון שהיתה לו שעת הכושר לפני כן — נחשב הוא ראוי.","ומעירים: \u0003ל\u0004שיטת \u0003ר' אליעזר\u0004 במשנה שסריס אדם אינו חולץ, ואינו מתקשר בנישואין גם אם היתה לו קודם שעת הכושר, \u0003פירוקא\u0004 \u0005[התירוץ]\u0006 של \u0003רבא\u0004 שמוכיח מכל אדם שסמוך למותו הרי הוא כסריס, \u0003פירכא\u0004 \u0005[קושיה]\u0006 \u0003היא!\u0004","ומשיבים: ר' אליעזר סבור כי אין אדם סמוך למיתה נחשב לסריס, ומה שאינו מסוגל להוליד אז הוא כי \u0003התם כחישותא דאתחילה ביה\u0004 \u0005[שם, חולשה שהתחילה בו]\u0006 סמוך למותו, שאינו מסוגל לבוא על אשה, אבל אין זה פגם בכושר ההולדה שלו.","ובבירור הדברים למעשה שואלים: \u0003היכי דמי\u0004 \u0005[כיצד זה בדיוק]\u0006 \u0003סריס חמה? אמר רב יצחק בר יוסף אמר ר' יוחנן: כל\u0004"],["\u0003שלא ראה שעה אחת בכשרותו,\u0004 אלא שנולד סריס. ושואלים: \u0003מנא ידעינן\u0004 \u0005[מניין יודעים אנו]\u0006 באדם שהוא סריס חמה ולא היה ראוי מימיו? \u0003אמר אביי: כל המטיל מים ואינו עושה כיפה\u0004 (כעין קשת) בהטלת המים, אלא מי הרגליים שלו שותתים תחתיו — סריס הוא מתחילתו.","ואגב שואלים: \u0003ממאי הואי\u0004 \u0005[ממה הוא\u0006 נעשה\u0005]\u0006 מום זה? ומשיבים: \u0003דאפיה אימיה בטיהרא ושתיא שיכרא מרקא\u0004 \u0005[שאופה אמו\u0006 לחם \u0005ב\u0006שעת \u0005הצהריים ושותה שיכר חריף]\u0006 בזמן ההריון, שמחמת חימום הגוף נוצר ליקוי זה בילד. \u0003אמר רב יוסף: היינו דשמענא לאמי דאמר\u0004 \u0005[הוא ששמעתי\u0006 מר' \u0005אמי שהיה אומר]\u0006 ביטוי זה: \u0003\"כל שממעי אמו לקוי\", ולא ידענא מאי ניהו\u0004 \u0005[ידעתי מה הוא,\u0006 מה מובנו\u0005]\u0006 ולאיזה ענין הוא נוגע, ועכשיו אני מבין שפירש מהו סריס חמה.","ושואלים: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא הבריא בינתים,\u0004 במשך הזמן, בלא שנדע, והיתה לו שעת הכושר! ומשיבים: \u0003כיון\u0004 ש\u0003תחלתו וסופו לקוי — לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 לכך.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב מרי\u0004 ממה ששנינו בהלכות בכורות, \u0003ר' חנינא בן אנטיגנוס אומר: בודקין אותו\u0004 את הבכור שנפל בו מום של סנוורים בעין \u0003שלש פעמים בתוך שמונים יום\u0004 שמא הבריא. משמע שאין אנחנו סומכים על החזקה בזה, וחוששים שמא הבריא בינתים אף שבתחילה ובסוף היה חולה, וממילא היתה לו שעת הכושר!","ומשיבים: \u0003לחד אבר חיישינן\u0004 \u0005[לאבר אחד,\u0006 כגון עין, \u0005חוששים אנו]\u0006 שמא הבריא ואחר כך חלה שוב, ואולם \u0003לכוליה גופא לא חיישינן\u0004 \u0005[לכל הגוף אין אנו חוששים],\u0006 כי הסריס איננו לקוי באבר אחד בלבד, אלא יש בו פגם המשפיע על כל גופו, ואין לחשוש שנעשה בו שינוי כזה וחזר בינתיים שוב לבריאותו.","שנינו במשנה: \u0003ר' אליעזר אומר לא כי\u0004 אלא סריס חמה חולץ, ולא סריס אדם \u0003וכו'. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003בן עשרים שנה ולא הביא שתי שערות\u0004 שהם סימן בגרות — \u0003יביאו ראיה שהוא בן עשרים, והוא הסריס,\u0004 ולענין ייבום — \u0003לא חולץ ולא מייבם.\u0004 היתה אשה \u0003בת עשרים ולא הביאה שתי שערות — יביאו ראיה שהיא בת עשרים, והיא האילונית — לא חולצת ולא מתייבמת,\u0004 אלו \u0003דברי בית הלל. ובית שמאי אומרים: זה וזה בני שמנה עשרה\u0004 ולא בני עשרים.","\u0003ר' אליעזר אומר: הזכר כדברי בית הלל, ונקבה כדברי בית שמאי, מפני שהאשה ממהרת לבא\u0004 לבגרות \u0003לפני האיש,\u0004 ואם לא נראו בה הסימנים עד גיל שמונה עשרה מן הסתם איילונית היא. על כל פנים מובן מן הדברים שסריס כזה, שהוא סריס חמה, אינו חולץ ואינו מייבם, וגם ר' אליעזר מסכים לכך!","\u0003אמר רמי בר דיקולי אמר שמואל: חזר בו ר' אליעזר\u0004 ושינה את דעתו. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהי הדר ביה\u0004 \u0005[מאיזו חזר בו]?\u0006 האם חזר בו ממה שאמר במשנה שסריס חמה חולץ וחולצים לאשתו, או שמא במשנתנו מובאת דעתו האחרונה שחזר בו ממה שאמר במשנה אחרת. ומציעים: \u0003תא שמע\u0004 \u0005[בא\u0006 ו\u0005שמע],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: סריס חמה חולץ וחולצין לאשתו, שכן במינן מתרפאין באלכסנדריא של מצרים.\u0004 משמע ממקור נוסף זה שלא חזר בו מן הדעה שאמר במשנתנו, אלא ממה שאמר כדברי בית הלל ובית שמאי ודעתו כפי שהיא מובאת במשנתנו, היא האחרונה.","\u0003ר' אלעזר אומר: לעולם לא הדר ביה\u0004 \u0005[חזר בו]\u0006 כלל ולא שינה דעתו. \u0003וכי תנן\u0004 \u0005[וכאשר שנינו]\u0006 את המשנה \u0003ההיא\u0004 מה שאמר ר' אליעזר בדבר גילו של סריס — \u0003ל\u0004ענין \u0003עונשין\u0004 נאמר, ממתי הוא נחשב כמבוגר ובן עונשין, ולא לענין חליצה וייבום.","ואכן \u0003איתמר\u0004 \u0005[נאמר]:\u0006 מי ש\u0003אכל חלב,\u0004 או עבר עבירה אחרת שחייבים עליה מלקות או כרת, כשהיה \u0003מבן שתים עשרה\u0004 שנה \u0003ויום אחד עד בן שמנה עשרה, ונולדו בו סימני סריס\u0004 המפורשים להלן, \u0003ולאחר מכאן הביא שתי שערות. רב אמר: נעשה סריס למפרע,\u0004 כלומר, שערות אלה אינן נחשבות סימן בגרות מהרגע שבאו, אלא אנו דנים אותו כסריס מתחילתו, ולכן קובעים שהגיע לבגרותו בגיל שלוש עשרה, כשאר האנשים, ומתחייב על מה שעבר בינתיים. \u0003ושמואל אמר:\u0004 לא, ודאי \u0003קטן היה באותה שעה,\u0004 ושתי שערות שהביא הן סימן בגרותו, אלא שנתאחרה בגרותו.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף:\u0004 אם כן, \u0003ל\u0004שיטת \u0003רב,\u0004 ה\u0003אילונית לר' מאיר יהא לה קנס,\u0004 שלשיטת ר' מאיר רק נערה שנאנסה משלמים לה קנס ולא קטנה, ואיילונית שנאנסה אין לה קנס, משום שהיא נחשבת קטנה שהרי לא הביאה סימני בגרות, והרי לדעת רב היא נעשית בוגרת למפרע!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 יש לומר שהאיילונית \u0003מקטנותה יצתה לבגר.\u0004 כלומר, היא איננה עוברת שלב של נערות, אלא, בזמן שהיא קטנה — קטנה היא, ומיד לאחר מכן הופכת היא להיות בוגרת, ואין בה שלב ביניים של נערה, ולבוגרת אין קנס.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף שקיבל את דבריו, ונהנה מהם: יפה אמרת, \u0003כל כי הני מילי מעלייתא יתאמרו משמאי\u0004 \u0005[דברים מעולים כאלה\u0006 הייתי רוצה ש\u0005ייאמרו בשמי].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אין הסריס נידון כבן סורר ומורה — לפי שאין בן סורר ומורה נידון אלא ב\u0004זמן \u0003חתימת זקן התחתון\u0004 (שער הערוה), כשהגיע לבגרות אבל עדיין אינו איש גמור (והוא מקביל לנערה בנשים), והסריס אין לו סימנים אלה, ואין בו שלב ביניים בין קטנות לבגרות גמורה. \u0003ואין אילונית נידונית כנערה המאורסה — שמקטנותה יצתה לבגר,\u0004 הרי ברייתא מפורשת כדבריך.","\u0003אמר ר' אבהו: סימני סריס, ו\u0004כן סימני \u0003אילונית, ו\u0004סימני ילד \u0003בן שמנה,\u0004 כלומר, ילד שנולד לשמונה חודשים של הריון, שאין יודעים אם יחיה או לא יחיה — \u0003אין עושין בהן מעשה\u0004 להחשיב את הסריס והאיילונית כמבוגרים, ולהחשיב ילד בן שמונה כבן קיימא — \u0003עד שיהו בן עשרים.\u0004","שואלים: \u0003ובן שמנה מי קחיי\u0004 \u0005[האם הוא חי]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 ילד שנולד \u0003בן שמנה — הרי הוא כאבן\u0004 לענין דין מוקצה, ולכן \u0003אסור לטלטלו\u0004 בשבת, שאנחנו מניחים שאין בו חיוניות כלל, \u0003אבל אמו שוחה\u0004 (מתכופפת) \u0003עליו ומניקתו\u0004"],["\u0003מפני הסכנה\u0004 הן משום הסכנה של הילד (שמא יחיה לבסוף), והן לגבי החלב שיש לה, שאם אינו יוצא גורם לה כאבים העשויים להביאה למיתה. ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כשגמרו סימניו\u0004 ונראה שהוא וולד מושלם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003איזהו\u0004 שנולד \u0003בן שמנה\u0004 חודשים להריון? \u0003כל שלא כלו לו חדשיו,\u0004 שנולד לפני הזמן הראוי. \u0003רבי אומר: סימנין מוכיחין עליו? שערו וצפרניו שלא גמרו.\u0004 ומעתה, \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003לא גמרו\u0004 שערו וציפורניו, \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003גמרו, אמרינן\u0004 \u0005[אומרים אנו]\u0006 \u0003האי בר\u0004 \u0005[זה בן]\u0006 \u0003שבעה\u0004 חודשים \u0003הוא, ואישתהויי\u0004 \u0005[ושהות]\u0006 \u0003הוא דאישתהי\u0004 \u0005[שהשתהה]\u0006 ברחם אמו, ולא נולד לשבעה, אבל כבר בסוף חודש שביעי היה ראוי ללידה.","ושואלים: \u0003אלא הא דעבד\u0004 \u0005[זה שעשה]\u0006 \u0003רבא תוספאה עובדא\u0004 \u0005[מעשה]\u0006 \u0003באשה שהלך בעלה למדינת הים ואישתהי\u0004 \u0005[והשתהה]\u0006 הוולד \u0003עד תריסר ירחי שתא\u0004 \u0005[שנים עשר חודשי שנה]\u0006 לאחר שנסע הבעל, \u0003ואכשריה\u0004 \u0005[והכשירו]\u0006 ואמר שיש לתלות את הוולד בבעל, ואיננו ממזר. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 עשה כן — \u0003כרבי,\u0004 ש\u0003אמר\u0004 שלא תמיד נולד הילד בזמנו אלא לפעמים \u0003משתהא\u0004 \u0005[משתהה]\u0006 הוא זמן מסויים. ואיך פסק כדעת רבי שהיא דעת יחיד!","ומשיבים: \u0003כיון דאיכא\u0004 \u0005[שישנו]\u0006 גם \u0003רבן שמעון בן גמליאל\u0004 ש\u0003אמר משתהי\u0004 \u0005[משתהה]\u0006 הוולד, אם כן \u0003כרבים עבד\u0004 \u0005[עשה]\u0006 רבא תוספאה, ואין דעת רבי דעת יחיד. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבן שמעון בן גמליאל אומר: כל ששהה שלשים יום באדם\u0004 ונשאר חי — \u0003אינו נפל.\u0004 משמע שגם אם לא כלו לו חודשיו אומרים שהוכח שאינו נפל, והטעם — שיכול להיות שהשתהה ונולד לאחר זמן.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו סריס חמה? כל שהוא בן עשרים, ולא הביא\u0004 עדיין \u0003שתי שערות. ואפילו הביא\u0004 שערות \u0003לאחר מכאן — הרי הוא כסריס לכל דבריו\u0004 (דיניו). \u0003ואלו הן סימניו: כל שאין לו זקן, ושערו לקוי,\u0004 שאין השיער דומה לשיער כל אדם, \u0003ובשרו מחליק\u0004 (שאיננו שעיר). \u0003רבן שמעון בן גמליאל אומר משום ר' יהודה בן יאיר: כל שאין מימיו\u0004 (מי רגליו) \u0003מעלין רתיחות.\u0004","\u0003ויש אומרים: כל המטיל מים ואין עושה כיפה\u0004 (כעין קשת). \u0003ויש אומרים: כל ששכבת זרעו דוחה,\u0004 שאיננה נקרשת כשכבת זרע של בריא. \u0003ויש אומרים: כל שאין מימי רגליו מחמיצין. אחרים אומרים: כל שרוחץ בימות הגשמים ואין בשרו מעלה הבל. ר' שמעון בן אלעזר אומר: כל שקולו לקוי, ואין ניכר\u0004 בו ההבדל \u0003בין איש לאשה.\u0004","\u0003ואיזו היא אילונית? כל שהיא בת עשרים ולא הביאה שתי שערות, ואפילו הביאה\u0004 שערות \u0003לאחר מכאן — הרי היא כאילונית לכל דבריה. ואלו הן סימניה: כל שאין לה דדים\u0004 (שדיים), \u0003ומתקשה בשעת תשמיש,\u0004 שהתשמיש קשה ומכאיב לה. \u0003רבן שמעון בן גמליאל אומר: כל שאין לה שיפולי מעים כנשים,\u0004 שאין לה בשר תפוח מעל איבר המין שלה. \u0003ר' שמעון בן אלעזר אומר: כל שקולה עבה, ואינה ניכרת בין אשה לאיש.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו חכמים ב\u0003סימני סריס\u0004 אלה. \u0003רב הונא אמר: עד שיהו כולם,\u0004 שרק זה שמצויים בו כל הסימנים שנמנו — הוא הקרוי סריס. \u0003ר' יוחנן אמר: אפילו באחד מהן.\u0004 ומעירים: \u0003היכא\u0004 \u0005[היכן,\u0006 כאשר\u0005]\u0006 \u0003הביא שתי שערות בזקן — כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 ש\u0003עד שיהו\u0004 בו הסימנים \u0003כולן,\u0004 רק אז ייחשב כסריס למרות השערות. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו] —\u0006 \u0003בשלא הביא\u0004 שתי שערות.","ושואלים: \u0003אלא הא\u0004 \u0005[זה]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבה בר אבוה לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003עיינו ביה\u0004 \u0005[הסתכלו בו]\u0006 \u0003ברב נחמן\u0004 כשהולך לרחוץ, \u0003אי\u0004 \u0005[אם]\u0006 \u0003בשרו מעלה הבל איתיב ליה ברת\u0004 \u0005[אתן לו\u0006 את ה\u0005בת\u0006 שלי\u0005]\u0006 לאשה. \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]\u0006 אמר זאת, האם לא \u0003כרב הונא\u0004 שצריכים להיות בו כל הסימנים, שהרי מן הסתם ראה שאין לו זקן! ומשיבים: \u0003לא, רב נחמן סיכי דיקנא הויא ליה\u0004 \u0005[היו לו זיפי זקן]\u0006 ורצה לדעת אם יש בו סימני סריס אחרים.","שנינו במשנה: \u0003הסריס לא חולץ ולא מייבם, וכן אילונית וכו'.\u0004 ומעירים: \u0003קתני\u0004 \u0005[שנה]\u0006 כאן \u0003סריס דומיא\u0004 \u0005[\u0006ב\u0005דומה]\u0006 ל\u0003אילונית\u0004 ונלמד עוד מכאן: \u0003מה אילונית\u0004 הוא דבר ש\u0003בידי שמים — אף סריס\u0004 הוא \u0003בידי שמים, וסתמא\u0004 \u0005[וסתמה]\u0006 של משנה זו הוא \u0003כ\u0004דעת \u0003ר' עקיבא,\u0004 ש\u0003אמר:\u0004 סריס \u0003בידי אדם — אין\u0004 \u0005[כן]\u0006 הוא נחשב ככל אדם וחולץ, ואילו סריס \u0003בידי שמים — לא\u0004 חולץ \u0003.\u0004","שנינו במשנה ש\u0003הסריס שחלץ ליבמתו לא פסלה,\u0004 ואם בעל אותה פסלה. ומדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003בעלה הוא\u0004 משום שזו היא בעילת זנות, שהרי אינו בר הולדה ונמצא שהיא נבעלת לאחי בעלה שלא במקום מצוה. \u0003הא\u0004 \u0005[הרי]\u0006 אם היה בא עליה אדם \u0003אחר — לא\u0004 היתה נפסלת,"],["\u0003לימא תיהוי תיובתא\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005תהא\u0006 זו \u0005קושיה חמורה]\u0006 על \u0003רב המנונא,\u0004 ש\u0003אמר: שומרת יבם שזינתה — פסולה ליבמה,\u0004 שדינה כאשת איש שזנתה! ודוחים: \u0003לא,\u0004 מכאן אין קושיה. אפשר לומר כי \u0003הוא הדין אפילו\u0004 שנבעלה \u0003לאחר, נמי\u0004 \u0005[גם כן]\u0006 פסולה, \u0003ואיידי דתנא רישא בדידיה\u0004 \u0005[ומתוך ששנה תחילה בו]\u0006 בסריס שחלץ, \u0003תנא נמי סיפא בדידיה\u0004 \u0005[שנה גם כן\u0006 ב\u0005סוף בו]\u0006 בסריס שחלץ, אבל בענין זה הוא הדין גם כשנבעלה לאחרים.","שנינו: \u0003וכן איילונית שחלצו לה אחין\u0004 — לא פסלוה, בעלוה — פסלוה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 ש\u0003בעלוה, הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003לא בעלוה — לא,\u0004 אינה פסולה. \u0003כמאן\u0004 \u0005[כמי] —\u0006 ש\u0003לא כ\u0004שיטת \u0003ר' יהודה, דאי\u0004 \u0005[שאם]\u0006 כשיטת \u0003ר' יהודה, האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003איילונית זונה היא,\u0004 ואסורה לכהן בכל מקרה.","\u0003סריס חמה כהן שנשא בת ישראל — מאכילה בתרומה. ר' יוסי ור' שמעון אומרים: אנדרוגינוס\u0004 (שיש לו איברי זכר ואיברי נקיבה) \u0003כהן שנשא בת ישראל — מאכילה בתרומה.\u0004","\u0003ר' יהודה אומר: טומטום\u0004 (שאין ניכרים בו אברי המין) \u0003שנקרע\u0004 מעטה העור שהיה על אברו \u0003ונמצא זכר — לא יחלוץ, מפני שהוא כסריס. אנדרוגינוס נושא\u0004 אשה \u0003אבל לא נישא\u0004 לאיש מפני שהוא כזכר. \u0003ר' אליעזר אומר: אנדרוגינוס חייבין עליו סקילה כזכר\u0004 אם בא אדם אחר עליו.","על האמור במשנה לגבי כהן סריס שנישא לבת ישראל שהוא מאכילה בתרומה, שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 ולמה לא יאכילנה? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי כיון שנאמר \"ויליד ביתו הם יאכלו בלחמו\" (ויקרא כב, יא), יש לומר שהדבר תלוי בזה שהוא בר הולדה, שמי ש\u0003מוליד — מאכיל\u0004 גם את אשתו, ומי \u0003שאינו מוליד — אינו מאכיל,\u0004 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין הדבר תלוי בכך.","שנינו במשנה ש\u0003ר' יוסי ור' שמעון אומרים: אנדרוגינוס\u0004 מאכיל בתרומה. \u0003אמר ריש לקיש: מאכילה,\u0004 את אשתו, \u0003בתרומה, ואין מאכילה בחזה ושוק\u0004 של שלמים. \u0003ר' יוחנן אומר: אף מאכילה בחזה ושוק.\u0004 ושואלים: \u0003ולריש לקיש מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003חזה ושוק,\u0004 אם תאמר מפני שהם \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 הלא \u0003תרומה נמי דאורייתא\u0004 \u0005[גם כן מן התורה]\u0006 היא, ומדוע מתיר בה?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003בתרומה בזמן הזה,\u0004 שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 בלבד. ושואלים: \u0003אבל בזמן שבית המקדש קיים מאי\u0004 \u0005[מה]\u0006 יהיה הדין — \u0003לא,\u0004 שאינו מאכיל אפילו בתרומה. ואם כן קשה: \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 \u0003אין מאכילה בחזה ושוק, ליפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה\u0006 בתרומה \u0005עצמה]\u0006 וכך יאמר: \u0003במה דברים אמורים — בתרומה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 \u0003אבל בתרומה דאורייתא\u0004 \u0005[שמן התורה] —\u0006 \u0003לא!\u0004","ומשיבים: \u0003הכי נמי קאמר\u0004 \u0005[כך גם כן אמר],\u0006 כלומר, אכן, זו היתה כוונת הדברים, וכך יש להבין: \u0003כשהוא מאכילה — מאכילה בתרומה בזמן הזה\u0004 שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ואין מאכילה בזמן\u0004 שהיו \u0003חזה ושוק\u0004 ניתנים לכהנים, כלומר, בזמן שהיה המקדש קיים, \u0003ואפילו בתרומה דרבנן\u0004 \u0005[שמדברי סופרים],\u0006 וזאת מתוך החשש \u0003דלמא אתי\u0004 \u0005[שמא יבוא]\u0006 \u0003לאוכלה\u0004 (להאכילה) \u0003בתרומה דאורייתא.\u0004","\u0003ור' יוחנן אמר: אף מאכילה בחזה ושוק.\u0004 לגוף המחלוקת \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן לריש לקיש: מי סברת\u0004 \u0005[האם סבור אתה]\u0006 כי \u0003תרומה בזמן הזה דרבנן\u0004 \u0005[מדברי סופרים]\u0006 היא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 וראיה לדבר, \u0003שאני שונה: עיגול בעגולים עולה,\u0004 שאם עיגול דבילה (תאנים מיובשות וכבושות) של תרומה נתערב במאה עיגולים אחרים, ואין אנו יודעים איזה הוא — הרי הוא מתבטל בעיגולים האחרים ואין צריך לנהוג בהם כבתרומה. ומאחר שאפילו עיגול, שהוא דבר חשוב לעצמו, בטל — הרי זה בודאי מפני שעיקר תרומה שבו היא רק מדברי סופרים, ולא מדברי תורה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003והלא אני שונה: חתיכה בחתיכות עולה,\u0004 שאפילו חתיכה של חטאת שנתערבה בחתיכות בשר אחרות בטלה בהן, שלדעתו דין ביטול חל אפילו בדברים האסורים מן התורה. \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 \u0003\"כל שדרכו לימנות\" שנינו,\u0004 כלומר, כל דבר שיש לו חשיבות לעצמו, עד שהוא נמנה לעיתים כיחידה לעצמו ומוכרים אותו לבדו — חשוב הוא, ואינו בטל? לא כך, אלא \u0003\"את שדרכו לימנות\" שנינו,\u0004 רק דבר שהוא מיוחד בחשיבותו, שמונים אותו תמיד לעצמו, ואינו נמכר באומד בלבד, ועיגול תאנים לא תמיד נמנה לעצמו.","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 ההלכה שר' יוחנן רומז לה — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מי שהיו לו חבילי תלתן\u0004 שהיו \u0003של כלאי הכרם — ידלקו\u0004 (יישרפו באש), שכלאי הכרם אסורים בהנאה. \u0003נתערבו\u0004 חבילות אלה \u0003באחרות\u0004"],["\u0003כולן ידלקו,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: יעלו\u0004 (יתבטלו) \u0003באחד ומאתים. שהיה ר' מאיר אומר: כל שדרכו לימנות,\u0004 שהוא דבר חשוב לעצמו, שאינו נמכר במשקל או בכמויות גדולות, אלא כל פרט ממנו נמנה — \u0003מקדש,\u0004 ופוסל את הכל, ואינו בטל. \u0003וחכמים אומרים: אינו מקדש\u0004 בשל אי־התבטלותם, \u0003אלא ששה דברים בלבד. ר' עקיבא אומר: שבעה.\u0004","\u0003אלו הן\u0004 הדברים שאינם בטלים, מפני שהם חשובים כשלעצמם: \u0003אגוזי פרך, ורמוני\u0004 המקום \u0003בדן, וחביות סתומות\u0004 של יין, \u0003וחלפי תרדין\u0004 מיני תרד מיוחדים, \u0003וקולחי\u0004 (גבעולי) \u0003כרוב, ודלעת יונית. ור' עקיבא מוסיף\u0004 כשביעי \u0003אף ככרות של בעל הבית.\u0004 אלו מהן \u0003הראוין לערלה,\u0004 שאיסור ערלה חל עליהם, מדובר בהם לענין \u0003ערלה,\u0004 כגון אגוזים ורימונים. הראויים \u0003ל\u0004היאסר באיסור \u0003כלאי הכרם\u0004 כגון תרדין, כרוב ודלעת — משום \u0003כלאי הכרם,\u0004 שאיסורים אלה הם איסורי הנאה, אבל בטלים ברוב, חוץ מדברים אלה שהם חשובים.","\u0003ר' יוחנן סבר\u0004 וגרס בדברי ר' מאיר: \u0003\"את שדרכו לימנות\" שנינו\u0004 שרק אותם דברים הנמכרים תמיד אחד אחד מפני חשיבותם אינם בטלים. \u0003וריש לקיש סבר: \"כל שדרכו לימנות\" שנינו,\u0004 ובכלל זה גם שאר דברים שיש להם חשיבות.","ועוד מסבירים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003חתיכה\u0004 שרמז לה ר' יוחנן — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חתיכה של חטאת טמאה שנתערבה במאה חתיכות של חטאות טהורות, וכן פרוסה של לחם הפנים טמאה שנתערבה במאה פרוסות של לחם הפנים טהורות — תעלה\u0004 (תתבטל). \u0003ר' יהודה אומר: לא תעלה.\u0004","\u0003אבל חתיכה של חטאת טהורה שנתערבה במאה חתיכות של חולין טהורות, וכן פרוסה של לחם הפנים\u0004 שהיתה \u0003טהורה שנתערבה במאה פרוסות של חולין טהורות — דברי הכל לא תעלה.\u0004","ושואלים: \u0003קתני מיהת רישא\u0004 \u0005[\u0006הלא \u0005שנינו על כל פנים\u0006 ב\u0005תחלה]\u0006 שחתיכה של חטאת טמאה \u0003תעלה\u0004 (תתבטל), ואם כן קשה לריש לקיש, שהרי חתיכת חטאת היא דבר שדרכו להימנות, שפעמים נחשבת לעצמה, ואיסורה מן התורה, ובכל זאת בטילה! \u0003אמר ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב הונא:\u0004 מדובר כשחתיכה זו כבר לא היתה שלימה, אלא \u0003בנימוחה\u0004 ונתפרקה לחלקים קטנים, שכיון שאיננה עוד חתיכה שלימה — בטלה חשיבותה ממנה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר בנימוחה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יהודה\u0004 שאומר שלא תתבטל?"],["\u0003ר' יהודה\u0004 הולך בענין זה \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 כלל: \u0003מין במינו — לא בטיל\u0004 בכל אופן.","וממשיכים להקשות: \u0003אבל לא נימוח מאי\u0004 \u0005[מה]\u0006 יהיה הדין — \u0003לא תעלה,\u0004 אם כן \u0003אדתני\u0004 \u0005[עד ש\u0006הוא \u0005שונה]\u0006 בסוף המשנה מקרה אחר: \u0003אבל חתיכה של חטאת טהורה שנתערבה במאה חתיכות של חולין טהורות לא תעלה — ניפלוג וניתני בדידה\u0004 \u0005[שיחלק וישנה בה עצמה]\u0006 חלוקה זו: \u0003במה דברים אמורים בשנימוחה, אבל לא נימוחה — לא תעלה!\u0004","ומשיבים: אף על פי כן \u0003טהורות בטהורות עדיף ליה\u0004 \u0005[לו]\u0006 לומר, ולגלות לנו דין חדש, ואף שהיה יכול לחלק בדינה של חתיכה טמאה עצמה.","ושואלים: \u0003ולריש לקיש\u0004 שמעמיד בחתיכה שנימוחה, אם כן \u0003מאי שנא רישא ומאי שנא סיפא\u0004 \u0005[\u0006ב\u0005מה שונה\u0006 ב\u0005ראש ו\u0006ב\u0005מה שונה\u0006 ב\u0005סוף],\u0006 מדוע יש ביטול בטמאה ולא בטהורה? \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: רישא\u0004 \u0005[\u0006ב\u0005ראש]\u0006 מדובר שנטמאה החתיכה \u0003בטומאת משקין\u0004 שהיא רק טומאה \u0003דרבנן\u0004 \u0005[\u0006ש\u0005מדברי סופרים],\u0006 שכיון שנטמא הקודש רק בטומאה מדברי סופרים, אין לאבד בשל כך קדשים ביודעין, ולכן היא מתבטלת. ואילו \u0003סיפא\u0004 \u0005[\u0006ב\u0005סוף]\u0006 שמדובר בקודש שנתערב בחולין, כיון שהוא איסור \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 שאסור לזר לאכול קודש, לכן אין החתיכה מתבטלת.","ושואלים: אם כן, שמפרשים שבחלק הראשון מדובר בטומאת משקין בלבד, \u0003אבל\u0004 אם נטמא הקודש \u0003בטומאת שרץ\u0004 שהיא טומאה מן התורה \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין — \u0003לא תעלה\u0004 (תתבטל) חתיכת הקודש אף לשיטת ריש לקיש, ואם כן,","\u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סוף]:\u0006 \u0003אבל חתיכה של חטאת טהורה שנתערבה במאה חתיכות של חולין טהורות לא תעלה, ניפלוג וליתני בדידה\u0004 \u0005[שיחלק וישנה בה עצמה]:\u0006 \u0003במה דברים אמורים בטומאת משקין, אבל בטומאת שרץ — לא!\u0004 ומשיבים: אף על פי כן, \u0003טהורה בטהורות עדיף ליה\u0004 \u0005[לו]\u0006 לחדש בה.","\u0003רבה אמר\u0004 טעם אחר להבדל בין ראשית המשנה לסופה: \u0003רישא\u0004 \u0005[\u0006ב\u0005ראשה]\u0006 מדובר כאשר בגלל התערובת של אכילת קדשים טמאים החשש הוא רק של \u0003איסור לאו,\u0004 וב\u0003סיפא\u0004 \u0005[\u0006וב\u0005סוף]\u0006 החשש חמור יותר — חשש \u0003איסור כרת\u0004 על אכילת קדשים טהורים על ידי זר.","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רבה\u0004 עצמו \u0003הוא\u0004 ש\u0003אמר\u0004 כי \u0003כל\u0004 דבר שהוא אסור \u0003דאורייתא\u0004 \u0005[\u0006מדברי \u0005תורה]\u0006 שנתערב בהיתר, \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם הוא \u0003איסור לאו ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם הוא \u0003איסור כרת,\u0004 אין הבדל ביניהם לגבי ביטול! ומסכמים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 על דברי רבה.","\u0003רב אשי אמר\u0004 תירוץ אחר: \u0003סיפא\u0004 \u0005[הסוף]\u0006 שמדובר בה על קודש טהור שנתערב בדבר טהור אינו בטל — זהו \u0003משום דהוי ליה\u0004 \u0005[שהריהו]\u0006 \u0003דבר שיש לו מתירין,\u0004 שיש דרך להתירו. שהרי חתיכה זו אינה אסורה לכול, והיא מותרת באכילה לכהן, \u0003ו\u0004כלל הוא: \u0003כל דבר שיש לו מתירין אפילו באלף לא בטיל\u0004 \u0005[אינו בטל].\u0006","ומעירים: \u0003והא\u0004 \u0005[ו\u0006מימרה \u0005זו]\u0006 של \u0003רב אשי בדותא\u0004 \u0005[בדויה]\u0006 \u0003היא,\u0004 אינה נכונה. כי על מימרא זו, בהקשר לדברים כאן, יש לשאול: \u0003למאן\u0004 \u0005[למי]\u0006 יש לה מתירים? \u0003אי\u0004 \u0005[אם]\u0006 \u0003לכהן — מישרא שרי\u0004 \u0005[מותר]\u0006 הדבר לגמרי גם לפני התערובת, שהרי מותר לכהן לאכול גם קודש וגם חולין ולגביו אין כאן צד של תערובת איסור כלל. \u0003אי\u0004 \u0005[אם]\u0006 \u0003לישראל — לעולם אסור,\u0004 ואין לה מתירים! \u0003אלא הא\u0004 \u0005[זו]\u0006 שאמר \u0003רב אשי\u0004 ודאי \u0003בדותא\u0004 \u0005[בדויה]\u0006 \u0003היא,\u0004 אינה נכונה.","ולעצם שיטת ר' יוחנן שואלים: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יוחנן\u0004 כי \u0003תרומה בזמן הזה דאורייתא\u0004 \u0005[מן התורה]\u0006 היא? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003שתי קופות\u0004 (סלים גדולים) מלאות תבואה, \u0003אחת של חולין ואחת של תרומה, ולפניהם שתי סאין,\u0004 כלים בני סאה, \u0003אחת של חולין ואחת של תרומה, ונפלו אלו בתוך אלו,\u0004 ואין אנחנו יודעים מה נפל לתוך מה, ויש לחשוש שמא התרומה נפלה לקופת החולין, ולהיפך — \u0003הרי אלו\u0004 שהיו בהן חולין \u0003מותרים\u0004 באכילה לזרים, \u0003שאני אומר\u0004 ומניח ש\u0003תרומה לתוך תרומה נפלה, וחולין בתוך חולין נפלו.\u0004","\u0003ואמר ריש לקיש: והוא שרבו חולין על התרומה,\u0004 כלומר, שגם אם נפלה התרומה לתוך החולין, קופת החולין גדולה דיה, כך שמכל מקום בטילה התרומה ברוב. \u0003ור' יוחנן אמר: אף על פי שלא רבו חולין על התרומה\u0004 — מותרים, ואפשר לסמוך על ההנחה שכל מין נפל לתוך מינו.","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003לריש לקיש\u0004 אפשר להבין את שיטתו, כי \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 שאפילו \u0003ב\u0004תרומה האסורה באיסור \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003נמי רבויא הוא דבעינן\u0004 \u0005[גם כן ריבוי הוא שאנו צריכים]\u0006 כדי שיהיה ביטול ברוב. \u0003אלא לר' יוחנן קשיא\u0004 \u0005[קשה],\u0006 שאם הוא סבור שתרומה אף בזמן הזה היא מן התורה, כיצד אנו מתירים על ידי הנחה זו של \"שאני אומר\" ואין חוששים לאיסור?","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 לענין סאה שנפלה בקופה כשיטת \u0005מי\u0006 היא\u0005] —\u0006 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא\u0004 בענין תרומה בזמן הזה,"],["\u0003ואנא דאמרי\u0004 \u0005[ואני שאמרתי]\u0006 את פירוש משנתנו, פירשתיה \u0003כ\u0004דעת \u0003ר' יוסי,\u0004 שאף תרומה בזמן הזה מן התורה היא, ולשיטתו אין הבדל בין תרומה לחזה ושוק.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 \u0003ב\u0004ספר \u0003\"סדר עולם\"\u0004 על הכתוב המדבר בחזרת ישראל לארץ אחר הגלות: \u0003\"\u0004והביאך ה' אלהיך אל הארץ \u0003אשר ירשו אבתיך וירשתה\"\u0004 (דברים ל, ה), ששתי לשונות ירושה אלה באו ללמד: \u0003ירושה ראשונה\u0004 בזמן יהושע, \u0003ושניה\u0004 בזמן עולי בבל — \u0003יש להן\u0004 לישראל. שכשגלו לבבל בטלה קדושת הארץ, וכשחזרו בימי בית שני וירשוה — חזרה ונתקדשה. \u0003ושלישית — אין להן\u0004 ואינם צריכים לירושה נוספת כדי לקדשה, שכן מאותו זמן נתקדשה ארץ ישראל לעולם, ולא בטלה קדושתה.","\u0003ואמר ר' יוחנן: מאן תנא\u0004 \u0005[מי שנה]\u0006 את \u0003\"סדר עולם\" — ר' יוסי.\u0004 וכיון שר' יוחנן מסביר לפי שיטת ר' יוסי הרי לדעתו לא בטלה קדושת ארץ ישראל, ותרומות ומעשרות שבה הן מן התורה מראשית ימי בית המקדש השני עד עולם.","ושואלים מצד אחר על שיטת ר' יוחנן: \u0003וסבר\u0004 \u0005[ו\u0006האם \u0005סבור]\u0006 \u0003ר' יוחנן\u0004 כי \u0003ב\u0004דבר שהוא אסור \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003לא בעינן רבויא\u0004 \u0005[צריכים אנו\u0006 ביטול ב\u0005רוב]\u0006 ואפילו כשאין רוב חולין — התרומה בטילה? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה שיש בו ארבעים סאה מכוונות\u0004 (מדוייקות), לא פחות ולא יותר, אם \u0003נתן\u0004 במקוה זה \u0003סאה\u0004 משקה שאינו מים, \u0003ונטל\u0004 אחר כך \u0003סאה\u0004 מן המקוה — \u0003כשר,\u0004 שאנו אומרים שהמשקים שהכניס למקוה בטלים בתוכו והם משלימים את ארבעים הסאה. \u0003ואמר ר' יהודה בר שילא אמר ר' אסי אמר ר' יוחנן:\u0004 דין זה קיים \u0003עד רובו\u0004 של המקוה.","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003נשתייר רובו,\u0004 שרוב המשקה שבמקוה הוא עדיין מים כשרים, כלומר, עד שיתן בו תשע עשרה סאין של משקים אחרים, ואותם המשקים בטלים במי המקוה הכשרים, אבל אם היה רוב משקים אחרים — לא. הרי שאף באיסור שמדברי חכמים יש צורך בביטול ברוב! ודוחים: \u0003לא,\u0004 הכוונה היא ש\u0003לא נשקול\u0004 \u0005[ניקח,\u0006 נוציא\u0005]\u0006 את \u0003רובו,\u0004 אבל מחצה על מחצה — כשר, ואין צריך רוב לבטלו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 הסבר אחר לשיטת ר' יוחנן: \u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 בקופות שאחת מהן תרומה, \u0003דאיכא למימר\u0004 \u0005[שיש\u0006 מקום \u0005לומר]\u0006 את הטעם \u0003\"שאני אומר\",\u0004 וכיון שיש אפשרות במקרה זה שהתרומה נפלה לתרומה, אפשר לסמוך על כך, ואין זקוקים לביטול ברוב בתרומה שמדברי סופרים.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003אנדרוגינוס נושא,\u0004 משמע שנושא אשה לכתחילה כיון שנחשב כזכר ודאי. ואם כן זהו כדברי ר' יוחנן, וקשה לריש לקיש שסבור שאין נישואיו אלא ספק! ומתקנים: \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"אם נשא\",\u0004 שלא נמלך, אלא עשה מעשה ונשא.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"נושא\" קתני\u0004 \u0005[שנינו]\u0006 ומשמעו שנושא לכתחילה! ודוחים: \u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אבל לא נישא\"?\u0004 שהוא ודאי לשון בדיעבד, שאם זכר גמור הוא, אין כל טעם לומר שאינו נישא לכתחילה, \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"נישא\" — דיעבד,\u0004 ולא לכתחילה, שאפילו בדיעבד אינו נישא, אם כן \u0003\"נושא\" נמי\u0004 \u0005[גם כן]\u0006 הוא \u0003דיעבד!\u0004","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003לא,\u0004 כי לשון \u0003\"נושא\" — לכתחלה משמע, \"אבל לא נישא\" — דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 ונשארה הקושיה על ריש לקיש במקומה.","ומקשים על פירוש זה: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנה\u0006 ב\u0005סוף]\u0006 \u0003ר' אליעזר אומר: אנדרוגינוס חייבין עליו סקילה כזכר, מכלל\u0004 הדברים אתה למד שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003ספוקי מספקא ליה\u0004 \u0005[מסופק לו]\u0006 אם האנדרוגינוס אכן נחשב כזכר גמור, ומכאן קשה לר' יוחנן!","ומשיבים: לא, \u0003בין למר\u0004 \u0005[לחכם זה]\u0006 \u0003בין למר\u0004 \u0005[לחכם זה]\u0006 \u0003מפשט פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 שאנדרוגינוס זכר הוא, אלא \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל בפרטים לגבי \u0003סקילה משני מקומות.\u0004 אם בא עליו גבר אחר, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא \u0005סבור]\u0006 כי \u0003חייבין עליו סקילה משני מקומות,\u0004 שגם אם בא עליו באבר הנקבות שלו, מכל מקום כיון שהוא כזכר — חייב עליו סקילה. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אליעזר \u0005סבור]\u0006 שרק כשבא עליו \u0003כ\u0004דרך שבא על \u0003זכר\u0004 אחר, חייב סקילה, ולא כשבא במקום נקבות.","\u0003אמר רב:\u0004"],["\u0003ליתא למתניתין מקמי\u0004 \u0005[אין ל\u0006קבל את \u0005משנתנו מפני]\u0006 ה\u0003ברייתא\u0004 שבה שנויה שיטה אחרת, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]:\u0006 \u0003ר' יוסי אומר: אנדרוגינוס בריה בפני עצמה הוא, ולא הכריעו בו חכמים אם זכר אם נקבה.\u0004 ולכן איננו יכול לשאת אשה, ואם קידש אשה — אינו מאכיל אותה בתרומה.","ושואלים: \u0003אדרבה\u0004 (להיפך) \u0003ליתא\u0004 \u0005[אין\u0006 מקום\u0005]\u0006 \u0003לברייתא מקמי מתניתין\u0004 \u0005[מפני משנתנו],\u0006 שהרי מסתבר לומר שהברייתא היא פחות מוסמכת מהמשנה! ומשיבים: \u0003מדשבקיה\u0004 \u0005[מ\u0006כיון \u0005שעזבו]\u0006 \u0003ר' יוסי לבר זוגיה\u0004 \u0005[את בן זוגו]\u0006 את ר' שמעון, שבמשנה נאמרים הדברים בשם ר' יוסי ור' שמעון יחד, ובברייתא — בשם ר' יוסי לבד, \u0003שמע מינה הדר ביה\u0004 \u0005[למד מכאן\u0006 ש\u0005חזר בו]\u0006 ר' יוסי מן השיטה שהחזיק בה עם ר' שמעון והגיע למסקנה אחרת.","\u0003ושמואל אמר\u0004 להיפך: \u0003ליתא\u0004 \u0005[אין\u0006 מקום\u0005]\u0006 \u0003לברייתא מקמי מתניתין\u0004 \u0005[מפני משנתנו].\u0006 ומקשים: \u0003אדרבה\u0004 (להיפך), \u0003ליתא למתניתין מקמי\u0004 \u0005[אין\u0006 מקום \u0005למשנתנו מפני]\u0006 ה\u0003ברייתא,\u0004 ויתר מכן: \u0003דהא שמעינן ליה\u0004 \u0005[שהרי שמענו אותו]\u0006 את \u0003שמואל דחייש ליחידאה\u0004 \u0005[ש\u0006הוא \u0005חושש\u0006 גם \u0005ל\u0006דעת \u0005יחיד]\u0006 הנאמרת בברייתא! ומשיבים: \u0003הני מילי כי לא מתעקרא מתניתין\u0004 \u0005[דברים אלה\u0006 אמורים \u0005כאשר אין משנתנו\u0006 עצמה \u0005נעקרת],\u0006 אלא יש דעה אחרת, שהיא נוספת על המשנה, \u0003אבל כי מתעקרא מתניתין לא חייש\u0004 \u0005[כאשר נעקרת משנתנו\u0006 ונאמר דבר בברייתא בניגוד לה \u0005איננו חושש].\u0006","\u0003אמרי בי\u0004 \u0005[אמרו\u0006 החכמים ב\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: הלכה כר' יוסי,\u0004 הן \u0003ב\u0004דין \u0003אנדרוגינוס, ו\u0004הן \u0003ב\u0004דין \u0003הרכבה. ושמואל אמר:\u0004 הלכה כמותו \u0003בקושי, ובקידוש.\u0004","ומסבירים: \u0003אנדרוגינוס — הא דאמרן\u0004 \u0005[זו שאמרנו],\u0006 שהוא סבור שבריה בפני עצמה הוא (ר\"ח). \u0003הרכבה — דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003אין נוטעין ואין מבריכין\u0004 ענף בקרקע, \u0003ואין מרכיבין\u0004 אילנות זה בזה \u0003ערב\u0004 שנת ה\u0003שביעית\u0004 (השמיטה) \u0003פחות משלשים יום לפני ראש השנה,\u0004 שאסור שתהיה הקליטה בשנת השמיטה. \u0003ואם נטע, ו\u0004כן אם \u0003הבריך\u0004 או \u0003הרכיב — יעקור. ר' יהודה אומר: כל הרכבה שאינה קולטת בשלשה ימים — שוב אינה קולטת,\u0004 ואסור איפוא לנטוע לשיטה זו רק שלושה ימים לפני ראש השנה. \u0003ר' יוסי ור' שמעון אומרים:\u0004 זמן הקליטה הוא \u0003שתי שבתות\u0004 (שני שבועות).","\u0003ואמר רב נחמן אמר רבה בר אבוה: לדברי האומר שלשים\u0004 — כוונתו ש\u0003צריך שלשים\u0004 יום לקליטה \u0003ושלשים\u0004 יום לתוספת \"ערב שביעית\", שמוסיפים מחול על הקודש, ואסור איפוא לנטוע שישים יום קודם ראש השנה. \u0003לדברי האומר שלשה — צריך\u0004 לחשבון זה לנטוע לפחות \u0003שלשה ושלשים\u0004 יום לפני שמיטה, \u0003לדברי האומר שתי שבתות — צריך שתי שבתות ושלשים\u0004 יום. ומכל מקום פסק רב כר' יוסי.","\u0003ושמואל אמר:\u0004 הלכה כמותו גם \u0003בקושי ו\u0004גם ב\u0003קידוש.\u0004 ומסבירים: \u0003קושי\u0004 מהו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 שיש דין מיוחד לגבי אשה המקשה ללדת וזב ממנה דם, שגם אם ראתה דם כמה ימים רצופים, אין אומרים שהדם הזה ייחשב כדם זיבה (שכל אשה הרואה דם שלושה ימים שלא בעת הוסת נחשבת לזבה), אלא דינו כדם לידה.","אלא שדנו בשאלה: \u0003כמה יהא קישויה,\u0004 כלומר, כמה זמן לפני הלידה אנחנו רואים זאת כקישוי מחמת לידה — \u0003ר' מאיר אומר: או ארבעים או חמשים יום\u0004 קודם הלידה. \u0003ר' יהודה אומר: דייה חדשה,\u0004 כלומר, מראשית אותו חודש שבו ילדה מספיק לחשבון זה. \u0003ר' יוסי ור' שמעון אומרים: אין קישוי\u0004 לידה \u0003יותר משתי שבתות\u0004 (שבועות). ופסק שמואל כר' יוסי גם בזה.","\u0003קידוש\u0004 מהו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המסכך גפנו על גבי תבואתו של חברו — הרי זה קדש,\u0004 כלומר, נאסר הכל משום כלאי הכרם, \u0003וחייב באחריותו,\u0004 שהעושה זאת צריך לשלם עבור הנזקים, שהרי גם התבואה של חבירו נאסרת בהנאה, אלו \u0003דברי ר' מאיר. ר' יוסי ור' שמעון אומרים:\u0004"],["\u0003אין אדם אוסר דבר שאינו שלו,\u0004 וכיון שאין התבואה שלו, אינו יכול לאסור אותה. ולדברי שמואל, הלכה כר' יוסי גם בזה.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003באנדרוגינוס מה לי אמר שמואל,\u0004 כלומר, מה דעתו של שמואל? שהרי בשם רב פסקו הלכה באנדרוגינוס כר' יוסי, ושמואל לא פירש מה דעתו בענין זה. ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ש\u0003אמר שמואל לרב ענן: ליתא\u0004 \u0005[אין\u0006 מקום\u0005]\u0006 \u0003לברייתא מקמי מתניתין\u0004 \u0005[מפני משנתנו],\u0006 משמע ששמואל אינו מקבל את דעת ר' יוסי בברייתא שאנדרוגינוס הוא בריה בפני עצמה.","ושואלים: ב\u0003הרכבה מה לי אמר שמואל,\u0004 מה דעת שמואל? ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב ענן: תני\u0004 \u0005[שנה]\u0006 \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]\u0006 \u0003שלשה ושלשים,\u0004 הרי שפסק בענין זה לא כר' יוסי אלא כר' יהודה.","ועוד שואלים: בענין \u0003קושי מה לי אמר רב,\u0004 מה היא דעת רב, האם פסק כר' יוסי? לשאלה זו לא נמצאה תשובה, ומסכמים: \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","ועוד שאלה נשאלה: ב\u0003קידוש\u0004 תבואה בכלאי הכרם \u0003מה לי אמר רב? אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ש\u0003אמר רב הונא אמר רב: אין הלכה כר' יוסי. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי חזית דסמכת אהא\u0004 \u0005[מה ראית שאתה סומך על זה]?\u0006 \u0003סמוך אהא\u0004 \u0005[על זה]!\u0006 שיש מקור אחר — ש\u0003אמר רב אדא אמר רב: הלכה כר' יוסי.\u0004 ואם כן יש גם מסורת שפסק הלכה כר' יוסי! ומשיבים: כשאמרו \u0003\"אמרי בי\u0004 \u0005[אמרו\u0006 חכמי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב\"\u0004 — \u0003מנו\u0004 \u0005[מי הוא],\u0006 למי התכוונו? — הרי זה כינוי ל\u0003רב הונא, ו\u0004הלא \u0003רב הונא אמר: אין הלכה\u0004 כר' יוסי. ולכן שמועה זו שמסרה רב אדא בשם רב איננה מדוייקת, ויש לסמוך על דברי רב הונא תלמידו המובהק.","שנינו במשנה, \u0003ר' יהודה אומר: טומטום\u0004 שנקרע ונמצא זכר — אינו חולץ, מפני שהוא כסריס. \u0003אמר ר' אמי: מאי עביד ליה\u0004 \u0005[מה\u0006 היה \u0005עושה לו]\u0006 \u0003ר' יהודה לטומטום\u0004 שהיה בעיר \u0003בירי דאותבוה אבי כורסיה\u0004 \u0005[שהושיבו אותו על כסא]\u0006 לצורך ניתוח, \u0003ואיקרע\u0004 \u0005[ונקרע]\u0006 הקרום המכסה את אברו \u0003ו\u0004אחר כך \u0003אוליד שבע בנין\u0004 \u0005[הוליד שבעה בנים],\u0006 הרי שאנדרוגינוס שנקרע אינו בהכרח סריס\u0005!\u0006 \u0003ו\u0004משיבים: \u0003ר' יהודה אמר לך\u0004 \u0005[היה אומר לך]:\u0006 \u0003חזר\u0004 (חפש) \u0003על בניו מאין הם,\u0004 שאינו מאמין שבנים אלו הם שלו, אלא מאיש אחר הם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: טומטום לא יחלוץ, שמא יקרע ונמצא סריס חמה.\u0004 ושואלים: מדוע מנסח הוא את דבריו כך? \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003כל\u0004 טומטום \u0003דמקרע\u0004 \u0005[שנקרע]\u0006 \u0003זכר הוי\u0004 \u0005[הוא]?\u0006 הלא ייתכן שיימצא נקיבה! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש להבין את דבריו: \u0003שמא יקרע ונמצא נקבה\u0004 וודאי אינו יכול לחלוץ, \u0003ואפילו נמצא זכר — שמא ימצא סריס חמה.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 בין ר' יהודה ובין בנו ר' יוסי הלכה למעשה? \u0003אמר רבא:\u0004 לענין \u0003לפסול במקום אחין,\u0004 שאם היו עוד אחים למת מלבד הטומטום, והטומטום חלץ, הרי לדעת ר' יהודה, שודאי סריס הוא, אין חליצתו כלום, ואינו פוסל את האחים האחרים מלייבם. ולדעת ר' יוסי בר' יהודה ספק סריס הוא ופוסל. \u0003ו\u0004כן לענין \u0003לחלוץ שלא במקום אחין,\u0004 שאם אין אחים אחרים, האם צריך הטומטום לחלוץ, שלדעת ר' יהודה ודאי אינו צריך, ולדעת ר' יוסי בר' יהודה צריך מספק. אלה ההבדלים ש\u0003איכא בינייהו\u0004 \u0005[\u0006ש\u0005יש ביניהם].\u0006","\u0003אמר רב שמואל בר יהודה אמר ר' אבא אחוה\u0004 \u0005[אחיו]\u0006 של \u0003ר' יהודה בר זבדי אמר רב יהודה אמר רב: אנדרוגינוס חייבין עליו סקילה,\u0004 אם בא אחר עליו \u0003משתי מקומות;\u0004 הן כשבא עליו בפי הטבעת כדרך שבא על הזכר, והן שבא עליו באבר הנקבות שלו. \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו, \u0003ר' אליעזר אמר: אנדרוגינוס חייבין עליו סקילה כבזכר. במה דברים אמורים\u0004 — שבא עליו \u0003בזכרות שלו,\u0004 כלומר כדרך שבאים על הזכר, \u0003אבל\u0004 אם בא \u0003בנקבות שלו — פטור!\u0004","ומשיבים: \u0003הוא,\u0004 רב, ש\u0003אמר,\u0004 סבור, \u0003כי האי תנא\u0004 \u0005[כמו תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' סימאי אומר: אנדרוגינוס חייבין עליו סקילה משתי מקומות.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' סימאי? אמר רבא:\u0004 החכם \u0003בר המדורי אסברא\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את הדבר, ומצא לו רמז מן המקרא, שנאמר: \u0003\"ואת זכר לא תשכב משכבי אשה\"\u0004 (ויקרא יח, כב), \u0003אי זהו זכר שיש בו שני משכבות — הוי אומר זה אנדרוגינוס,\u0004 שמלשון רבים \"משכבי\", נראה שמחייב בפועל על שניהם.","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 החולקים על ר' סימאי מה הם אומרים? — \u0003אף על גב דאית ביה\u0004 \u0005[אף על פי שיש בו]\u0006 \u0003שני משכבות\u0004 — \u0003\"\u0004ו\u0003את זכר\" כתיב,\u0004 ולכן נסקלים עליו דווקא כששכיבתו היתה כזכר.","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 המפרשים כל פסוק זה לגבי אנדרוגינוס, ואינם למדים ממנו על שני משכבות, \u0003זכר גרידא\u0004 \u0005[בלבד]\u0006 \u0003מנא להו\u0004 \u0005[מניין להם]\u0006 שאסור לבוא עליו? ומשיבים: \u0003מ\"אשה\"\u0004 (שנאמר: \"משכבי אשה\"). ושואלים: \u0003באשה\u0004 אסורה, לחייב את הבא עליה ביאה \u0003שלא כדרכה, מנא להו\u0004 \u0005[מניין להם]?\u0006 ומשיבים: \u0003מ\u0004ריבוי ה־ו' של \u0003\"ו\u0004 את... \u0003אשה\".\u0004","\u0003אמר רב שזבי אמר רב חסדא: לא לכל אמר ר' אליעזר\u0004 ש\u0003אנדרוגינוס זכר מעליא\u0004 \u0005[מעולה,\u0006 גמור\u0005]\u0006 \u0003הוא, שאם אתה אומר כן\u0004 שאנדרוגינוס הוא זכר לכל דבר, אם כן \u0003במוקדשים,\u0004 כלומר, לענין קרבנות, אם הקדיש עוף אנדרוגינוס, \u0003יקדש\u0004 אם מקדישים אותו.","\u0003ומנלן דלא קדש\u0004 \u0005[ומניין לנו שאינו קדוש] —\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 עוף \u0003הנרבע\u0004 לאדם, \u0003והמוקצה\u0004 כדי להשתמש בו לצורך עבודה זרה, \u0003והנעבד,\u0004 שאותו עצמו עבדו כעבודה זרה, \u0003והאתנן\u0004 שנתנו לזונה, \u0003ו\u0004כן \u0003מחיר\u0004 כלב, שהחליף אותו תמורת כלב, \u0003ו\u0004כן \u0003טומטום ואנדרוגינוס\u0004 — כל אלה אם נהג בהם כבקרבנות ומלק (ולא שחט) אותם, \u0003מטמאין בגדים אבית\u0004 \u0005[בבית]\u0006 \u0003הבליעה,\u0004 שכיון שנכנס הבשר לבית הבליעה שבאדם — נטמא האדם, ומטמא גם את הבגדים שעליו. וזאת כיון שקרבן העוף נעשה, במקום בשחיטה — במליקה, ומליקה מכשירה לאכילה רק עוף שהוא קרבן, ואילו עוף אחר שנמלק נעשה נבילה, ונבלת עוף טהור מטמאה בבית הבליעה. וכל אלה לא חלה עליהם כלל קדושת קרבן, ולכן מליקתם עושה אותם נבילה, ומטמאים בבית הבליעה.","\u0003ר' אליעזר אומר: טומטום ואנדרוגינוס אין מטמאין בגדים אבית\u0004 \u0005[בבית]\u0006 \u0003הבליעה,\u0004 שכן חלה עליהם קדושת קרבן. \u0003שהיה ר' אליעזר אומר: כל מקום שנאמר\u0004 במפורש בתורה \u0003זכר ונקבה — אתה מוציא טומטום ואנדרוגינוס מביניהם,\u0004 שטומטום ואנדרוגינוס אינם נכללים ביניהם, משום שהם ספק, ודבר זה נכון לגבי בהמות, שכן נתפרש בתורה קרבן זכר ונקיבה, אבל \u0003עוף, הואיל ולא נאמר בו זכר ונקבה,\u0004 אלא נאמר סתם תורים ובני יונה, על כן \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מוציא טומטום ואנדרוגינוס מביניהם,\u0004 וכשרים הם. ולענייננו רואים מכאן כי ר' אליעזר סבור שלענין קרבנות אנדרוגינוס אינו נחשב כזכר גמור.","\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דבר זה במפורש בברייתא: ש\u0003ר' אליעזר אומר:\u0004"],["\u0003הכלאים, וטרפה, ויוצא דופן, טומטום ואנדרוגינוס — לא קדושין\u0004 כשמקדישים אותם לקרבן, \u0003ולא מקדשין\u0004 אחרים בתמורתם.","\u0003ואמר שמואל: לא קדושין — בתמורה,\u0004 שאם היתה לו בהמה שהוקדשה כקרבן ורצה להמירה בטומטום או באנדרוגינוס — אין חלה עליהם קדושה. \u0003ולא מקדשין — בעושה תמורה,\u0004 שאם היו אלה מוקדשים, אינם עושים תמורה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ראיה גמורה שר' אליעזר אינו סבור שאנדרוגינוס הוא כזכר לכל דבר.","על אותו קטע במשנתנו ש\u0003ר' אליעזר אומר\u0004 שאנדרוגינוס \u0003חייבין עליו סקילה כזכר, תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר רבי: כשהלכתי ללמוד תורה אצל ר' אלעזר בן שמוע, חברו עלי תלמידיו כתרנגולים של בית בוקיא\u0004 שהם תוקפנים מאד, ואינם מניחים לתרנגול אחר להיות ביניהם, \u0003ולא הניחוני ללמוד\u0004 שם, ולא הספקתי ללמוד \u0003אלא דבר אחד במשנתינו\u0004 — ש\u0003ר' אליעזר אומר: אנדרוגינוס חייבין עליו סקילה כזכר.\u0004 \u0003א משנה יש\u0004 נשים ש\u0003מותרות לבעליהן ואסורות ליבמיהן,\u0004 ולהיפך, יש \u0003מותרות ליבמיהן ואסורות לבעליהן.\u0004 ויש \u0003מותרות לאלו ולאלו, ו\u0004יש \u0003אסורות לאלו ולאלו.\u0004","","","ומפרטים: \u0003ואלו מותרות לבעליהן ואסורות ליבמיהן: כהן הדיוט שנשא את האלמנה, ויש לו אח כהן גדול\u0004 הרי אלמנה זו היתה מותרת לבעלה, ואסורה ליבמה שהוא כהן גדול. וכן \u0003חלל\u0004 (כגון בנם של כהן וגרושה) \u0003שנשא כשרה ויש לו אח\u0004 מאביו שהוא כהן \u0003כשר.\u0004","שאותה אשה היתה מותרת לחלל, אבל אסורה לאחיו הכהן, כיון שחילל אותה האח החלל בביאתו, או \u0003ישראל שנשא\u0004 את \u0003בת ישראל ויש לו אח\u0004 מאביו שהוא \u0003ממזר,\u0004 שאסור לממזר לבוא בקהל ואסור ביבמתו, או \u0003ממזר שנשא ממזרת, ויש לו אח\u0004 מאביו שהוא \u0003ישראל\u0004 כשר, שהנישואין הראשונים של הממזר היו כשרים, שהרי ממזר מותר בממזרת, אבל האשה הממזרת אסורה ליבם הכשר — כל אלו \u0003מותרות לבעליהן ואסורות ליבמיהן.\u0004","\u0003ואלו מותרות ליבמיהן ואסורות לבעליהן: כהן גדול שקידש את האלמנה\u0004 שאסור לו לשאתה (ודווקא כשקידשה בלבד, אבל אם בא עליה — עשאה חללה ואסורה לכל כהן), \u0003ויש לו אח כהן הדיוט\u0004 שמותר באלמנה, וכן כהן \u0003כשר שנשא חללה ויש לו אח חלל,\u0004 וכן \u0003ישראל שנשא ממזרת ויש לו אח ממזר,\u0004 וכן \u0003ממזר שנשא בת ישראל ויש לו אח ישראל\u0004 — הרי כל אלו \u0003מותרות ליבמיהן ואסורות לבעליהן.\u0004","\u0003ואלו אסורות לאלו ולאלו: כהן גדול שנשא את האלמנה ויש לו אח כהן גדול, או כהן הדיוט\u0004 שהוא כהן \u0003כשר שנשא חללה ויש לו אח\u0004 כהן \u0003כשר,\u0004 שהאשה אסורה לשניהם משום חללה, וכן \u0003ישראל שנשא ממזרת ויש לו אח ישראל\u0004 כשר, \u0003או ממזר שנשא בת ישראל ויש לו אח ממזר\u0004 — הרי הן \u0003אסורות לאלו ולאלו. ושאר כל הנשים מותרות לבעליהן וליבמיהן.\u0004","\u0003שניות\u0004 לעריות, שהן קרובות־משפחה האסורות רק \u0003מדברי סופרים,\u0004 אם היתה \u0003שנייה לבעל ולא שנייה ליבם\u0004 — הרי זו \u0003אסורה לבעל ומותרת ליבם. שנייה ליבם ולא שנייה לבעל — אסורה ליבם ומותרת לבעל. שנייה לזה ולזה — אסורה לזה ולזה.\u0004","ובכל מקרה שאדם נושא שנייה, קנסוה חכמים, ולכך \u0003אין לה לא כתובה\u0004 בשעת גירושיה, \u0003ולא\u0004 זכאית לקבל בחזרה תשלום מבעלה בעד \u0003פירות\u0004 של נכסיה שהשתמש בהם, \u0003ולא\u0004 זכאית ב\u0003מזונות\u0004 ממנו \u0003ולא\u0004 מקבלת בחזרה \u0003בלאות\u0004 של בגדים וחפצים שהביאה בשעת נישואין. \u0003ו\u0004מכל מקום, \u0003הולד\u0004 הנולד משנייה \u0003כשר, וכופין אותו\u0004 בבית דין \u0003להוציא\u0004 (לגרשה). ואילו \u0003אלמנה לכהן גדול,\u0004 וכן \u0003גרושה\u0004 או \u0003חלוצה לכהן הדיוט, ממזרת\u0004 או \u0003נתינה לישראל, בת ישראל לנתין\u0004 או \u0003לממזר\u0004 אף שנישואיהן בעבירה — \u0003יש להן כתובה.\u0004","","בקטע הראשון במשנה דובר בכהן הדיוט שנשא את האלמנה ונפלה לייבום לפני אחיו כהן גדול. ושואלים: \u0003מאי איריא דתני\u0004 \u0005[מה שייך,\u0006 מדוע דווקא, \u0005שנה]\u0006 \u0003\"נשא\"? ליתני\u0004 \u0005[שישנה]\u0006 רק \u0003\"קידש\"!\u0004 שבקידושין בלבד כבר זקוקה היא לייבום כשמת בעלה. \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003טעמא\u0004 \u0005[\u0006ש\u0005הטעם]\u0006 ששנה \u0003\"נשא\",\u0004 משום \u0003דהוה ליה\u0004 \u0005[שהרי הוא]\u0006 לגבי היבם הכהן הגדול \u0003עשה\u0004 (של בתולה) \u0003ולא תעשה\u0004 של אלמנה, ואין מצות עשה של ייבום דוחה עשה ולא תעשה, \u0003אבל\u0004 אם \u0003קידש\u0004 בלבד ועדיין בתולה היא, תאמר ש\u0003אתי\u0004 \u0005[\u0006ש\u0005באה\u0006 מצות\u0005]\u0006 \u0003עשה\u0004 של ייבום \u0003ודוחה\u0004 את \u0003לא תעשה,\u0004 ולא תיחשב כ\"אסורות ליבמיהן\" — אולם אי אפשר לפרש כך, \u0003והא כולה פירקין\u0004 \u0005[והרי כל פרקנו]\u0006 דוגמאות של \u0003עשה ולא תעשה הוא,\u0004 שיש עשה של ייבום נגד לא תעשה של איסור נישואין, \u0003ולא אתי\u0004 \u0005[בא]\u0006 \u0003עשה ודחי\u0004 \u0005[ודוחה]\u0006 את \u0003לא תעשה!\u0004 ואם כן, לא זה הטעם ששנה \"נשא\".","","ומשיבים: באמת, במקרה זה היה יכול לומר גם \"קידש\", אלא \u0003משום דקבעי למיתני סיפא\u0004 \u0005[שרצה לשנות\u0006 ב\u0005סוף]\u0006 \u0003כהן גדול שנשא את האלמנה\u0004 ויש לו אח כהן הדיוט, ושם מדובר \u0003דוקא\u0004 ב\u0003נשא, דשוייה\u0004 \u0005[שעשה אותה]\u0006 \u0003חללה\u0004 בביאתו, \u0003אבל\u0004 אם \u0003קידש\u0004 בלבד ולא נעשתה חללה — \u0003שריא ליה\u0004 \u0005[מותרת לו]\u0006 לאחיו, שהוא כהן הדיוט ומותר באלמנה, לכן \u0003תנא נמי רישא\u0004 \u0005[שנה גם כן\u0006 ב\u0005תחילה]\u0006 \u0003\"נשא\"!\u0004","ומקשים על תירוץ זה: \u0003ואדתני\u0004 \u0005[ועד ש\u0006הוא \u0005שונה]\u0006 לשון \"נשא\" \u0003משום סיפא\u0004 \u0005[סופה]\u0006 של המשנה, \u0003ליתני\u0004 \u0005[שישנה]\u0006 \"קידש\" \u0003משום מציעתא\u0004 \u0005[אמצעה],\u0006 שהרי המקרה האחר הוא \u0003כהן גדול שקידש את האלמנה ויש לו אח כהן הדיוט! אלא\u0004 לא מפני טעם זה אמר, ויש לומר כי \u0003משום בת בוקתא\u0004 \u0005[דירתה],\u0006 הגרה בצידה, כלומר, משום המקרה שנאמר בסמוך לקטע זה, \u0003דקבעי למיתני\u0004 \u0005[שרצה לשנות]\u0006 \u0003חלל שנשא כשרה, טעמא\u0004 \u0005[\u0006ו\u0005הטעם]\u0006 שם דווקא משום ש\u0003נשא, דשוייה\u0004 \u0005[שעשה אותה]\u0006 \u0003חללה\u0004 בביאתו, \u0003אבל\u0004 אם \u0003קידש\u0004 בלבד \u0003— שריא ליה\u0004 \u0005[מותרת\u0006 גם \u0005לו]\u0006 לאח היבם, ו\u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003קתני\u0004 \u0005[שנה]\u0006 \u0003\"נשא\".\u0004","ועוד שואלים על הלשון: נאמר בכהן הדיוט שנשא את האלמנה, \u0003ומאי איריא\u0004 \u0005[ומה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003דקתני\u0004 \u0005[ששנה]\u0006 כהן הדיוט שנשא \u0003אלמנה? ליתני\u0004 \u0005[שישנה]\u0006 שנשא \u0003בתולה,\u0004 שהרי היא נעשית אלמנה במותו, ומה ההבדל אם היתה אלמנה קודם לכן, או לא היתה?"],["\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003קסבר האי תנא\u0004 \u0005[סבור תנא זה]\u0006 ש\u0003נישואין הראשונים מפילין,\u0004 כלומר, לגבי חיוב הייבום, הזמן הקובע אינו זמן מותו של האח אלא זמן נישואיו, ואם נשא בתולה הלא היתה כשרה גם לכהן גדול — אולם אי אפשר לומר כן, ש\u0003הרי\u0004 שנינו: \u0003חלל שנשא כשרה\u0004 שאסורה להתייבם לאח הכשר, \u0003ולא אמרינן\u0004 \u0005[ואין אנו אומרים]\u0006 \u0003נישואין הראשונים מפילין\u0004 ומכיון שהיתה כשרה, הריהי כשרה עכשיו לאחיו. שאם כן — הלא בזמן שקידש אותה היתה כשרה וראויה גם לאחיו, ונתחללה רק אחר כך כשבא עליה!","ומשיבים: \u0003הא\u0004 \u0005[זה]\u0006 \u0003ודאי\u0004 נאמר בלשון זו \u0003משום סיפא\u0004 \u0005[סופה]\u0006 של המשנה, \u0003משום דקבעי למיתנא סיפא\u0004 \u0005[שרצה לשנות\u0006 את \u0005סופה]\u0006 של המשנה \u0003כהן גדול שנשא את האלמנה ויש לו אח כהן גדול או כהן הדיוט,\u0004 ושם \u0003דוקא אלמנה\u0004 מן הנישואין, שנעשתה חללה על ידי ביאת הכהן הגדול, \u0003אבל\u0004 אם היתה האשה \u0003בתולה\u0004 בנישואיה \u0003חזיא ליה\u0004 \u0005[ראויה\u0006 היתה \u0005לו]\u0006 לאח הכהן ההדיוט, שהרי היא אלמנה המותרת לכהן הדיוט, ו\u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003קתני\u0004 \u0005[כך שנה]\u0006 \u0003אלמנה\u0004 גם ברישא.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה,\u0006 על המשנה\u0005]\u0006 \u0003רב פפא: אם איתא להא\u0004 \u0005[יש\u0006 מקום \u0005ל\u0006הלכה \u0005זו]\u0006 \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר\u0004 בשם \u0003ר' יוחנן: מצרי שני שנשא מצרית ראשונה — בנה שני הוי\u0004 \u0005[הוא],\u0006 שבזה הולכים אחר האם ולא אחר האב, אם כן \u0003לתני נמי\u0004 \u0005[שישנה גם כן\u0006 במשנתנו\u0005]\u0006 מקרה כזה:","\u0003מצרי שני שנשא שתי מצריות, אחת ראשונה ואחת שנייה, והיו לו בנים מראשונה ושנייה, אי נסוב כי אורחייהו\u0004 \u0005[אם\u0006 שני אלה הבנים \u0005נשאו כדרכם],\u0006 כלומר, בהיתר, שהאחד שהוא מצרי שלישי נשא בת ישראל המותרת לו, והשני נשא מצרית שניה המותרת לו, הרי הן מאותן ש\u0003מותרות לבעליהן ואסורות ליבמיהן,\u0004 שהמצרי השני אסור ביבמתו הישראלית, והמצרי השלישי דינו כישראל לכל דבר ואסור במצרית שניה.","\u0003ואי איפוך ונסוב\u0004 \u0005[ואם הפכו ונשאו],\u0006 שהמצרי השלישי נשא מצרית שניה והמצרי השני נשא ישראלית — הרי אלו \u0003מותרות ליבמיהן ואסורות לבעליהן.\u0004 וכן \u0003מותרות לאלו ולאלו\u0004 אם נשאו הבנים הללו \u0003גיורות,\u0004 שגם מצרי שני מותר בגיורת, שאינה בכלל \"קהל ה'\". ו\u0003אסורות לאלו ולאלו — אילוניות,\u0004 שאם נשא מצרי שני ישראלית איילונית הריהי אסורה לו משום ישראלית, ולאחיו אסורה משום שהיא איילונית שאין מייבמים אותה. ומאחר שלא שנה דבר זה במשנתנו, משמע שאין הלכה כדברי ר' יוחנן!","ומשיבים: אין מכאן הוכחה להלכה, כי התנא לא שנה במשנתנו את כל המקרים אלא \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 מקרים נוספים. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שייר\u0004 עוד שאתה אומר \u0003דהאי\u0004 \u0005[ש\u0006גם את \u0005זה]\u0006 \u0003שייר?\u0004 ומשיבים: \u0003שייר פצוע דכא,\u0004 שאם הבעל או היבם הוא פצוע דכא, אפשר שיהיו מקרים של אשה האסורה לבעלה ומותרת ליבמה, ולהיפך.","ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום פצוע דכא — לאו שיורא\u0004 \u0005[אין\u0006 זה \u0005שיור],\u0006 \u0003דהא תנא ליה\u0004 \u0005[שהרי שנה אותו]\u0006 כדין כללי של \u0003חייבי לאוין,\u0004 ואף פצוע דכא בכלל זה!","ודוחים: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003חייבי לאוין מי לא קתני והדר תני\u0004 \u0005[האם לא שנה\u0006 בכלל \u0005וחזר\u0006 ו\u0005שנה\u0006 בפרט\u0005]?\u0006 \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 \u0003כהן הדיוט שנשא אלמנה, וחלל שנשא כשרה,\u0004 שהם חייבי לאוין לגבי היבם!","ומשיבים: הקטע \u0003ההוא\u0004 אינו בא כפירוט בלבד של ההלכה הכללית, אלא \u0003איצטריכא ליה לאשמועינן\u0004 \u0005[הוצרך לו\u0006 כדי \u0005להשמיענו]\u0006 על ידו הלכה נוספת \u0003כ\u0004פי שאמר \u0003רב יהודה אמר רב,\u0004 ש\u0003אמר רב יהודה אמר רב: לא הוזהרו\u0004 כהנות \u0003כשרות להנשא לפסולין,\u0004 ומותר לכשרה להינשא לחלל. והלכה זו הוא שבא ללמדנו.","ומקשים: \u0003והא קתני\u0004 \u0005[והרי שנה]\u0006 במשנה גם \u0003חלל שנשא כשרה, וישראל שנשא בת ישראל ויש לו אח ממזר,\u0004 והרי זה פירוט של לאו שאין בו חידוש! ומשיבים: \u0003הא נמי לא מהדר מיתנא היא\u0004 \u0005[גם זה איננו לחזור ולשנות]\u0006 \u0003דאשמועינן\u0004 \u0005[שהשמיע לנו]\u0006 בשתי דוגמאות אלה חידוש, גם \u0003לאו שאין שוה בכל,\u0004 כגון בלאוים שאינם מתייחסים אלא לכהנים, \u0003וקמשמע לן\u0004 \u0005[והשמיע לנו]\u0006 גם \u0003לאו השוה בכל\u0004 כגון ממזר שהוא איסור בין בישראל בין בכהנים.","ומקשים: \u0003הא קתני\u0004 \u0005[הרי\u0006 כבר \u0005שנה]\u0006 \u0003ישראל שנשא ממזרת ויש לו אח ישראל, וממזר שנשא ממזרת ויש לו אח ישראל,\u0004 הרי שלגבי לאו השווה בכל נשנה הדבר כמה פעמים, \u0003אלא לאו שמע מינה\u0004 \u0005[\u0006האם \u0005לא תלמד מכאן]\u0006 כי \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 ולא פירט הכל, ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003גופא\u0004 לגופו של דבר שהזכרנו קודם אגב הדיון. \u0003אמר רב יהודה אמר רב: לא הוזהרו כשרות להנשא לפסולין,\u0004 ומותר להן הדבר אפילו לכתחילה. ומציעים: \u0003לימא, מסייע ליה\u0004 \u0005[\u0006האם \u0005נאמר\u0006 ש\u0005מסייע לו]\u0006 מה ששנינו: \u0003חלל שנשא כשרה, מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ל\u0003כהנת הראויה לו, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"כשרה\" — כשרה לכהונה?\u0004","ודוחים: \u0003לא,\u0004 אפשר לומר שהכוונה היא ל\u0003ישראלית, ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"כשרה\" — כשרה לקהל.\u0004","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 מה ששנינו שם: \u0003יש לו אח כשר נמי,\u0004 \u0005[גם כן]\u0006 עליך לפרש כיוצא בו שמדובר שהוא \u0003כשר לקהל,\u0004 הרי \u0003מכלל\u0004 הדברים אתה למד ש\u0003הוא\u0004 \u0005[שהוא]\u0006 החלל שמת \u0003פסול לקהל?\u0004 והרי חלל הוא רק פסול כהונה! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה שם ודאי ל\u0003כהן\u0004 כשר, \u0003ומ\u0004כיון שבהכרח האח \u0003הוא כהן,\u0004 גם \u0003היא\u0004 האשה ודאי \u0003כהנת!\u0004 ודוחים: \u0003מידי איריא\u0004 \u0005[וכי\u0006 הדברים \u0005שייכים\u0006 זה לזה\u0005]\u0006 — \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא],\u0006 שייתכן ש\"כשר\" האמור בו הוא כהן כשר, והאמור בה משמעו ישראלית כשרה.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבין בר נחמן\u0004 על רב מברייתא ששנינו בה, נאמר: \u0003\"\u0004אשה זונה וחללה \u0003לא יקחו\"\u0004 (ויקרא כא, ז), ונאמר גם: \"ואשה גרושה מאישה \u0003לא יקחו\"\u0004 (שם), ומכפילות זו של \"לא יקחו\" \u0003מלמד שהאשה מוזהרת על ידי האיש,\u0004 כלומר, איסור הנישואין הזה חל לא רק על הכהן שלא לשאת אשה שאסורה עליו, אלא גם על אשה כשרה שלא להינשא לכהן פסול!","\u0003אמר רבא:\u0004 זו אינה קושיה, כי \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003הוא מוזהר\u0004 ואסור — \u0003היא מוזהרת\u0004 ואסור גם לה, אבל \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003הוא לא מוזהר, היא,\u0004 האשה, גם \u0003לא מזדהרא\u0004 \u0005[מוזהרת],\u0006 ולא נאמרה דרשה זו אלא לומר שיש איסור לאו גם על האשה כשהיא פסולה להינשא לכשר, ואכן כשהיא כשירה אינה מוזהרת.","על עצם הדרשה בברייתא שואלים: \u0003והא מהכא נפקא\u0004 \u0005[ו\u0006דבר \u0005זה מכאן יוצא,\u0006 נלמד\u0005]?\u0006 הלא \u0003מ\u0004דבריו של \u0003רב יהודה אמר רב נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]!\u0006 ש\u0003אמר רב יהודה אמר רב, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם מ\u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל\u0004 נאמר: \u0003\"איש או אשה כי יעשו מכל חטאת האדם\"\u0004 (במדבר ה, ו) — הרי \u0003השוה הכתוב\u0004 בפסוק זה \u0003אשה לאיש לכל עונשין שבתורה,\u0004 ואם כן איסורי נישואין חלים על האשה כשם שחלים על האיש! ולשם מה הלימוד הנוסף בענין זה?","ומשיבים: \u0003אי מההיא, הוה אמינא\u0004 \u0005[אם\u0006 רק \u0005מאותו\u0006 פסוק, \u0005הייתי אומר]\u0006 שדבר זה נכון לגבי \u0003לאו השוה בכל, אבל לאו שאינו שוה בכל,\u0004 כגון איסורי הכהנים, \u0003לא,\u0004 שכיון שהלאו הזה מוטל רק על כהנים בלבד ולא על אחרים, שמא אין הלאו חל גם על הנשים, על כן השמיע לנו שאין הדבר כן."],["\u0003והרי\u0004 איסור \u0003טומאה\u0004 של כהנים שהוא \u0003לאו שאין שוה בכל,\u0004 שהרי רק לכהנים אסור להיטמא למת, \u0003וטעמא\u0004 \u0005[והטעם]\u0006 שאנחנו יודעים שאיסור זה ישנו רק בכהנים זכרים, משום \u0003דכתב רחמנא\u0004 \u0005[שכתבה התורה]\u0006 \u0003\"בני אהרן\"\u0004 (\"אמור אל הכהנים בני אהרן... לנפש לא יטמא...\" ויקרא כא, א), ללמוד מכאן: \u0003ולא בנות אהרן, הא לאו הכי, הוה אמינא\u0004 \u0005[הרי לולא כן, הייתי אומר]\u0006 שגם \u0003נשים חייבות\u0004 בו, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 בדבר? \u0003לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 \u0003משום\u0004 שיטת \u0003רב יהודה אמר רב,\u0004 שאיש ואשה שוים לכל עונשים ואיסורים שבתורה ואפילו בלאו שאינו שווה בכל, כמו הלאו של טומאה?","ודוחים: \u0003לא, דגמרינן\u0004 \u0005[שאנו לומדים]\u0006 את הסברה הזו \u0003מ\"לא יקחו\",\u0004 שההנחה הראשונה שמא בנות אהרון חייבות להיזהר מטומאה אינה נלמדת מן ההכללה של רב יהודה אמר רב, אלא דווקא ממה שנאמר \"לא יקחו\" — שלמדים שגם בלאו של איסור כהונה מוזהרות הנשים, ולכן היינו יכולים לחשוב שמא הדבר קיים לא רק בדיני אישות של כהנים אלא לכל דיניהם ובכלל זה איסור טומאה.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 פסוק זה של \u0003קיחה\u0004 (\"לא יקחו\") האמור אצל כהנים \u0003אצטריכא ליה\u0004 \u0005[היה נצרך לו]\u0006 לאומרו במפורש, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003ליגמר\u0004 \u0005[נלמד]\u0006 דין זה \u0003מטומאה,\u0004 שכשם שבטומאה רק בני אהרון הזכרים מצווים — כך בדיני נישואין, חלים האיסורים רק על גברים ולא על נשים, על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 הכתוב \"לא יקחו\" שאינו כן.","ומסופר: \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע איקלעו\u0004 \u0005[הזדמנו]\u0006 \u0003ל\u0004עיר \u0003הינצבו, לאתריה\u0004 \u0005[למקומו]\u0006 של \u0003רב אידי בר אבין, בעו מינייהו\u0004 \u0005[שאלו מהם]\u0006 האם \u0003הוזהרו\u0004 נשים \u0003כשרות\u0004 מ\u0003להנשא לפסולין, או לא?\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא\u0004 בתשובה: \u0003תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 במשנה: \u0003עשרה יוחסין עלו מבבל: כהנים לוים וישראלים, חללים, גרים, וחרורים\u0004 (עבדים משוחררים), \u0003וממזרים, נתינים\u0004 (גבעונים), \u0003שתוקי\u0004 (שידועה זהות אמו ולא זהות אביו), \u0003ואסופי\u0004 (שנאסף מן השוק ואין ידועה לא זהות אביו ולא זהות אמו). \u0003כהנים, לוים\u0004 ו\u0003ישראלים — מותרין לבא זה בזה. לוים, ישראלים, חללים, גרים, חרורים — מותרין לבא זה בזה. גירי, חרורי, וממזרי, נתיני, שתוקי, ואסופי — מותרים לבא זה בזה. ואילו כהנות\u0004 שמותרות \u0003לחלל — לא קתני\u0004 \u0005[שנה],\u0006 משמע שלכהנות אסור להינשא לחללים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 מכאן אין ראיה, כי \u0003כל היכא\u0004 \u0005[מקום]\u0006 \u0003דהני נסבי מהני והני נסבי מהני\u0004 \u0005[שאלה נושאים מאלה ואלה נושאים מאלה] —\u0006 \u0003קתני\u0004 \u0005[שנה],\u0006 שבכל מקום שנאמר שמותרים לבוא זה בזה פירושו שההיתר הוא משני הצדדים, ואילו \u0003כהן, כיון\u0004 ש\u0003אילו בעי למינסב\u0004 \u0005[\u0006היה \u0005רוצה לשאת]\u0006 \u0003חללה\u0004 הלא \u0003אסירא ליה\u0004 \u0005[אסורה לו],\u0006 ולכן \u0003לא קתני\u0004 \u0005[שנה],\u0006 ואין להוכיח מכאן שאסור לכהנות להינשא לחללים. ומסופר: \u0003אתו לקמיה\u0004 \u0005[באו לפני]\u0006 \u0003רב אידי בר אבין\u0004 וסיפרו לו על השאלה ועל הספק שהיה להם. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003דרדקי\u0004 \u0005[ילדים],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב יהודה אמר רב: לא הוזהרו כשרות לינשא לפסולים.\u0004","שנינו במשנה כי \u0003שניות מדברי סופרים\u0004 פעמים שהן אסורות לבעל ופעמים ליבם \u0003וכו'. בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 \u0003בני\u0004 העיר \u0003בירי מרב ששת:\u0004 אשה שהיא \u0003שניה לבעל ולא שניה ליבם,\u0004 האם \u0003יש לה כתובה מיבם או לא?\u0004 ואלה צדדי השאלה: \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שיבמה \u0003כתובתה על נכסי בעלה הראשון,\u0004 וזו כיון שהיא שניה לבעל הלא אין לה כתובה מבעלה, ואם כן \u0003לית לה\u0004 \u0005[אין לה]\u0006 גם מן היבם,","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון\u0004 שכלל אמרו ביבמה ש\u0003אילו לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 אפשרות לגבות כתובתה \u0003מראשון,\u0004 וכגון שלא השאיר נכסים, \u0003תקינו לה רבנן\u0004 \u0005[תיקנו לה חכמים]\u0006 כתובה \u0003משני,\u0004 אם כן, גם זו \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 כתובה מנכסי היבם?","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ששת: תניתוה\u0004 \u0005[\u0006כבר \u0005שניתם אותה]\u0006 בברייתא: יבמה \u0003כתובתה על נכסי בעלה הראשון, ואם היתה שניה לבעל — אפילו מיבם אין לה,\u0004 והרי זה איפוא פתרון מפורש לשאלה.","כיון שנזכרה ברייתא זו, שואלים: \u0003מכלל\u0004 דברי הברייתא יוצא \u0003דאיכא דאית\u0004 \u0005[שיש\u0006 אשה \u0005שיש]\u0006 \u0003לה\u0004 כתובה \u0003מיבם,\u0004 כיצד? ומשיבים: \u0003חסורי מיחסרא, והכי קתני\u0004 \u0005[חסרה\u0006 ברייתא זו, \u0005וכך יש לשנותה]:\u0006 \u0003כתובתה\u0004 של יבמה \u0003על נכסי בעלה הראשון, ואי לית\u0004 \u0005[ואם אין]\u0006 \u0003לה מראשון,\u0004 שלא השאיר נכסים — \u0003תקינו\u0004 \u0005[תיקנו]\u0006 \u0003לה משני. ואם היתה שניה לבעל — אפילו מיבם אין לה.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אלעזר מר' יוחנן: אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט\u0004 וכיוצא בהן, \u0003יש להן מזונות\u0004 מבעליהן \u0003או אין להן מזונות?\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק הדבר]\u0006 \u0003אילימא דיתבה תותיה\u0004 \u0005[אם תאמר ש\u0006היא \u0005יושבת תחתיו],\u0006 שהם חיים עדיין יחד, הלא \u0003ב\"עמוד והוצא\" קאי\u0004 \u0005[עומד\u0006 הוא\u0005]\u0006 שחייב לגרשה, וכי \u0003מזונות אית\u0004 \u0005[יש]\u0006 \u0003לה? לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003שהלך הוא למדינת הים\u0004 מיד, ואיננו כאן שיגרש אותה, \u0003ו\u0004היא \u0003לותה\u0004 בינתיים \u0003ואכלה.\u0004 והשאלה היא זו: \u0003מאי\u0004 \u0005[מה]\u0006 יהיה הדין?","האם נאמר כי \u0003מזוני\u0004 \u0005[מזונות]\u0006 \u0003תנאי כתובה נינהו\u0004 \u0005[הם]\u0006 שהם תנאי בנישואין הנובע וצמוד לכתובה, \u0003מדאית\u0004 \u0005[מ\u0006כיון \u0005שיש]\u0006 \u0003לה כתובה אית\u0004 \u0005[יש]\u0006 \u0003לה\u0004 גם \u0003מזוני\u0004 \u0005[מזונות],\u0006 ולכן היא מקבלת גם מזונות ויצטרך לשלם מה שלוותה, \u0003או דלמא\u0004 \u0005[שמא]\u0006 יש להבדיל: \u0003כתובה דלמשקל ומיפק\u0004 \u0005[ש\u0006היא עשויה \u0005לקחת ולצאת\u0006 ממנו\u0005]\u0006 — \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה,\u0004 שבזה לא רצו חכמים לקונסה, ואולם \u0003מזוני\u0004 \u0005[מזונות]\u0006 שיש לחשוש \u0003דלמא תיעכב גביה\u0004 \u0005[שמא תתעכב אצלו],\u0006 שלא תהיה לה סיבה למהר להתגרש ולכן \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה? אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003לית\u0004 \u0005[אין]\u0006 \u0003לה\u0004 מזונות.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יש לה\u0004 מזונות! ומשיבים: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא\u0004 שיש לה מזונות — הרי זה במזונות שמגיעים לה \u0003לאחר מיתה,\u0004 שהאיסור של היותה עמו כבר אינו קיים, ומכל מקום עדיין עומדת התחייבותו לפרנסה. עד כאן נוסח אחד של הדברים.","\u0003אית\u0004 \u0005[יש]\u0006 מי ש\u0003אמר\u0004 שכך \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 ש\u0003יש לה\u0004 מזונות. והקשה לו: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ב\"עמוד והוצא\" קאי\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 ומדוע יתן לה מזונות? וחזר ושאל: \u0003ואלא התניא\u0004 \u0005[הרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003יש לה?\u0004 ענה לו: \u0003כי תניא\u0004 \u0005[כאשר שנויה\u0006 הברייתא\u0005]\u0006 \u0003ההיא,\u0004 הרי הוא \u0003לאחר מיתה,\u0004 ולא בחייו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אלמנה לכהן גדול, גרושה וחלוצה לכהן הדיוט — יש לה כתובה,\u0004 וכן מחזיר לה את \u0003פירות\u0004 נכסיה, וכן יש לה \u0003מזונות,\u0004 וכן \u0003בלאות\u0004 (של בגדים ונכסים שהכניסה בנדונייתה), \u0003והיא פסולה\u0004 בביאה זו משום חללה, \u0003וולדה פסול\u0004 כחלל, \u0003וכופין אותו להוציא. שניות\u0004 שגזרו \u0003מדברי סופרים — אין לה\u0004 לא \u0003כתובה, לא פירות, לא מזונות, ולא בלאות, והיא כשירה\u0004 לכהונה, \u0003וולדה כשר, וכופין אותו להוציא.\u0004","\u0003אמר ר' שמעון בן אלעזר: מפני מה אמרו אלמנה לכהן גדול יש לה כתובה — מפני שהוא פסול\u0004 על ידי נישואין לה, שכהן שנשא אשה האסורה לו פסול לעבודה עד שיגרשה ויקבל עליו שלא להחזירה, \u0003והיא פסולה\u0004 שמתחללת בביאתו, \u0003וכל מקום שהוא פסול והיא פסולה\u0004"],["\u0003קנסו אותו כתובה,\u0004 כלומר, לא פטרוהו חכמים מלתת לה כתובה, שכיון שיש פסול, הנישואין הללו לא יתקיימו, ולכן לא קנסו אותה להפסיד את כתובתה. \u0003ומפני מה אמרו\u0004 כי \u0003שניות\u0004 שהן אסורות \u0003מדברי סופרים אין להן כתובה — מפני שהוא כשר והיא כשרה,\u0004 ולכן אין להם סיבה להתגרש, \u0003וכל מקום שהוא כשר והיא כשרה, קנסו אותה\u0004 ב\u0003כתובה\u0004 כדי להחיש את גירושיהם.","\u0003רבי אומר\u0004 טעם אחר: \u0003הללו\u0004 כגון אלמנה לכהן גדול וגרושה וחלוצה לכהן הדיוט — \u0003דברי תורה\u0004 הם, \u0003ודברי תורה אין צריכין חיזוק,\u0004 אין עושים להם תקנה מיוחדת כדי לחזקם. \u0003והללו\u0004 השניות מ\u0003דברי סופרים\u0004 הם, \u0003ודברי סופרים צריכין חיזוק\u0004 ולכן קנסוהו יותר. \u0003דבר אחר: זה,\u0004 במקרה ששניהם פסולים — \u0003הוא\u0004 זה ש\u0003מרגילה\u0004 ומושך אותה לחיות עמו, \u0003וזו\u0004 כששניהם כשרים, אף שיש בנישואיהם איסור — \u0003היא מרגילתו,\u0004 ולכן קנסו אותה.","ושואלים: \u0003דבר אחר\u0004 זה, \u0003מאן קתני לה\u0004 \u0005[מי שנה אותה],\u0006 לפי איזו שיטה נאמרו הדברים? \u0003איכא דאמר\u0004 \u0005[יש\u0006 מי \u0005שאומר]\u0006 ש\u0003ר' שמעון בן אלעזר קתני לה\u0004 \u0005[שנה אותה]\u0006 כתוספת לדבריו הקודמים, \u0003ו\u0004בסגנון \u0003מה טעם קאמר\u0004 \u0005[אמר],\u0006 כלומר, \u0003מה טעם אמרו\u0004 שכאשר \u0003הוא פסול והיא פסולה קנסו אותו כתובה — מפני שהוא מרגילה,\u0004 שהרי עיקר הפסול נוגע בעיקר לה, ולכן קנסו אותו שלא ירגילנה. \u0003ומה טעם\u0004 אמרו ש\u0003הוא כשר והיא כשרה קנסו אותה כתובה — מפני שהיא מרגילתו\u0004 שהרי איננה נפסלת על ידי כך, ולא איכפת לה בעבירה, ולכן תיקנו שמפסידה כל זכויותיה.","\u0003איכא דאמר\u0004 \u0005[יש\u0006 מי \u0005שאומר]:\u0006 \u0003רבי קתני לה\u0004 \u0005[שנה אותה]\u0006 כתוספת לדבריו, \u0003ו\u0004כך יש להבין טעמה של תוספת זו, כי \u0003חלוצה\u0004 לכהן \u0003קא קשיא ליה\u0004 \u0005[היה קשה לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חלוצה\u0004 שהיא \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 ולא מן התורה, \u0003ו\u0004בכל זאת \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה כתובה\u0004 ולא עשו חכמים חיזוק לדבריהם! \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר\u0004 טעם אחר: חלוצה לכהן \u0003כיון דפסיל לה מדרבנן\u0004 \u0005[שפוסל אותה\u0006 לכהונה לפחות \u0005מדברי סופרים],\u0006 \u0003זה — הוא מרגילה\u0004 שהוא לא איכפת לו בכך, והיא זו שמעוניינת להתגרש, \u0003וזו\u0004 שניה ששניהם אינם נפסלים — \u0003היא מרגילתו.\u0004","ושואלים: \u0003מאי איכא\u0004 \u0005[מה יש]\u0006 הבדל למעשה \u0003בין רבי לר' שמעון בן אלעזר? אמר רב חסדא:\u0004 לגבי \u0003ממזרת ונתינה לישראל איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה:","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהטעם הוא מפני שהדברים הם \u0003דאורייתא\u0004 \u0005[מן התורה] —\u0006 \u0003הא נמי דאורייתא\u0004 \u0005[זו גם כן מן התורה]\u0006 ולכן מקבלת כתובה, \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מפני שהוא מרגילה — הא\u0004 \u0005[הרי]\u0006 פה \u0003היא מרגלא ליה\u0004 \u0005[מרגילה אותו],\u0006 שהרי הממזרת או הנתינה פסולה בעצמה, והיא מעוניינת להינשא לישראל, שעל ידי כך יש דרך כלשהי במשך הדורות להכשיר את הצאצאים לבוא בקהל, אם יקח בנה הממזר שפחה ויוליד ממנה ילדים שהם עבדים, ואחר כך ישחרר אותם.","ושואלים: \u0003ול\u0004דעת \u0003ר' אליעזר ש\u0004\u0003אמר\u0004 \u0005[שאמר]\u0006 שגם אם נשא ממזר שפחה — \u0003הרי זה\u0004 הילד \u0003עבד וממזר,\u0004 ואם כן, מאחר שאין לה כל תקוה להכשיר את ילדיה, אם כן \u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003לא מרגלא ליה\u0004 \u0005[מרגילה אותו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום]!\u0006 \u0003אלא אמר רב יוסף:\u0004 לגבי \u0003מחזיר גרושה משניסת\u0004 \u0005[משנישאת]\u0006 לאחר \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל להלכה; \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהדבר תלוי אם האיסור הוא \u0003דאורייתא\u0004 \u0005[מן התורה] —\u0006 \u0003הא נמי דאורייתא\u0004 \u0005[זה גם כן מן התורה],\u0006 \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מפני שהוא מרגילה — הא\u0004 \u0005[הרי]\u0006 \u0003היא מרגלא ליה\u0004 \u0005[מרגילה אותו]\u0006 שהרי אין היא וזרעה נפסלים על ידי נישואין אלה.","ושואלים: \u0003ולר' עקיבא,\u0004 ש\u0003אמר\u0004 כי \u0003יש ממזר מחייבי לאוין\u0004 ובכלל זה גם גרושה שחזרה ונישאה לבעלה הראשון לאחר שנישאה לאחר, \u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003לא מרגלא ליה\u0004 \u0005[מרגילה אותו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום],\u0006 שהרי זרעה נפסל בכך! \u0003אלא אמר רב פפא:\u0004 לענין \u0003בעולה לכהן גדול איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, \u0003מאן דאמר דאורייתא\u0004 \u0005[מי שאומר\u0006 שהטעם הוא אם האיסור \u0005מן התורה]\u0006 \u0003הא נמי דאורייתא\u0004 \u0005[זה גם כן מן התורה],\u0006 \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שטעם האיסור הוא \u0003מפני שהוא מרגילה — הא היא מרגלא ליה\u0004 \u0005[זה היא מרגילה אותו],\u0006 שהרי יש כאן רק איסור עשה ואינו פוסל את הילדים.","שואלים: \u0003ול\u0004דעת \u0003ר' אליעזר בן יעקב\u0004 ש\u0003אמר\u0004 ש\u0003יש חלל\u0004 גם \u0003מחייבי עשה,\u0004 כגון בעולה לכהן גדול, \u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003לא מרגלא ליה\u0004 \u0005[מרגילה אותו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום] !\u0006 \u0003אלא אמר רב אשי:\u0004 לענין \u0003מחזיר ספק סוטתו איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל. שאם חשד באשתו שזינתה, וקינא לה, אבל לא הביאה לבית המקדש כדי שתיבדק במים המרים, והמשיך לחיות עימה ועבר על דברי תורה (כי אשה שקינא לה בעלה ונסתרה, אסורה עליו) —","\u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שהטעם הוא אם הדבר אסור \u0003דאורייתא\u0004 \u0005[מן התורה] —\u0006 \u0003הא נמי דאורייתא\u0004 \u0005[זה גם כן מן התורה],\u0006 \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שהטעם הוא \u0003מפני שהוא מרגילה — הא\u0004 \u0005[זה]\u0006 \u0003היא מרגלא ליה\u0004 \u0005[מרגילה אותו],\u0006 שהרי היא איננה נפסלת בכך, ולא איכפת לה. ושואלים: \u0003ולר' מתיא בן חרש ש\u0004\u0003אמר: אפילו הלך בעלה להשקותה, ובא עליה בדרך — עשאה זונה,\u0004 ואם כן פסל אותה לכהונה, \u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003לא מרגלא ליה\u0004 \u0005[מרגילה אותו]\u0006 \u0003ולא מידי\u0004 \u0005[כלום]\u0006 שהרי היא נפסלת בכך! \u0003אלא אמר מר בר רב אשי\u0004 ב\u0003סוטה ודאי איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל, שאם זנתה אשתו — הריהי אסורה עליו, אבל הכל מודים שהילדים הנולדים ממנה אינם ממזרים, ולכן היא מרגילה אותו, למרות שהדבר אסור מן התורה.","\u0003בת ישראל\u0004 שהיא \u0003מאורסת לכהן,\u0004 או שהיא \u0003מעוברת מכהן\u0004 ומת, או שהיא \u0003שומרת יבם לכהן. וכן בת כהן\u0004 שהיתה מאורסת, מעוברת או שומרת יבם \u0003לישראל — לא תאכל בתרומה. בת ישראל\u0004 שהיתה \u0003מאורסת ללוי,\u0004 או \u0003מעוברת מלוי,\u0004 או \u0003שומרת יבם ללוי, וכן בת לוי\u0004 מאורסת, מעוברת או שומרת יבם \u0003לישראל — לא תאכל במעשר\u0004 ראשון.","\u0003בת לוי\u0004 שהיתה \u0003מאורסת לכהן,\u0004 או שהיתה \u0003מעוברת מכהן\u0004 או \u0003שומרת יבם לכהן, וכן בת כהן ללוי — לא תאכל לא בתרומה ולא במעשר.\u0004 לפי הכלל שהאירוסין, העובר והיבם, יפה כוחם לפסול מאכילת תרומה אם היא בת כהן, ולא להאכיל כשבעלה כהן.","שנינו במשנה שבת ישראל המאורסת ללוי לא תאכל במעשר, ותוהים: \u0003ותהא\u0004 אפילו \u0003זרה\u0004 גמורה, \u0003זרה מי לא אכלה\u0004 \u0005[האם איננה אוכלת]\u0006 \u0003במעשר?!\u0004 הרי במעשר אין קדושה, והוא רק רכושו של הלוי, ומה ההבדל אם היא לויה או איננה לויה? ומשיבים, \u0003אמר רב נחמן אמר שמואל: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: מעשר ראשון אסור\u0004 באכילה \u0003לזרים. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006"]]};
